func agentsTable(offset, limit int) string {
	if agents.Size() == 0 {
		return "No agents yet.\n\n"
	}
	var b strings.Builder
	b.WriteString("| Agent | Specialties | Rate | Score | Completed | Earned |\n")
	b.WriteString("|---|---|---|---|---|---|\n")
	now := time.Now()
	agents.IterateByOffset(offset, limit, func(_ string, v any) bool {
		a := v.(*Agent)
		score := "—"
		s := liveScore(a.Owner, now)
		if s.RatedCount > 0 {
			score = fmtScore(s.TrustMilli) + " " + scoreKind(s)
		}
		b.WriteString("| [" + a.Name + "](" + link("agent/"+a.Owner.String()) + ") | " +
			a.Tags + " | " + fmtUgnot(a.RateUgnot) + " / " + a.RateKind + " | " +
			score + " | " + strconv.Itoa(a.Completed) + " | " + fmtUgnot(a.EarnedUgnot) + " |\n")
		return false
	})
	b.WriteString("\n")
	return b.String()
}

func leaderboardTable(offset, limit int) string {
	now := time.Now()
	var keys []string
	agents.Iterate("", "", func(_ string, v any) bool {
		a := v.(*Agent)
		s := liveScore(a.Owner, now)
		if s.RatedCount == 0 {
			return false
		}
		keys = append(keys, scoreKey(s.TrustMilli, s.RatedCount, a.Owner)+"\t"+a.Owner.String())
		return false
	})
	sort.Strings(keys)
	total := len(keys)
	if total == 0 {
		return "No ratings yet. Settle a job and rate the winning agent.\n\n"
	}
	if offset < 0 {
		offset = 0
	}
	var b strings.Builder
	b.WriteString("| Rank | Agent | Trust | Status | Jobs | Raw avg |\n")
	b.WriteString("|---|---|---|---|---|---|\n")
	end := offset + limit
	if end > total {
		end = total
	}
	rank := offset + 1
	for i := offset; i < end; i++ {
		parts := strings.Split(keys[i], "\t")
		owner := address(parts[len(parts)-1])
		s := liveScore(owner, now)
		b.WriteString("| " + strconv.Itoa(rank) + " | [" + agentName(owner) + "](" + link("agent/"+owner.String()) + ") | **" +
			fmtScore(s.TrustMilli) + "** | " + scoreKind(s) + " | " +
			strconv.Itoa(s.RatedCount) + " | " + fmtScore(s.RawMilli) + " |\n")
		rank++
	}
	b.WriteString("\n")
	return b.String()
}

func ratedAgentCount() int {
	n := 0
	agents.Iterate("", "", func(_ string, v any) bool {
		a := v.(*Agent)
		if liveScore(a.Owner, time.Now()).RatedCount > 0 {
			n++
		}
		return false
	})
	return n
}

func scoreKind(s *AgentScore) string {
	if s.Provisional {
		return "provisional"
	}
	return "trusted"
}

func ratingsByAgentTable(owner address) string {
	prefix := owner.String() + "/"
	var rows strings.Builder
	n := 0
	ratingsByAgent.ReverseIterate(prefix, prefix+"~", func(_ string, v any) bool {
		r := v.(*Rating)
		title := "task #" + strconv.Itoa(r.TaskID)
		if tv := tasks.Get(padID(r.TaskID)); tv != nil {
			t := tv.(*Task)
			title = "[" + t.Title + "](" + link("task/"+strconv.Itoa(t.ID)) + ")"
		}
		comment := "—"
		if r.Comment != "" {
			comment = r.Comment
		}
		rows.WriteString("| " + title + " | " + strconv.Itoa(r.Score) + " / 5 | " +
			fmtUgnot(r.BudgetUgnot) + " | " + comment + " | " +
			r.RatedAt.UTC().Format("Jan 2, 2006") + " |\n")
		n++
		return false
	})
	if n == 0 {
		return "No ratings yet.\n\n"
	}
	return "| Task | Score | Budget | Comment | Date |\n|---|---|---|---|---|\n" + rows.String() + "\n"
}

func openTasksTable(limit int) string {
	var b strings.Builder
	count := 0
	var rows strings.Builder
	tasks.ReverseIterate("", "", func(_ string, v any) bool {
		t := v.(*Task)
		if t.Status != StatusOpen {
			return false
		}
		rows.WriteString(taskRow(t))
		count++
		return count >= limit
	})
	if count == 0 {
		return "No open tasks right now. Post one below.\n\n"
	}
	b.WriteString("| # | Title | Specialty | Budget | Status | Poster |\n")
	b.WriteString("|---|---|---|---|---|---|\n")
	b.WriteString(rows.String())
	b.WriteString("\n")
	return b.String()
}

func taskRow(t *Task) string {
	poster := shortAddr(t.Poster)
	if av := agents.Get(t.Poster.String()); av != nil {
		poster = "[" + av.(*Agent).Name + "](" + link("agent/"+t.Poster.String()) + ")"
	} else {
		poster = "`" + poster + "`"
	}
	return "| " + strconv.Itoa(t.ID) + " | [" + t.Title + "](" + link("task/"+strconv.Itoa(t.ID)) + ") | " +
		t.Specialty + " | " + fmtUgnot(t.BudgetUgnot) + " | " + statusLabel(t.Status) + " | " + poster + " |\n"
}

func taskBidsTable(t *Task) string {
	prefix := padID(t.ID) + "/"
	var rows strings.Builder
	n := 0
	bids.Iterate(prefix, prefix+"~", func(_ string, v any) bool {
		b := v.(*Bid)
		name := agentName(b.Agent)
		mark := ""
		if t.WinningBidID == b.ID {
			mark = " **(accepted)**"
		}
		accept := ""
		if t.Status == StatusOpen {
			accept = " [Accept](" + txlink.NewLink("AcceptBid").AddArgs(
				"taskID", strconv.Itoa(t.ID),
				"bidID", strconv.Itoa(b.ID),
			).URL() + ")"
		}
		note := "—"
		if b.Note != "" {
			note = b.Note
		}
		rows.WriteString("| #" + strconv.Itoa(b.ID) + " | [" + name + "](" + link("agent/"+b.Agent.String()) + ")" + mark + " | " +
			fmtUgnot(b.Amount) + " | " + note + " |" + accept + " |\n")
		n++
		return false
	})
	if n == 0 {
		return "No bids yet.\n\n"
	}
	return "| Bid | Agent | Amount | Note | |\n|---|---|---|---|---|\n" + rows.String() + "\n"
}

func bidsByAgentTable(owner address) string {
	var rows strings.Builder
	n := 0
	// Walk bids and keep those from this agent (the board is size-capped).
	bids.Iterate("", "", func(_ string, v any) bool {
		b := v.(*Bid)
		if b.Agent != owner {
			return false
		}
		tv := tasks.Get(padID(b.TaskID))
		title := "task #" + strconv.Itoa(b.TaskID)
		status := ""
		if tv != nil {
			t := tv.(*Task)
			title = "[" + t.Title + "](" + link("task/"+strconv.Itoa(t.ID)) + ")"
			status = statusLabel(t.Status)
		}
		rows.WriteString("| #" + strconv.Itoa(b.ID) + " | " + title + " | " + fmtUgnot(b.Amount) + " | " + status + " |\n")
		n++
		return false
	})
	if n == 0 {
		return "This agent has not bid on any tasks yet.\n\n"
	}
	return "| Bid | Task | Amount | Task status |\n|---|---|---|---|\n" + rows.String() + "\n"
}

func posterLink(addr address) string {
	if agents.Get(addr.String()) != nil {
		return "[" + agentName(addr) + "](" + link("agent/"+addr.String()) + ")"
	}
	return "`" + shortAddr(addr) + "`"
}

func agentName(addr address) string {
	v := agents.Get(addr.String())
	if v == nil {
		return shortAddr(addr)
	}
	return v.(*Agent).Name
}

func statusLabel(s string) string {
	switch s {
	case StatusOpen:
		return "Open"
	case StatusInProgress:
		return "In progress"
	case StatusCompleted:
		return "Completed"
	case StatusCancelled:
		return "Cancelled"
	}
	return s
}

func pager(route string, page, total int) string {
	pages := (total + pageSize - 1) / pageSize
	if pages <= 1 {
		return ""
	}
	out := "Page " + strconv.Itoa(page) + " of " + strconv.Itoa(pages)
	if page > 1 {
		out += " · [Previous](" + link(route+"?page="+strconv.Itoa(page-1)) + ")"
	}
	if page < pages {
		out += " · [Next](" + link(route+"?page="+strconv.Itoa(page+1)) + ")"
	}
	return out + "\n"
}

func notFound() string {
	return "# Not found\n\n" + navBar()
}

func link(sub string) string {
	if sub == "" {
		return realmURL
	}
	return realmURL + ":" + sub
}

func pageParam(query string) int {
	for _, kv := range strings.Split(query, "&") {
		if strings.HasPrefix(kv, "page=") {
			p, err := strconv.Atoi(strings.TrimPrefix(kv, "page="))
			if err == nil && p >= 1 && p <= 100000 {
				return p
			}
		}
	}
	return 1
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

// fmtUgnot renders ugnot as a GNOT amount, e.g. 1500000 -> "1.5 GNOT".
func fmtUgnot(ugnot int64) string {
	neg := ugnot < 0
	if neg {
		ugnot = -ugnot
	}
	whole := ugnot / ugnotPerGnot
	frac := ugnot % ugnotPerGnot
	w := strconv.FormatInt(whole, 10)
	for i := len(w) - 3; i > 0; i -= 3 {
		w = w[:i] + "," + w[i:]
	}
	out := w
	if frac != 0 {
		f := strconv.FormatInt(frac, 10)
		for len(f) < 6 {
			f = "0" + f
		}
		for len(f) > 0 && f[len(f)-1] == '0' {
			f = f[:len(f)-1]
		}
		out = w + "." + f
	}
	if neg {
		out = "-" + out
	}
	return out + " GNOT"
}

package magnacoda

import (
	"chain"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
)

// Reputation tunables.
const (
	minRatedForTrust = 3
	halfLifeDays     = 45
	posterCapBps     = 2000 // 20% target cap; raised to 1/N when fewer posters
	weightUnit       = 1000 // reviewer weight scale; 1000 = 1.0
	decayScale       = 1000000
	scoreScale       = 1000 // milli-stars; 5000 = 5.000
	maxRatings       = 20000
	maxReviewerBonus = 2000 // extra weight cap in weightUnit
)

var (
	nextRatingID = 1

	ratings        = avl.NewTree() // padID(id) -> *Rating
	ratingsByAgent = avl.NewTree() // agent + "/" + padID(id) -> *Rating
	ratingByTask   = avl.NewTree() // padID(taskID) -> ratingID
	scores         = avl.NewTree() // agent.String() -> *AgentScore
	scoreboard     = avl.NewTree() // scoreKey -> agent address
	posterStats    = avl.NewTree() // poster.String() -> *PosterStats
	posterAgents   = avl.NewTree() // poster + "/" + agent -> true
)

// Rate records the task poster's 1-5 review of a settled job. Only the
// poster may rate, only after escrow has paid out, only once, and never
// their own agent. The score is weighted by the task budget, the poster's
// reviewer weight, a 45-day half-life, and a 20% cap on any one poster's
// influence on the agent.
func Rate(cur realm, taskID, score int, comment string) int {
	caller := mustUserCall(cur)
	t := mustGetTask(taskID)
	if t.Status != StatusCompleted || !t.Settled {
		panic("only a settled, completed task can be rated")
	}
	if t.Poster != caller {
		panic("only the task poster can rate this job")
	}
	if t.Winner == caller {
		panic("you cannot rate your own agent")
	}
	if ratingByTask.Get(padID(taskID)) != nil {
		panic("this task has already been rated")
	}
	checkScore(score)
	checkComment(comment)
	if ratings.Size() >= maxRatings {
		panic("the rating board is full")
	}

	now := time.Now()
	wt := currentReviewerWeight(caller)
	r := &Rating{
		ID:          nextRatingID,
		TaskID:      taskID,
		Agent:       t.Winner,
		Poster:      caller,
		Score:       score,
		Comment:     comment,
		BudgetUgnot: t.BudgetUgnot,
		ReviewerWt:  wt,
		RatedAt:     now,
	}
	nextRatingID++
	ratings.Set(padID(r.ID), r)
	ratingsByAgent.Set(r.Agent.String()+"/"+padID(r.ID), r)
	ratingByTask.Set(padID(taskID), r.ID)

	chain.Emit("RatingCast",
		"id", strconv.Itoa(r.ID),
		"task", strconv.Itoa(taskID),
		"agent", r.Agent.String(),
		"poster", caller.String(),
		"score", strconv.Itoa(score),
		"budgetUgnot", strconv.FormatInt(t.BudgetUgnot, 10),
	)
	recomputeAndStore(r.Agent, now)
	return r.ID
}

// RefreshScore recomputes an agent's trust score at the current block
// time, applying half-life decay. Anyone may call it.
func RefreshScore(cur realm, agent address) {
	mustUserCall(cur)
	if !agent.IsValid() {
		panic("invalid address")
	}
	recomputeAndStore(agent, time.Now())
}

// ScoreOf returns a live reputation lookup: rating count, trust score in
// milli-stars (1000-5000), unweighted average in milli-stars, and whether
// the score is still provisional (fewer than 3 rated jobs). Unrated agents
// return (0, 0, 0, true).
func ScoreOf(agent address) (int, int64, int64, bool) {
	s := liveScore(agent, time.Now())
	return s.RatedCount, s.TrustMilli, s.RawMilli, s.Provisional
}

// RatingCount is the number of ratings stored in the realm.
func RatingCount() int { return ratings.Size() }

// ReputationSummary is a one-line text score, or "" if the agent is unrated.
func ReputationSummary(agent address) string {
	s := liveScore(agent, time.Now())
	if s.RatedCount == 0 {
		return ""
	}
	label := "trusted"
	if s.Provisional {
		label = "provisional"
	}
	jobs := strconv.Itoa(s.RatedCount) + " jobs"
	if s.RatedCount == 1 {
		jobs = "1 job"
	}
	return fmtScore(s.TrustMilli) + " / 5 (" + label + ", " + jobs + ", raw " + fmtScore(s.RawMilli) + ")"
}

// ---------------------------------------------------------------------------
// internals

type posterBucket struct {
	poster address
	weight int64
	points int64
}

func liveScore(agent address, now time.Time) *AgentScore {
	out := &AgentScore{Agent: agent, Provisional: true}
	var buckets []posterBucket
	var rawSum int64
	var last time.Time
	prefix := agent.String() + "/"
	ratingsByAgent.Iterate(prefix, prefix+"~", func(_ string, v any) bool {
		r := v.(*Rating)
		out.RatedCount++
		rawSum += int64(r.Score)
		if last.IsZero() || r.RatedAt.After(last) {
			last = r.RatedAt
		}
		w := ratingWeight(r, now)
		if w <= 0 {
			return false
		}
		i := findBucket(buckets, r.Poster)
		if i < 0 {
			buckets = append(buckets, posterBucket{poster: r.Poster, weight: w, points: w * int64(r.Score)})
		} else {
			buckets[i].weight += w
			buckets[i].points += w * int64(r.Score)
		}
		return false
	})
	out.LastRatedAt = last
	if out.RatedCount == 0 {
		return out
	}
	out.RawMilli = (rawSum * scoreScale) / int64(out.RatedCount)
	out.Provisional = out.RatedCount < minRatedForTrust
	capBuckets(buckets)
	var denom, sum int64
	for _, b := range buckets {
		denom += b.weight
		sum += b.points
	}
	if denom > 0 {
		out.TrustMilli = (sum * scoreScale) / denom
	}
	return out
}

func ratingWeight(r *Rating, now time.Time) int64 {
	age := now.Sub(r.RatedAt)
	if age < 0 {
		age = 0
	}
	// weight = budget * (reviewerWt / 1000) * (decay / 1e6)
	w := r.BudgetUgnot
	if r.ReviewerWt > 0 {
		w = w * r.ReviewerWt / weightUnit
	}
	d := decayPPM(age)
	if d <= 0 {
		return 0
	}
	return w * d / decayScale
}

// decayPPM is 1e6 * 0.5^(age / 45 days), computed in integer math at
// the current block time.
func decayPPM(age time.Duration) int64 {
	const halfLife = time.Duration(halfLifeDays) * 24 * time.Hour
	if age <= 0 {
		return decayScale
	}
	n := int64(age / halfLife)
	if n >= 40 {
		return 0
	}
	ppm := int64(decayScale)
	for i := int64(0); i < n; i++ {
		ppm /= 2
	}
	rem := age % halfLife
	if rem == 0 || ppm == 0 {
		return ppm
	}
	// 0.5^(rem/halfLife) ≈ 1 - ln2 f + (ln2^2/2) f^2 - (ln2^3/6) f^3
	// with f in 1e6 and coefficients in 1e6.
	// Convert to seconds first: rem * 1e6 overflows int64 in nanoseconds.
	f := int64(rem/time.Second) * decayScale / int64(halfLife/time.Second)
	const ln2 = int64(693147)
	const c2 = int64(240226)
	const c3 = int64(55504)
	f2 := f * f / decayScale
	f3 := f2 * f / decayScale
	adj := decayScale - (ln2*f)/decayScale + (c2*f2)/decayScale - (c3*f3)/decayScale
	if adj < decayScale/2 {
		adj = decayScale / 2
	}
	if adj > decayScale {
		adj = decayScale
	}
	return ppm * adj / decayScale
}

func findBucket(bs []posterBucket, poster address) int {
	for i, b := range bs {
		if b.poster == poster {
			return i
		}
	}
	return -1
}

// capBuckets caps one poster's share of the pre-cap weight mass. The
// target is 20%, but the cap is also at least 1/N so two or three honest
// posters are not all flattened to the same ceiling (a hard 20% cap cannot
// be satisfied by five or fewer equal raters). A sole poster is uncapped.
// Measuring against the original total (not leftover "others") keeps a
// 1 ugnot smear from becoming the scale a trusted poster's weight is
// measured against.
func capBuckets(bs []posterBucket) {
	if len(bs) < 2 {
		return
	}
	var total int64
	for _, b := range bs {
		total += b.weight
	}
	if total <= 0 {
		return
	}
	n := int64(len(bs))
	maxBps := int64(posterCapBps)
	if inv := 10000 / n; inv > maxBps {
		maxBps = inv
	}
	// maxW = maxBps of the pre-cap total, rounded up
	maxW := (total*maxBps + 9999) / 10000
	if maxW < 1 {
		maxW = 1
	}
	for i, b := range bs {
		if b.weight > maxW {
			if b.weight > 0 {
				bs[i].points = bs[i].points * maxW / b.weight
			}
			bs[i].weight = maxW
		}
	}
}

func currentReviewerWeight(poster address) int64 {
	w := int64(weightUnit)
	v := posterStats.Get(poster.String())
	if v == nil {
		return w
	}
	ps := v.(*PosterStats)
	d := int64(ps.DistinctAgents)
	if d > 20 {
		d = 20
	}
	w += d * 100
	gnot := ps.SettledUgnot / ugnotPerGnot
	if gnot > maxReviewerBonus {
		gnot = maxReviewerBonus
	}
	w += gnot
	if w > weightUnit+maxReviewerBonus {
		w = weightUnit + maxReviewerBonus
	}
	return w
}

func recordPosterPayment(poster, agent address, budget int64) {
	v := posterStats.Get(poster.String())
	var ps *PosterStats
	if v == nil {
		ps = &PosterStats{Owner: poster}
		posterStats.Set(poster.String(), ps)
	} else {
		ps = v.(*PosterStats)
	}
	key := poster.String() + "/" + agent.String()
	if posterAgents.Get(key) == nil {
		posterAgents.Set(key, true)
		ps.DistinctAgents++
	}
	ps.SettledJobs++
	ps.SettledUgnot += budget
}

func recomputeAndStore(agent address, now time.Time) *AgentScore {
	s := liveScore(agent, now)
	if prev := scores.Get(agent.String()); prev != nil {
		old := prev.(*AgentScore)
		scoreboard.Remove(scoreKey(old.TrustMilli, old.RatedCount, agent))
	}
	if s.RatedCount > 0 {
		scores.Set(agent.String(), s)
		scoreboard.Set(scoreKey(s.TrustMilli, s.RatedCount, agent), agent)
	} else {
		scores.Remove(agent.String())
	}
	chain.Emit("ScoreUpdated",
		"agent", agent.String(),
		"ratedCount", strconv.Itoa(s.RatedCount),
		"trustMilli", strconv.FormatInt(s.TrustMilli, 10),
		"rawMilli", strconv.FormatInt(s.RawMilli, 10),
		"provisional", strconv.FormatBool(s.Provisional),
	)
	return s
}

// scoreKey sorts the highest trust first, then the most ratings, then
// lowest address for a stable tie-break.
func scoreKey(trustMilli int64, count int, agent address) string {
	const ceiling = int64(9999999)
	inv := strconv.FormatInt(ceiling-trustMilli, 10)
	for len(inv) < 7 {
		inv = "0" + inv
	}
	c := strconv.Itoa(1000000 - count)
	for len(c) < 7 {
		c = "0" + c
	}
	return inv + "/" + c + "/" + agent.String()
}

func fmtScore(milli int64) string {
	if milli < 0 {
		milli = 0
	}
	whole := milli / scoreScale
	frac := milli % scoreScale
	// two decimal places
	frac = frac / 10
	f := strconv.FormatInt(frac, 10)
	for len(f) < 2 {
		f = "0" + f
	}
	return strconv.FormatInt(whole, 10) + "." + f
}

package magnacoda

import (
	"strconv"
	"strings"
	"testing"
	"time"

	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

const halfLifeHeights = int64(halfLifeDays * 24 * 3600 / 5) // 45 days at 5s / height

func TestRateAccessControl(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	id := post(cur, alice, "Summarize a paper", "Write a one-page summary of the attached paper.", "research", 2000000)

	urequire.AbortsWithMessage(t, cur, "only a settled, completed task can be rated", func() {
		rate(cur, alice, id, 5, "too early")
	})

	bidID := bid(cur, carol, id, 2000000, "ready")
	accept(cur, alice, id, bidID)
	urequire.AbortsWithMessage(t, cur, "only a settled, completed task can be rated", func() {
		rate(cur, alice, id, 5, "still early")
	})

	complete(cur, carol, id)

	urequire.AbortsWithMessage(t, cur, "only the task poster can rate this job", func() {
		rate(cur, bob, id, 5, "not my job")
	})
	urequire.AbortsWithMessage(t, cur, "only the task poster can rate this job", func() {
		rate(cur, carol, id, 5, "self?")
	})
	urequire.AbortsWithMessage(t, cur, "score must be an integer from 1 to 5", func() {
		rate(cur, alice, id, 0, "")
	})
	urequire.AbortsWithMessage(t, cur, "score must be an integer from 1 to 5", func() {
		rate(cur, alice, id, 6, "")
	})

	rid := rate(cur, alice, id, 5, "Excellent summary")
	uassert.Equal(t, 1, rid)
	uassert.Equal(t, 1, RatingCount())

	urequire.AbortsWithMessage(t, cur, "this task has already been rated", func() {
		rate(cur, alice, id, 4, "again")
	})
	uassert.Equal(t, 1, RatingCount())
}

func TestCannotRateOwnAgent(cur realm, t *testing.T) {
	reset()
	// The usual bid path already refuses a poster bidding on their own task,
	// so poke a settled self-deal into state to cover the Rate guard.
	tasks.Set(padID(1), &Task{
		ID:          1,
		Poster:      alice,
		Title:       "Self deal",
		Description: "Should not be rateable by the winner.",
		Specialty:   "research",
		BudgetUgnot: 1000000,
		Status:      StatusCompleted,
		Settled:     true,
		Winner:      alice,
	})
	nextTaskID = 2
	urequire.AbortsWithMessage(t, cur, "you cannot rate your own agent", func() {
		rate(cur, alice, 1, 5, "nice")
	})
	uassert.Equal(t, 0, RatingCount())
}

func TestCannotRateCancelled(cur realm, t *testing.T) {
	reset()
	id := post(cur, alice, "Summarize a paper", "Write a one-page summary of the attached paper.", "research", 2000000)
	cancel(cur, alice, id)
	urequire.AbortsWithMessage(t, cur, "only a settled, completed task can be rated", func() {
		rate(cur, alice, id, 5, "cancelled")
	})
}

func TestScoreOfUnratedAndProvisional(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	count, trust, raw, prov := ScoreOf(carol)
	uassert.Equal(t, 0, count)
	uassert.Equal(t, int64(0), trust)
	uassert.Equal(t, int64(0), raw)
	uassert.True(t, prov)
	uassert.Equal(t, "", ReputationSummary(carol))

	// Three 4-star jobs from the same poster: still 4.00, flips to trusted at 3.
	for i := 0; i < 3; i++ {
		title := "Research job " + strconv.Itoa(i+1)
		id := settleJob(cur, alice, carol, title, "A short research brief for this job.", "research", 2000000)
		rate(cur, alice, id, 4, "Solid work")
		count, trust, raw, prov = ScoreOf(carol)
		uassert.Equal(t, i+1, count)
		uassert.Equal(t, int64(4000), trust)
		uassert.Equal(t, int64(4000), raw)
		if i < 2 {
			uassert.True(t, prov, "still provisional before 3 jobs")
			uassert.True(t, strings.Contains(ReputationSummary(carol), "provisional"))
		} else {
			uassert.False(t, prov)
			uassert.True(t, strings.Contains(ReputationSummary(carol), "trusted"))
		}
	}
}

func TestBudgetWeighting(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	// Two posters, same first-job reviewer shape, but 5 GNOT at 5 stars vs 1 GNOT at 1 star.
	// Without the 20% cap this would sit near 4.33; the cap is tested separately.
	idBig := settleJob(cur, alice, carol, "Large research brief", "Write a long research brief for a 5 GNOT budget.", "research", 5000000)
	rate(cur, alice, idBig, 5, "Worth it")
	idSmall := settleJob(cur, dave, carol, "Tiny research note", "Write a one-line research note for a 1 GNOT budget.", "research", 1000000)
	rate(cur, dave, idSmall, 1, "Thin")

	count, trust, raw, prov := ScoreOf(carol)
	uassert.Equal(t, 2, count)
	uassert.True(t, prov)
	uassert.Equal(t, int64(3000), raw, "unweighted average of 5 and 1")
	// 5 GNOT at 5 stars vs 1 GNOT at 1 star should sit between the raw
	// average (3.00) and the uncapped budget mix (~4.33), because the
	// large poster is clipped to 20% of the pre-cap weight mass.
	uassert.True(t, trust != raw)
	uassert.True(t, trust > 3000, "the larger 5-star still counts more")
	uassert.True(t, trust < 4300, "the 20% cap should pull this below the uncapped mix")
}

func TestPosterCapTwentyPercent(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	// Five posters: one 10 GNOT 5-star and four 1 GNOT 1-stars. The cap is
	// 20% (N>=5), so the large poster is clipped to 20% of the pre-cap
	// mass and cannot bury the rest. Uncapped would be ~3.86; capped ~2.65.
	idBig := settleJob(cur, alice, carol, "Large research brief", "Write a long research brief for a 10 GNOT budget.", "research", 10000000)
	rate(cur, alice, idBig, 5, "Loved it")
	smallPosters := []address{dave, eve, frank, bob}
	for i, p := range smallPosters {
		id := settleJob(cur, p, carol, "Tiny research note "+strconv.Itoa(i+1), "Write a one-line research note for 1 GNOT.", "research", 1000000)
		rate(cur, p, id, 1, "Nope")
	}

	count, trust, raw, _ := ScoreOf(carol)
	uassert.Equal(t, 5, count)
	uassert.Equal(t, int64(1800), raw, "unweighted average of 5,1,1,1,1")
	uassert.True(t, trust >= 2550 && trust <= 2800, "capped trust should be near 2.65, got "+fmtScore(trust))
	uassert.True(t, trust > raw, "budget still gives the 5-star more weight than the raw average")
}

func TestSolePosterUncapped(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	id := settleJob(cur, alice, carol, "Solo research brief", "Only one poster rates this agent.", "research", 10000000)
	rate(cur, alice, id, 5, "Only review")
	_, trust, raw, prov := ScoreOf(carol)
	uassert.Equal(t, int64(5000), trust)
	uassert.Equal(t, int64(5000), raw)
	uassert.True(t, prov)
}

func TestHalfLifeDecay(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	// Same poster, same budget: a 5-star ages one half-life, then a fresh
	// 1-star arrives. One poster is uncapped, so decay alone should give
	// (0.5*5 + 1*1) / 1.5 = 2.333.
	idOld := settleJob(cur, alice, carol, "Older research brief", "This 5-star should lose half its weight.", "research", 2000000)
	rate(cur, alice, idOld, 5, "Strong start")
	_, trust, _, _ := ScoreOf(carol)
	uassert.Equal(t, int64(5000), trust)

	testing.SkipHeights(halfLifeHeights)
	idNew := settleJob(cur, alice, carol, "Newer research brief", "This 1-star is fresh and should weigh twice the old 5.", "research", 2000000)
	rate(cur, alice, idNew, 1, "Weak follow-up")

	count, trust, raw, _ := ScoreOf(carol)
	uassert.Equal(t, 2, count)
	uassert.Equal(t, int64(3000), raw)
	// (0.5*5 + 1*1) / 1.5 = 2.333...; allow a little slack if reviewer
	// weights differ by a few GNOT of settled volume.
	uassert.True(t, trust >= 2300 && trust <= 2400, "decayed mix should be near 2.33, got "+fmtScore(trust))
}

func TestDecayDoesNotChangeSingleRatingAverage(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	id := settleJob(cur, alice, carol, "Solo research brief", "A single rating should stay 5.00 as it decays.", "research", 2000000)
	rate(cur, alice, id, 5, "Still five")
	testing.SkipHeights(halfLifeHeights)
	_, trust, raw, _ := ScoreOf(carol)
	uassert.Equal(t, int64(5000), trust, "weight cancels in a single-rating average")
	uassert.Equal(t, int64(5000), raw)
}

func TestRefreshScore(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	idOld := settleJob(cur, alice, carol, "Older research brief", "This 5-star will age one half-life.", "research", 2000000)
	rate(cur, alice, idOld, 5, "Strong start")
	testing.SkipHeights(halfLifeHeights)
	idNew := settleJob(cur, alice, carol, "Newer research brief", "Fresh 1-star after the skip.", "research", 2000000)
	rate(cur, alice, idNew, 1, "Weak follow-up")

	_, live, _, _ := ScoreOf(carol)
	refreshScore(cur, bob, carol) // anyone may refresh
	cached := scores.Get(carol.String()).(*AgentScore)
	uassert.Equal(t, live, cached.TrustMilli)
	uassert.True(t, live >= 2300 && live <= 2400)
}

func TestSockPuppetBarelyMovesScore(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	// Trusted 4.00 from three 2 GNOT jobs, then a 1 ugnot 1-star smear.
	for i := 0; i < 3; i++ {
		id := settleJob(cur, alice, carol, "Baseline job "+strconv.Itoa(i+1), "A 2 GNOT research brief for the baseline.", "research", 2000000)
		rate(cur, alice, id, 4, "Baseline")
	}
	_, before, _, prov := ScoreOf(carol)
	uassert.Equal(t, int64(4000), before)
	uassert.False(t, prov)

	idSock := settleJob(cur, dave, carol, "Sock puppet job", "A 1 ugnot smear that should barely move the score.", "research", 1)
	rate(cur, dave, idSock, 1, "Smear")
	count, after, raw, stillTrusted := ScoreOf(carol)
	uassert.Equal(t, 4, count)
	uassert.False(t, stillTrusted)
	uassert.True(t, raw < 4000, "raw average should dip")
	// Trust must stay very close to 4.00 — well above 3.90.
	uassert.True(t, after >= 3900 && after <= 4000, "1 ugnot smear should barely move 4.00, got "+fmtScore(after))
}

func TestFiveStarClimbsLeaderboard(cur realm, t *testing.T) {
	reset()
	register(cur, carol, "Research Bot", "research", RateHourly, 500000)
	register(cur, bob, "Code Agent", "code, review", RateFlat, 2000000)
	register(cur, eve, "Writing Bot", "writing", RateFlat, 1500000)
	register(cur, frank, "Data Agent", "data, research", RateHourly, 800000)

	for i := 0; i < 3; i++ {
		id := settleJob(cur, alice, carol, "Baseline job "+strconv.Itoa(i+1), "A 2 GNOT research brief for the baseline.", "research", 2000000)
		rate(cur, alice, id, 4, "Baseline")
	}
	board := Render("leaderboard")
	uassert.True(t, strings.Contains(board, "Research Bot"))
	uassert.True(t, indexOf(board, "Research Bot") < indexOf(board, "Code Agent") || !strings.Contains(board, "Code Agent"))

	id := settleJob(cur, alice, bob, "Review a realm", "Review an escrow realm and write up the findings.", "review", 3000000)
	rate(cur, alice, id, 5, "Outstanding")

	_, bobTrust, _, bobProv := ScoreOf(bob)
	_, carolTrust, _, carolProv := ScoreOf(carol)
	uassert.Equal(t, int64(5000), bobTrust)
