package magnacoda

import "time"

// Rate kinds for an agent's listed price.
const (
	RateHourly = "hourly"
	RateFlat   = "flat"
)

// Task statuses. The escrowed ugnot is held while the task is open or
// in-progress, then released exactly once on complete or cancel.
const (
	StatusOpen       = "open"
	StatusInProgress = "in-progress"
	StatusCompleted  = "completed"
	StatusCancelled  = "cancelled"
)

// Agent is a registered worker. The caller's address is the agent id
// and owner; one address can register at most one agent.
type Agent struct {
	Owner        address
	Name         string
	Tags         string // canonical, comma-space separated specialties
	RateKind     string
	RateUgnot    int64
	RegisteredAt time.Time
	Completed    int
	EarnedUgnot  int64
}

// Task is a job posted with an ugnot budget held in escrow by the realm.
type Task struct {
	ID          int
	Poster      address
	Title       string
	Description string
	Specialty   string // required specialty tag
	BudgetUgnot int64
	Status      string
	PostedAt    time.Time

	WinningBidID int
	Winner       address
	AcceptedAt   time.Time
	CompletedAt  time.Time
	Settled      bool // true after payout or refund; prevents double settlement

	// Optional hash-commit settlement. Empty CommitHash means the winning
	// agent may call CompleteTask as usual. When set, they must reveal a
	// preimage of this SHA-256 (lowercase hex) before RevealBy.
	CommitHash string
	RevealBy   time.Time
}

// Bid is one agent's offer on an open task.
type Bid struct {
	ID       int
	TaskID   int
	Agent    address
	Amount   int64 // ugnot, must be > 0 and <= the task budget
	Note     string
	PlacedAt time.Time
}

// Rating is one poster's 1-5 review of a settled job.
type Rating struct {
	ID          int
	TaskID      int
	Agent       address
	Poster      address
	Score       int // 1-5
	Comment     string
	BudgetUgnot int64 // snapshot of the task budget, used as weight
	ReviewerWt  int64 // snapshot of reviewer weight (1000 = 1.0)
	RatedAt     time.Time
}

// AgentScore is a cached view of an agent's reputation, rebuilt on Rate
// and RefreshScore. Queries and Render recompute decay live from ratings.
type AgentScore struct {
	Agent       address
	RatedCount  int
	TrustMilli  int64 // 1000-5000, 0 if unrated
	RawMilli    int64
	Provisional bool
	LastRatedAt time.Time
}

// PosterStats tracks a poster's history, used to grow reviewer weight.
type PosterStats struct {
	Owner          address
	SettledJobs    int
	SettledUgnot   int64
	DistinctAgents int
}

package magnacoda

import (
	"sort"
	"strconv"
	"strings"
)

// Input limits.
const (
	minNameLen      = 3
	maxNameLen      = 48
	minTitleLen     = 3
	maxTitleLen     = 80
	minDescLen      = 3
	maxDescLen      = 280
	maxNoteLen      = 80
	minTagLen       = 2
	maxTagLen       = 24
	maxTags         = 8
	maxTagsInputLen = 200
	maxRateUgnot    = 1000000000000 // 1,000,000 GNOT
	minBudgetUgnot  = 1
	maxBudgetUgnot  = 1000000000000
	ugnotPerGnot    = 1000000
	minScore        = 1
	maxScore        = 5
	maxCommentLen   = 120
	commitHashLen   = 64
	minRevealSecs   = 60
	maxRevealSecs   = 30 * 24 * 60 * 60
)

// isSafeChar is the character whitelist for every free-text field. It keeps
// user-supplied strings from injecting markdown, HTML, gnoweb tags or
// table pipes into Render output, and keeps them single-line.
func isSafeChar(c rune) bool {
	switch {
	case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		return true
	}
	switch c {
	case ' ', '-', '.', ',', '(', ')', '\'', '/', '+', ':', '@', '#', '%', '&', '=':
		return true
	}
	return false
}

// checkText validates a free-text field and panics with a readable message.
func checkText(field, s string, minLen, maxLen int) {
	if len(s) < minLen || len(s) > maxLen {
		panic(field + " must be " + strconv.Itoa(minLen) + "-" + strconv.Itoa(maxLen) + " characters")
	}
	if s[0] == ' ' || s[len(s)-1] == ' ' {
		panic(field + " must not start or end with a space")
	}
	for _, c := range s {
		if !isSafeChar(c) {
			panic(field + " contains an unsupported character: only letters, digits, spaces and - . , ( ) ' / + : @ # % & = are allowed")
		}
	}
}

func checkRateKind(kind string) {
	switch kind {
	case RateHourly, RateFlat:
		return
	}
	panic("rate kind must be one of: hourly, flat")
}

func checkRate(rate int64) {
	if rate < 1 || rate > maxRateUgnot {
		panic("rate must be between 1 and " + strconv.FormatInt(maxRateUgnot, 10) + " ugnot")
	}
}

func checkBudget(budget int64) {
	if budget < minBudgetUgnot || budget > maxBudgetUgnot {
		panic("budget must be between " + strconv.FormatInt(minBudgetUgnot, 10) + " and " + strconv.FormatInt(maxBudgetUgnot, 10) + " ugnot")
	}
}

// checkSpecialty validates a single required specialty tag.
func checkSpecialty(tag string) string {
	normalized := strings.ToLower(strings.TrimSpace(tag))
	checkTag("specialty", normalized)
	return normalized
}

func checkTag(field, tag string) {
	if len(tag) < minTagLen || len(tag) > maxTagLen {
		panic(field + " must be " + strconv.Itoa(minTagLen) + "-" + strconv.Itoa(maxTagLen) + " characters")
	}
	if strings.Contains(tag, ",") {
		panic(field + " must be a single tag, not a comma-separated list")
	}
	if tag[0] == ' ' || tag[len(tag)-1] == ' ' {
		panic(field + " must not start or end with a space")
	}
	for _, c := range tag {
		if !isSafeChar(c) {
			panic(field + " contains an unsupported character: only letters, digits, spaces and - . , ( ) ' / + : @ # % & = are allowed")
		}
	}
}

// parseTags canonicalizes a comma-separated specialty list: lowercased,
// trimmed, unique, sorted, joined with ", ".
func parseTags(raw string) string {
	checkText("tags", raw, minTagLen, maxTagsInputLen)
	parts := strings.Split(raw, ",")
	var tags []string
	for _, p := range parts {
		tag := strings.ToLower(strings.TrimSpace(p))
		if tag == "" {
			continue
		}
		checkTag("tag", tag)
		if containsTag(tags, tag) {
			continue
		}
		tags = append(tags, tag)
		if len(tags) > maxTags {
			panic("an agent can list at most " + strconv.Itoa(maxTags) + " specialty tags")
		}
	}
	if len(tags) == 0 {
		panic("tags must list at least one specialty")
	}
	sort.Strings(tags)
	return strings.Join(tags, ", ")
}

func containsTag(tags []string, tag string) bool {
	for _, t := range tags {
		if t == tag {
			return true
		}
	}
	return false
}

func agentHasSpecialty(agentTags, specialty string) bool {
	for _, t := range strings.Split(agentTags, ", ") {
		if t == specialty {
			return true
		}
	}
	return false
}

func checkScore(score int) {
	if score < minScore || score > maxScore {
		panic("score must be an integer from 1 to 5")
	}
}

func checkComment(comment string) {
	if comment == "" {
		return
	}
	checkText("comment", comment, 1, maxCommentLen)
}

func checkCommitHash(h string) string {
	h = strings.ToLower(h)
	if len(h) != commitHashLen {
		panic("commit hash must be a 64-character hex SHA-256 digest")
	}
	for _, c := range h {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			panic("commit hash must be a 64-character hex SHA-256 digest")
		}
	}
	return h
}

func checkRevealDeadline(secs int64) {
	if secs < minRevealSecs || secs > maxRevealSecs {
		panic("reveal deadline must be between 60 seconds and 30 days")
	}
}

package verdict

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"math/overflow"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/mux/v0"
	"gno.land/p/nt/seqid/v0"
)

var (
	admin               address
	realmAddr           address
	realmPkgPath        string
	defaultBond         int64
	arbiterQuorum       int
	arbiters            avl.Tree // addr.String() -> bool
	nextMarketID        seqid.ID
	markets             avl.Tree // seqid.ID(id).String() -> *market
	claimableBonds      avl.Tree // addr.String() -> int64
	totalCollateral     int64
	totalFeePool        int64
	totalActiveBonds    int64
	totalClaimableBonds int64
	protocolDustPool    int64
	totalVolume         int64
	totalTrades         int64
	resolvedMarketCount int
	router              *mux.Router
)

func init() {
	admin = unsafe.OriginCaller()
	realmAddr = unsafe.CurrentRealm().Address()
	realmPkgPath = unsafe.CurrentRealm().PkgPath()
	defaultBond = DefaultBondAmount
	arbiterQuorum = 1
	arbiters.Set(admin.String(), true)
	router = buildRouter()
}

func requireAdmin(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic("invalid realm")
	}
	if rlm.Previous().Address() != admin {
		panic("admin only")
	}
}

// requireEOAPayment enforces direct MsgCall origin and single-denom ugnot receipt.
func requireEOAPayment(_ int, rlm realm, minAmount int64) int64 {
	if !rlm.IsCurrent() {
		panic("invalid realm")
	}
	if !rlm.Previous().IsUserCall() {
		panic("direct EOA MsgCall required")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != Denom {
		panic("expected single ugnot coin")
	}
	amt := sent[0].Amount
	if amt <= 0 || amt < minAmount {
		panic("insufficient ugnot sent")
	}
	return amt
}

func requireExactEOAPayment(_ int, rlm realm, exactAmount int64) int64 {
	if !rlm.IsCurrent() {
		panic("invalid realm")
	}
	amt := requireEOAPayment(0, rlm, exactAmount)
	if amt != exactAmount {
		panic("exact ugnot amount required")
	}
	return amt
}

func sendUgnot(_ int, rlm realm, to address, amount int64) {
	if !rlm.IsCurrent() {
		panic("invalid realm")
	}
	if amount <= 0 {
		return
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	bnk.SendCoins(rlm.Address(), to, chain.Coins{{Denom: Denom, Amount: amount}})
}

func creditClaimableBond(addr address, amount int64) {
	if amount <= 0 {
		return
	}
	key := addr.String()
	var prev int64
	if raw := claimableBonds.Get(key); raw != nil {
		v, ok := raw.(int64)
		if !ok {
			panic("corrupt claimable bond entry")
		}
		prev = v
	}
	next, ok := overflow.Add64(prev, amount)
	if !ok {
		panic("claimable bond overflow")
	}
	claimableBonds.Set(key, next)

	nextTotal, ok := overflow.Add64(totalClaimableBonds, amount)
	if !ok {
		panic("total claimable bonds overflow")
	}
	totalClaimableBonds = nextTotal
}

func getMarketOrPanic(id uint64) *market {
	if id == 0 {
		panic("market not found")
	}
	raw := markets.Get(seqid.ID(id).String())
	if raw == nil {
		panic("market not found")
	}
	m, ok := raw.(*market)
	if !ok {
		panic("corrupt market entry")
	}
	return m
}

func getPositionTree(m *market) *avl.Tree {
	if m.positions == nil {
		panic("corrupt positions tree")
	}
	return m.positions
}

func getPositionOrNil(m *market, addr address) *position {
	tree := getPositionTree(m)
	raw := tree.Get(addr.String())
	if raw == nil {
		return nil
	}
	pos, ok := raw.(*position)
	if !ok {
		panic("corrupt position entry")
	}
	return pos
}

func getOrCreatePosition(m *market, addr address) *position {
	tree := getPositionTree(m)
	key := addr.String()
	if raw := tree.Get(key); raw != nil {
		pos, ok := raw.(*position)
		if !ok {
			panic("corrupt position entry")
		}
		return pos
	}
	pos := &position{}
	tree.Set(key, pos)
	return pos
}

func pruneEmptyPosition(m *market, addr address, pos *position) {
	if pos.yesShares == 0 && pos.noShares == 0 && pos.lpShares == 0 && pos.pendingFees == 0 && !pos.claimed {
		tree := getPositionTree(m)
		tree.Remove(addr.String())
	}
}

func recordPricePoint(m *market, ts, yesProbBps, volume int64) {
	n := len(m.priceHistory)
	if n > 0 && m.priceHistory[n-1].timestamp == ts {
		m.priceHistory[n-1].yesProbBps = yesProbBps
		m.priceHistory[n-1].volume = volume
		return
	}
	m.priceHistory = append(m.priceHistory, pricePoint{
		timestamp:  ts,
		yesProbBps: yesProbBps,
		volume:     volume,
	})
	if len(m.priceHistory) <= MaxPriceHistory {
		return
	}
	// Downsample evenly while preserving pts[0] (open) and the latest tick.
	compacted := make([]pricePoint, MaxPriceHistory)
	compacted[0] = m.priceHistory[0]
	lastIdx := len(m.priceHistory) - 1
	slots := MaxPriceHistory - 2
	for i := 1; i <= slots; i++ {
		srcIdx := (i * (lastIdx - 1)) / slots
		if srcIdx < 1 {
			srcIdx = 1
		}
		compacted[i] = m.priceHistory[srcIdx]
	}
	compacted[MaxPriceHistory-1] = m.priceHistory[lastIdx]
	m.priceHistory = compacted
}

package verdict

import (
	"encoding/base64"
	"strconv"
	"strings"

	"gno.land/p/nym-verdict001/fpmm"
)

func renderOddsChartMarkdown(pts []pricePoint, yesProbBps int64, status MarketStatus, outcome Outcome) string {
	const (
		width  = 640
		height = 240
		x0     = 48
		x1     = 616
		y0     = 44
		y1     = 204
	)
	plotW := x1 - x0
	plotH := y1 - y0

	yesPct := formatProbPct(yesProbBps)
	noPct := formatProbPct(fpmm.BpsScale - yesProbBps)

	badge := status.String()
	badgeColor := "#10b981"
	if status == StatusProposed {
		badge = "PROPOSED: " + outcome.String()
		badgeColor = "#f59e0b"
	} else if status == StatusDisputed {
		badge = "DISPUTED"
		badgeColor = "#f43f5e"
	} else if status == StatusResolved {
		badge = "RESOLVED: " + outcome.String()
		if outcome == OutcomeNo {
			badgeColor = "#f43f5e"
		} else if outcome == OutcomeInvalid {
			badgeColor = "#94a3b8"
		}
	}

	var poly strings.Builder
	var lastX, lastY int

	n := len(pts)
	if n == 0 {
		y := y0 + ((int(fpmm.BpsScale-yesProbBps) * plotH) / int(fpmm.BpsScale))
		poly.WriteString(strconv.Itoa(x0) + "," + strconv.Itoa(y) + " " + strconv.Itoa(x1) + "," + strconv.Itoa(y))
		lastX, lastY = x1, y
	} else if n == 1 {
		y := y0 + ((int(fpmm.BpsScale-pts[0].yesProbBps) * plotH) / int(fpmm.BpsScale))
		poly.WriteString(strconv.Itoa(x0) + "," + strconv.Itoa(y) + " " + strconv.Itoa(x1) + "," + strconv.Itoa(y))
		lastX, lastY = x1, y
	} else {
		for i := 0; i < n; i++ {
			x := x0 + (i*plotW)/(n-1)
			y := y0 + ((int(fpmm.BpsScale-pts[i].yesProbBps) * plotH) / int(fpmm.BpsScale))
			if i > 0 {
				poly.WriteByte(' ')
			}
			poly.WriteString(strconv.Itoa(x) + "," + strconv.Itoa(y))
			lastX, lastY = x, y
		}
	}

	linePoints := poly.String()
	areaPoints := strconv.Itoa(x0) + "," + strconv.Itoa(y1) + " " + linePoints + " " + strconv.Itoa(x1) + "," + strconv.Itoa(y1)

	y75 := y0 + plotH/4
	y50 := y0 + plotH/2
	y25 := y0 + (3*plotH)/4

	var svg strings.Builder
	svg.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="640" height="240" viewBox="0 0 640 240">`)
	svg.WriteString(`<defs><linearGradient id="yesFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#10b981" stop-opacity="0.38"/><stop offset="100%" stop-color="#10b981" stop-opacity="0.02"/></linearGradient></defs>`)
	svg.WriteString(`<rect x="1" y="1" width="638" height="238" rx="12" fill="#0f172a" stroke="#1e293b" stroke-width="2"/>`)
	svg.WriteString(`<text x="20" y="27" fill="#94a3b8" font-family="ui-monospace,monospace" font-size="11" font-weight="700">VERDICT CPMM  |  ` + badge + `</text>`)
	svg.WriteString(`<text x="616" y="27" text-anchor="end" fill="#34d399" font-family="ui-monospace,monospace" font-size="13" font-weight="700">` + yesPct + ` YES  /  ` + noPct + ` NO</text>`)

	// Gridlines at 75%, 50%, 25%.
	svg.WriteString(`<line x1="48" y1="` + strconv.Itoa(y75) + `" x2="616" y2="` + strconv.Itoa(y75) + `" stroke="#1e293b" stroke-dasharray="4 4"/>`)
	svg.WriteString(`<text x="40" y="` + strconv.Itoa(y75+4) + `" text-anchor="end" fill="#64748b" font-family="ui-monospace,monospace" font-size="10">75%</text>`)
	svg.WriteString(`<line x1="48" y1="` + strconv.Itoa(y50) + `" x2="616" y2="` + strconv.Itoa(y50) + `" stroke="#334155" stroke-dasharray="4 4"/>`)
	svg.WriteString(`<text x="40" y="` + strconv.Itoa(y50+4) + `" text-anchor="end" fill="#94a3b8" font-family="ui-monospace,monospace" font-size="10">50%</text>`)
	svg.WriteString(`<line x1="48" y1="` + strconv.Itoa(y25) + `" x2="616" y2="` + strconv.Itoa(y25) + `" stroke="#1e293b" stroke-dasharray="4 4"/>`)
	svg.WriteString(`<text x="40" y="` + strconv.Itoa(y25+4) + `" text-anchor="end" fill="#64748b" font-family="ui-monospace,monospace" font-size="10">25%</text>`)

	// Baseline axis.
	svg.WriteString(`<line x1="48" y1="204" x2="616" y2="204" stroke="#334155" stroke-width="1"/>`)

	// Probability area & line.
	svg.WriteString(`<polygon points="` + areaPoints + `" fill="url(#yesFill)"/>`)
	svg.WriteString(`<polyline points="` + linePoints + `" fill="none" stroke="#34d399" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>`)

	// Terminal live dot.
	svg.WriteString(`<circle cx="` + strconv.Itoa(lastX) + `" cy="` + strconv.Itoa(lastY) + `" r="7" fill="` + badgeColor + `" fill-opacity="0.25"/>`)
	svg.WriteString(`<circle cx="` + strconv.Itoa(lastX) + `" cy="` + strconv.Itoa(lastY) + `" r="4" fill="#34d399" stroke="#0f172a" stroke-width="1.5"/>`)

	svg.WriteString(`<text x="48" y="224" fill="#64748b" font-family="ui-monospace,monospace" font-size="10">OPEN 50.0%</text>`)
	svg.WriteString(`<text x="616" y="224" text-anchor="end" fill="#64748b" font-family="ui-monospace,monospace" font-size="10">` + strconv.Itoa(n) + ` ON-CHAIN TICKS</text>`)
	svg.WriteString(`</svg>`)

	encoded := base64.StdEncoding.EncodeToString([]byte(svg.String()))
	return "![YES Probability Chart](data:image/svg+xml;base64," + encoded + ")"
}

func renderMiniOddsBarMarkdown(yesProbBps int64) string {
	const totalW = 160
	yesW := (int(yesProbBps) * totalW) / int(fpmm.BpsScale)
	if yesW < 4 {
		yesW = 4
	}
	if yesW > totalW-4 {
		yesW = totalW - 4
	}
	var svg strings.Builder
	svg.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="160" height="14" viewBox="0 0 160 14">`)
	svg.WriteString(`<rect x="0" y="2" width="160" height="10" rx="5" fill="#e11d48"/>`)
	svg.WriteString(`<rect x="0" y="2" width="` + strconv.Itoa(yesW) + `" height="10" rx="5" fill="#10b981"/>`)
	svg.WriteString(`</svg>`)
	encoded := base64.StdEncoding.EncodeToString([]byte(svg.String()))
	return "![Odds](data:image/svg+xml;base64," + encoded + ")"
}

package verdict

import (
	"chain"
	"math/overflow"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nym-verdict001/fpmm"
)

// CreateMarket deploys a new permissionless binary prediction market and seeds
// a 50/50 CPMM liquidity pool with the attached ugnot deposit.
//
// Pass disputeWindowSec = 0 to use DefaultDisputeWindow (3600s).
// EOA-only (`maketx call` with -send >= 100000ugnot).
func CreateMarket(
	cur realm,
	question string,
	description string,
	category string,
	closeTimeUnix int64,
	feeBps int64,
	disputeWindowSec int64,
) uint64 {
	deposit := requireEOAPayment(0, cur, MinInitialLiquidity)
	caller := cur.Previous().Address()

	question = strings.TrimSpace(question)
	description = strings.TrimSpace(description)
	category = strings.TrimSpace(category)

	if len(question) == 0 || len(question) > MaxQuestionLen {
		panic("invalid question length")
	}
	if len(description) > MaxDescriptionLen {
		panic("description too long")
	}
	if len(category) == 0 || len(category) > MaxCategoryLen {
		panic("invalid category length")
	}

	now := time.Now().Unix()
	if closeTimeUnix < now+MinMarketDuration || closeTimeUnix > now+MaxMarketDuration {
		panic("close time out of bounds")
	}
	if disputeWindowSec == 0 {
		disputeWindowSec = DefaultDisputeWindow
	}
	if disputeWindowSec < MinDisputeWindow || disputeWindowSec > MaxDisputeWindow {
		panic("dispute window out of bounds")
	}

	pool, err := fpmm.NewPool(deposit, feeBps)
	if err != nil {
		panic(err.Error())
	}

	nextColl, ok := overflow.Add64(totalCollateral, deposit)
	if !ok {
		panic("total collateral overflow")
	}

	id := uint64(nextMarketID.Next())
	posTree := avl.NewTree()
	posTree.Set(caller.String(), &position{
		lpShares: pool.TotalLP,
	})

	m := &market{
		id:            id,
		question:      question,
		description:   description,
		category:      category,
		creator:       caller,
		createdAt:     now,
		closeTime:     closeTimeUnix,
		disputeWindow: disputeWindowSec,
		bondAmount:    defaultBond,
		pool:          pool,
		collateral:    deposit,
		status:        StatusOpen,
		positions:     posTree,
		priceHistory: []pricePoint{
			{
				timestamp:  now,
				yesProbBps: pool.YesProbBps(),
				volume:     0,
			},
		},
	}

	markets.Set(nextMarketID.String(), m)
	totalCollateral = nextColl

	chain.Emit(
		"MarketCreated",
		"marketId", strconv.FormatUint(id, 10),
		"creator", caller.String(),
		"category", category,
		"closeTime", strconv.FormatInt(closeTimeUnix, 10),
		"feeBps", strconv.FormatInt(feeBps, 10),
		"initialLiquidity", strconv.FormatInt(deposit, 10),
	)
	return id
}

// Buy purchases YES (buyYes=true) or NO (buyYes=false) outcome shares with
// attached ugnot, reverting if fewer than minSharesOut shares are returned.
// EOA-only (`maketx call`).
func Buy(cur realm, marketID uint64, buyYes bool, minSharesOut int64) int64 {
	gross := requireEOAPayment(0, cur, 1)
	caller := cur.Previous().Address()
	m := getMarketOrPanic(marketID)

	now := time.Now().Unix()
	if m.status != StatusOpen || now >= m.closeTime {
		panic("market is closed for trading")
	}

	side := fpmm.SideNo
	if buyYes {
		side = fpmm.SideYes
	}

	nextPool, q, err := m.pool.ApplyBuy(side, gross, minSharesOut)
	if err != nil {
		panic(err.Error())
	}
	nextAcc, err := fpmm.UpdateFeeAccumulator(m.feeAcc, q.Fee, m.pool.TotalLP)
	if err != nil {
		panic(err.Error())
	}

	mColl, ok := overflow.Add64(m.collateral, q.NetCollateral)
	if !ok {
		panic("collateral overflow")
	}
	tColl, ok := overflow.Add64(totalCollateral, q.NetCollateral)
	if !ok {
		panic("total collateral overflow")
	}
	mFee, ok := overflow.Add64(m.feePool, q.Fee)
	if !ok {
		panic("fee pool overflow")
	}
	tFee, ok := overflow.Add64(totalFeePool, q.Fee)
	if !ok {
		panic("total fee pool overflow")
	}
	mVol, ok := overflow.Add64(m.totalVolume, gross)
	if !ok {
		panic("volume overflow")
	}
	tVol, ok := overflow.Add64(totalVolume, gross)
	if !ok {
		panic("total volume overflow")
	}

	pos := getOrCreatePosition(m, caller)
	m.pool = nextPool
	m.feeAcc = nextAcc
	m.collateral = mColl
	totalCollateral = tColl
	m.feePool = mFee
	totalFeePool = tFee
	m.totalVolume = mVol
	totalVolume = tVol
	m.tradeCount++
	totalTrades++

	if buyYes {
		pos.yesShares += q.SharesOut
		m.totalYesOut += q.SharesOut
	} else {
		pos.noShares += q.SharesOut
		m.totalNoOut += q.SharesOut
	}

	recordPricePoint(m, now, q.NewYesProbBps, m.totalVolume)

	chain.Emit(
		"Trade",
		"marketId", strconv.FormatUint(m.id, 10),
		"trader", caller.String(),
		"action", "buy",
		"side", side.String(),
		"collateral", strconv.FormatInt(gross, 10),
		"shares", strconv.FormatInt(q.SharesOut, 10),
		"fee", strconv.FormatInt(q.Fee, 10),
		"yesProbBps", strconv.FormatInt(q.NewYesProbBps, 10),
	)
	return q.SharesOut
}

// Sell sells sharesIn YES or NO shares back to the pool and sends net ugnot
// to the caller, reverting if output is below minCollateralOut.
func Sell(cur realm, marketID uint64, sellYes bool, sharesIn, minCollateralOut int64) int64 {
	caller := cur.Previous().Address()
	m := getMarketOrPanic(marketID)

	now := time.Now().Unix()
	if m.status != StatusOpen || now >= m.closeTime {
		panic("market is closed for trading")
	}
	if sharesIn <= 0 {
		panic("sharesIn must be positive")
	}

	pos := getPositionOrNil(m, caller)
	if pos == nil {
		panic("insufficient shares")
	}
	if sellYes {
		if pos.yesShares < sharesIn {
			panic("insufficient YES shares")
		}
	} else {
		if pos.noShares < sharesIn {
			panic("insufficient NO shares")
		}
	}

	side := fpmm.SideNo
	if sellYes {
		side = fpmm.SideYes
	}

	nextPool, q, err := m.pool.ApplySell(side, sharesIn, minCollateralOut)
	if err != nil {
		panic(err.Error())
	}
	nextAcc, err := fpmm.UpdateFeeAccumulator(m.feeAcc, q.Fee, m.pool.TotalLP)
	if err != nil {
		panic(err.Error())
	}
	if q.GrossCollateral > m.collateral || q.GrossCollateral > totalCollateral {
		panic("insufficient market collateral")
	}
	mFee, ok := overflow.Add64(m.feePool, q.Fee)
	if !ok {
		panic("fee pool overflow")
	}
	tFee, ok := overflow.Add64(totalFeePool, q.Fee)
	if !ok {
		panic("total fee pool overflow")
	}
	mVol, ok := overflow.Add64(m.totalVolume, q.GrossCollateral)
	if !ok {
		panic("volume overflow")
	}
	tVol, ok := overflow.Add64(totalVolume, q.GrossCollateral)
	if !ok {
		panic("total volume overflow")
	}

	// Effects before bank interaction.
	if sellYes {
		pos.yesShares -= sharesIn
		m.totalYesOut -= sharesIn
	} else {
		pos.noShares -= sharesIn
		m.totalNoOut -= sharesIn
	}
	pruneEmptyPosition(m, caller, pos)

	m.pool = nextPool
	m.feeAcc = nextAcc
	m.collateral -= q.GrossCollateral
	totalCollateral -= q.GrossCollateral
	m.feePool = mFee
	totalFeePool = tFee
	m.totalVolume = mVol
	totalVolume = tVol
	m.tradeCount++
	totalTrades++

	recordPricePoint(m, now, q.NewYesProbBps, m.totalVolume)

	sendUgnot(0, cur, caller, q.CollateralOut)

	chain.Emit(
		"Trade",
		"marketId", strconv.FormatUint(m.id, 10),
		"trader", caller.String(),
		"action", "sell",
		"side", side.String(),
		"collateral", strconv.FormatInt(q.CollateralOut, 10),
		"shares", strconv.FormatInt(sharesIn, 10),
		"fee", strconv.FormatInt(q.Fee, 10),
		"yesProbBps", strconv.FormatInt(q.NewYesProbBps, 10),
	)
	return q.CollateralOut
}

// AddLiquidity deposits attached ugnot into the pool proportionally and mints LP shares.
// Any excess shares on the scarcer side of a skewed pool are credited to the caller.
// EOA-only (`maketx call`).
func AddLiquidity(cur realm, marketID uint64, minLPMinted int64) int64 {
	deposit := requireEOAPayment(0, cur, 1)
	caller := cur.Previous().Address()
	m := getMarketOrPanic(marketID)

	now := time.Now().Unix()
	if m.status != StatusOpen || now >= m.closeTime {
		panic("market is closed for liquidity")
	}

	nextPool, q, err := m.pool.ApplyAddLiquidity(deposit, minLPMinted)
	if err != nil {
		panic(err.Error())
	}

	mColl, ok := overflow.Add64(m.collateral, deposit)
	if !ok {
		panic("collateral overflow")
	}
	tColl, ok := overflow.Add64(totalCollateral, deposit)
	if !ok {
		panic("total collateral overflow")
	}

	pos := getOrCreatePosition(m, caller)
	earned := fpmm.ComputePendingLPFee(m.feeAcc, pos.lpShares, pos.feeDebt)
	newLP := pos.lpShares + q.LPMinted
	newDebt, err := fpmm.ComputeLPFeeDebt(m.feeAcc, newLP)
	if err != nil {
		panic(err.Error())
	}

	m.pool = nextPool
	m.collateral = mColl
	totalCollateral = tColl

	pos.pendingFees += earned
	pos.lpShares = newLP
	pos.feeDebt = newDebt

	if q.RefundShares > 0 {
		if q.RefundSide == fpmm.SideYes {
			pos.yesShares += q.RefundShares
			m.totalYesOut += q.RefundShares
		} else if q.RefundSide == fpmm.SideNo {
			pos.noShares += q.RefundShares
			m.totalNoOut += q.RefundShares
		}
	}

	chain.Emit(
		"LiquidityAdded",
		"marketId", strconv.FormatUint(m.id, 10),
		"provider", caller.String(),
		"collateral", strconv.FormatInt(deposit, 10),
		"lpMinted", strconv.FormatInt(q.LPMinted, 10),
		"refundShares", strconv.FormatInt(q.RefundShares, 10),
	)
	return q.LPMinted
}

// RemoveLiquidity burns lpShares, merges balanced reserves into ugnot, harvests
// accrued LP fees, and credits any pool skew excess to the caller's share balance.
func RemoveLiquidity(cur realm, marketID uint64, lpShares int64) (collateralOut, feeOut, yesOut, noOut int64) {
	caller := cur.Previous().Address()
	m := getMarketOrPanic(marketID)

	now := time.Now().Unix()
	if m.status != StatusOpen || now >= m.closeTime {
		panic("market is closed for liquidity")
	}
	if lpShares <= 0 {
		panic("lpShares must be positive")
	}

	pos := getPositionOrNil(m, caller)
	if pos == nil || pos.lpShares < lpShares {
		panic("insufficient LP shares")
	}

	nextPool, q, err := m.pool.ApplyRemoveLiquidity(lpShares)
	if err != nil {
		panic(err.Error())
	}
	if q.CollateralOut > m.collateral || q.CollateralOut > totalCollateral {
		panic("insufficient market collateral")
	}

	earned := fpmm.ComputePendingLPFee(m.feeAcc, pos.lpShares, pos.feeDebt)
	feeOut = pos.pendingFees + earned
	if feeOut > m.feePool {
		feeOut = m.feePool
	}
	if feeOut > totalFeePool {
		feeOut = totalFeePool
	}

	newLP := pos.lpShares - lpShares
	newDebt, err := fpmm.ComputeLPFeeDebt(m.feeAcc, newLP)
	if err != nil {
		panic(err.Error())
	}

	// Effects before bank interaction.
	m.pool = nextPool
	m.collateral -= q.CollateralOut
	totalCollateral -= q.CollateralOut
	m.feePool -= feeOut
	totalFeePool -= feeOut

	pos.pendingFees = 0
	pos.lpShares = newLP
	pos.feeDebt = newDebt
	pos.yesShares += q.YesOut
	pos.noShares += q.NoOut
	m.totalYesOut += q.YesOut
	m.totalNoOut += q.NoOut
	pruneEmptyPosition(m, caller, pos)

	sendUgnot(0, cur, caller, q.CollateralOut+feeOut)

	chain.Emit(
		"LiquidityRemoved",
		"marketId", strconv.FormatUint(m.id, 10),
		"provider", caller.String(),
		"lpBurned", strconv.FormatInt(lpShares, 10),
		"collateralOut", strconv.FormatInt(q.CollateralOut, 10),
		"feeOut", strconv.FormatInt(feeOut, 10),
		"yesOut", strconv.FormatInt(q.YesOut, 10),
		"noOut", strconv.FormatInt(q.NoOut, 10),
	)
	return q.CollateralOut, feeOut, q.YesOut, q.NoOut
}

// ProposeOutcome submits an optimistic outcome proposal (1=YES, 2=NO, 3=INVALID)
// after market closeTime with an exact GNOT bond equal to the market's BondAmount.
// EOA-only (`maketx call`).
func ProposeOutcome(cur realm, marketID uint64, outcome uint8) {
	m := getMarketOrPanic(marketID)
	now := time.Now().Unix()
	if m.status != StatusOpen {
		panic("market is not open for proposal")
	}
	if now < m.closeTime {
		panic("market has not closed yet")
	}
	out := Outcome(outcome)
	if !out.ValidResolution() {
		panic("invalid outcome")
	}

	bond := requireExactEOAPayment(0, cur, m.bondAmount)
	caller := cur.Previous().Address()

	nextBonds, ok := overflow.Add64(totalActiveBonds, bond)
	if !ok {
		panic("active bonds overflow")
	}

	m.status = StatusProposed
	m.proposedOutcome = out
	m.proposer = caller
	m.proposedAt = now
	m.disputeDeadline = now + m.disputeWindow
	m.proposerBond = bond
	totalActiveBonds = nextBonds

	chain.Emit(
		"OutcomeProposed",
		"marketId", strconv.FormatUint(m.id, 10),
		"proposer", caller.String(),
		"outcome", out.String(),
		"bond", strconv.FormatInt(bond, 10),
		"disputeDeadline", strconv.FormatInt(m.disputeDeadline, 10),
	)
}

// DisputeOutcome challenges a proposed outcome within its dispute window by
// posting an equal counter-bond and escalating to the arbiter quorum.
// EOA-only (`maketx call`).
func DisputeOutcome(cur realm, marketID uint64) {
	m := getMarketOrPanic(marketID)
	now := time.Now().Unix()
	if m.status != StatusProposed {
		panic("market has no active proposal")
	}
	if now >= m.disputeDeadline {
		panic("dispute window expired")
	}
	caller := cur.Previous().Address()
	if caller == m.proposer {
		panic("proposer cannot self-dispute")
	}

	bond := requireExactEOAPayment(0, cur, m.bondAmount)

	nextBonds, ok := overflow.Add64(totalActiveBonds, bond)
	if !ok {
		panic("active bonds overflow")
	}

	m.status = StatusDisputed
	m.disputer = caller
	m.disputedAt = now
	m.disputerBond = bond
	m.arbiterQuorum = arbiterQuorum
	m.arbiterVotes = avl.NewTree()
	m.yesVotes = 0
	m.noVotes = 0
	m.invalidVotes = 0
	totalActiveBonds = nextBonds

	chain.Emit(
		"OutcomeDisputed",
		"marketId", strconv.FormatUint(m.id, 10),
		"disputer", caller.String(),
		"bond", strconv.FormatInt(bond, 10),
		"quorum", strconv.Itoa(m.arbiterQuorum),
	)
}

// FinalizeResolution permissionlessly finalizes an unchallenged proposal after
// disputeDeadline and credits the proposer's bond to pull-claimable balance.
func FinalizeResolution(cur realm, marketID uint64) {
	m := getMarketOrPanic(marketID)
	now := time.Now().Unix()
	if m.status != StatusProposed {
		panic("market is not proposed")
	}
	if now < m.disputeDeadline {
		panic("dispute window still active")
	}

	bond := m.proposerBond
	m.proposerBond = 0
	totalActiveBonds -= bond
	creditClaimableBond(m.proposer, bond)

	m.status = StatusResolved
	m.finalOutcome = m.proposedOutcome
	m.resolvedAt = now
	snapshotSettlement(m)

	chain.Emit(
		"MarketResolved",
		"marketId", strconv.FormatUint(m.id, 10),
		"outcome", m.finalOutcome.String(),
		"via", "optimistic",
	)
}

// CastArbiterVote records an arbiter's resolution vote on a disputed market.
// Once a single outcome reaches arbiterQuorum votes, the market resolves and
// the dishonest party's bond is awarded to the honest side via ClaimBonds.
func CastArbiterVote(cur realm, marketID uint64, outcome uint8) {
	arb := cur.Previous().Address()
	if !arbiters.Has(arb.String()) {
		panic("caller is not an arbiter")
	}
	m := getMarketOrPanic(marketID)
	if m.status != StatusDisputed {
		panic("market is not disputed")
	}
	out := Outcome(outcome)
	if !out.ValidResolution() {
		panic("invalid outcome")
	}

	votes := m.arbiterVotes
	if votes == nil {
		panic("corrupt arbiter votes tree")
	}
	if votes.Has(arb.String()) {
		panic("arbiter already voted")
	}

	votes.Set(arb.String(), out)
	var count int
	switch out {
	case OutcomeYes:
		m.yesVotes++
		count = m.yesVotes
	case OutcomeNo:
		m.noVotes++
		count = m.noVotes
	case OutcomeInvalid:
		m.invalidVotes++
		count = m.invalidVotes
	}

	chain.Emit(
		"ArbiterVoted",
		"marketId", strconv.FormatUint(m.id, 10),
		"arbiter", arb.String(),
		"outcome", out.String(),
		"tally", strconv.Itoa(count),
		"quorum", strconv.Itoa(m.arbiterQuorum),
	)

	if count < m.arbiterQuorum {
		return
	}

	pot := m.proposerBond + m.disputerBond
	winner := m.disputer
	if out == m.proposedOutcome {
		winner = m.proposer
	}
	m.proposerBond = 0
	m.disputerBond = 0
	totalActiveBonds -= pot
	creditClaimableBond(winner, pot)

	m.status = StatusResolved
	m.finalOutcome = out
	m.resolvedAt = time.Now().Unix()
	snapshotSettlement(m)

	chain.Emit(
		"MarketResolved",
		"marketId", strconv.FormatUint(m.id, 10),
		"outcome", m.finalOutcome.String(),
		"via", "arbiter_quorum",
		"bondWinner", winner.String(),
	)
}

// ExpireDispute is a permissionless liveness escape hatch: if arbiters fail to
// reach quorum within ArbiterTimeout (7 days), anyone can resolve the market
// as INVALID and refund both bonds to claimableBonds.
func ExpireDispute(cur realm, marketID uint64) {
	m := getMarketOrPanic(marketID)
	if m.status != StatusDisputed {
		panic("market is not disputed")
	}
	now := time.Now().Unix()
	if now < m.disputedAt+ArbiterTimeout {
		panic("arbiter timeout not reached")
	}

	pBond := m.proposerBond
	dBond := m.disputerBond
	m.proposerBond = 0
	m.disputerBond = 0
	totalActiveBonds -= (pBond + dBond)
	creditClaimableBond(m.proposer, pBond)
	creditClaimableBond(m.disputer, dBond)

	m.status = StatusResolved
	m.finalOutcome = OutcomeInvalid
	m.resolvedAt = now
	snapshotSettlement(m)

	chain.Emit(
		"MarketResolved",
		"marketId", strconv.FormatUint(m.id, 10),
		"outcome", OutcomeInvalid.String(),
		"via", "arbiter_timeout",
	)
}

// Claim withdraws a participant's resolved winning share payout, LP share
// redemption, and accrued LP fees using pull-only settlement.
func Claim(cur realm, marketID uint64) int64 {
	caller := cur.Previous().Address()
	m := getMarketOrPanic(marketID)
	if m.status != StatusResolved {
		panic("market is not resolved")
	}

	pos := getPositionOrNil(m, caller)
	if pos == nil {
		panic("no position for caller")
	}
	if pos.claimed {
		panic("already claimed")
	}

	sharePayout, feePayout := computePositionClaim(m, pos)
	totalPayout := sharePayout + feePayout
	if totalPayout <= 0 {
		panic("nothing to claim")
	}
	if sharePayout > m.collateral || sharePayout > totalCollateral {
		panic("insufficient market collateral")
	}
	if feePayout > m.feePool || feePayout > totalFeePool {
		panic("insufficient market fee pool")
	}

	claimedLP := pos.lpShares
	claimedYes := pos.yesShares
	claimedNo := pos.noShares

	// CEI: effects before bank transfer.
	pos.claimed = true
	pos.yesShares = 0
	pos.noShares = 0
	pos.lpShares = 0
	pos.feeDebt = 0
	pos.pendingFees = 0

	m.collateral -= sharePayout
	totalCollateral -= sharePayout
	m.feePool -= feePayout
	totalFeePool -= feePayout
	m.remainingLP -= claimedLP

	switch m.finalOutcome {
	case OutcomeYes:
		m.remainingWinShares -= claimedYes
	case OutcomeNo:
		m.remainingWinShares -= claimedNo
	case OutcomeInvalid:
		m.remainingWinShares -= (claimedYes + claimedNo)
	}

	if m.remainingLP == 0 && m.remainingWinShares == 0 {
		if m.collateral > 0 {
			protocolDustPool += m.collateral
			totalCollateral -= m.collateral
			m.collateral = 0
		}
		if m.feePool > 0 {
			protocolDustPool += m.feePool
			totalFeePool -= m.feePool
			m.feePool = 0
		}
	}

	sendUgnot(0, cur, caller, totalPayout)

	chain.Emit(
		"Claimed",
		"marketId", strconv.FormatUint(m.id, 10),
		"claimer", caller.String(),
		"sharePayout", strconv.FormatInt(sharePayout, 10),
		"feePayout", strconv.FormatInt(feePayout, 10),
		"totalPayout", strconv.FormatInt(totalPayout, 10),
	)
	return totalPayout
}

// ClaimBonds pulls all refunded or won dispute bonds owed to the caller.
func ClaimBonds(cur realm) int64 {
	caller := cur.Previous().Address()
	key := caller.String()
	raw := claimableBonds.Get(key)
	if raw == nil {
		panic("no claimable bonds")
	}
	amt, ok := raw.(int64)
	if !ok {
		panic("corrupt claimable bond entry")
	}
	if amt <= 0 {
		panic("no claimable bonds")
	}

	// CEI: remove before bank transfer.
	claimableBonds.Remove(key)
	totalClaimableBonds -= amt

	sendUgnot(0, cur, caller, amt)

	chain.Emit(
		"BondsClaimed",
		"claimer", caller.String(),
		"amount", strconv.FormatInt(amt, 10),
	)
	return amt
}

// WithdrawDust lets admin sweep integer floor-rounding dust left behind after a
// resolved market's final LP and winner claims complete.
func WithdrawDust(cur realm, to address) int64 {
	requireAdmin(0, cur)
	if !to.IsValid() {
		panic("invalid recipient address")
	}
	amt := protocolDustPool
	if amt <= 0 {
		panic("no protocol dust")
	}
	protocolDustPool = 0
	sendUgnot(0, cur, to, amt)
	chain.Emit(
		"DustWithdrawn",
		"to", to.String(),
		"amount", strconv.FormatInt(amt, 10),
	)
	return amt
}

// TransferAdmin rotates the realm admin address.
func TransferAdmin(cur realm, newAdmin address) {
	requireAdmin(0, cur)
	if !newAdmin.IsValid() {
		panic("invalid admin address")
	}
	oldAdmin := admin
	admin = newAdmin
	chain.Emit(
		"AdminTransferred",
		"oldAdmin", oldAdmin.String(),
		"newAdmin", newAdmin.String(),
	)
}

// AddArbiter adds a dispute-resolution arbiter up to MaxArbiters.
func AddArbiter(cur realm, arb address) {
	requireAdmin(0, cur)
	if !arb.IsValid() {
		panic("invalid arbiter address")
	}
	if arbiters.Has(arb.String()) {
		panic("already an arbiter")
	}
	if arbiters.Size() >= MaxArbiters {
		panic("arbiter cap reached")
	}
	arbiters.Set(arb.String(), true)
	chain.Emit("ArbiterAdded", "arbiter", arb.String())
}

// RemoveArbiter removes an arbiter while keeping at least arbiterQuorum active arbiters.
func RemoveArbiter(cur realm, arb address) {
	requireAdmin(0, cur)
	if !arbiters.Has(arb.String()) {
		panic("not an arbiter")
	}
	if arbiters.Size()-1 < arbiterQuorum || arbiters.Size() <= 1 {
		panic("cannot drop arbiters below quorum")
	}
	arbiters.Remove(arb.String())
	chain.Emit("ArbiterRemoved", "arbiter", arb.String())
}

// SetArbiterQuorum sets the required arbiter vote threshold for future disputes.
func SetArbiterQuorum(cur realm, quorum int) {
	requireAdmin(0, cur)
	if quorum < 1 || quorum > arbiters.Size() {
		panic("quorum out of range")
	}
	arbiterQuorum = quorum
	chain.Emit("ArbiterQuorumUpdated", "quorum", strconv.Itoa(quorum))
}

// SetDefaultBond sets the GNOT bond required for new markets within [MinAllowedBond, MaxAllowedBond].
func SetDefaultBond(cur realm, bond int64) {
	requireAdmin(0, cur)
	if bond < MinAllowedBond || bond > MaxAllowedBond {
		panic("bond amount out of bounds")
	}
	defaultBond = bond
	chain.Emit("DefaultBondUpdated", "bond", strconv.FormatInt(bond, 10))
}

func snapshotSettlement(m *market) {
	m.settlementYes = m.pool.ReserveYes
	m.settlementNo = m.pool.ReserveNo
	m.settlementLP = m.pool.TotalLP
	m.remainingLP = m.pool.TotalLP
	resolvedMarketCount++

	switch m.finalOutcome {
	case OutcomeYes:
		m.remainingWinShares = m.totalYesOut
	case OutcomeNo:
		m.remainingWinShares = m.totalNoOut
	case OutcomeInvalid:
		m.remainingWinShares = m.totalYesOut + m.totalNoOut
	}
}

func computePositionClaim(m *market, pos *position) (sharePayout, feePayout int64) {
	var lpYes, lpNo int64
	if pos.lpShares > 0 {
		var err error
		lpYes, lpNo, err = fpmm.QuoteSettleLP(m.settlementYes, m.settlementNo, m.settlementLP, pos.lpShares)
		if err != nil {
			panic(err.Error())
		}
		earned := fpmm.ComputePendingLPFee(m.feeAcc, pos.lpShares, pos.feeDebt)
		feePayout = pos.pendingFees + earned
	} else {
		feePayout = pos.pendingFees
	}
	if feePayout > m.feePool {
		feePayout = m.feePool
	}

	totalYes := pos.yesShares + lpYes
	totalNo := pos.noShares + lpNo

	switch m.finalOutcome {
	case OutcomeYes:
		sharePayout = totalYes
	case OutcomeNo:
		sharePayout = totalNo
	case OutcomeInvalid:
		sharePayout = (totalYes + totalNo) / 2
	default:
		panic("invalid final outcome")
	}
	return sharePayout, feePayout
}

