	AddArbiter(cross(cur), arb2)
	AddArbiter(cross(cur), arb3)
	SetArbiterQuorum(cross(cur), 2)

	baseClose := time.Now().Unix() + 3600

	// Market 1: 1% fee, optimistic YES resolution.
	testing.SetRealm(testing.NewUserRealm(alice))
	testing.IssueCoins(realmAddr, ugnot(2_000_000))
	testing.SetOriginSend(ugnot(2_000_000))
	m1 := CreateMarket(cross(cur), "Sim Market 1", "Desc 1", "Crypto", baseClose, 100, 120)
	testing.SetOriginSend(nil)

	// Market 2: 2.5% fee, disputed and resolved NO by 2-of-3 arbiters.
	testing.SetRealm(testing.NewUserRealm(bob))
	testing.IssueCoins(realmAddr, ugnot(1_500_000))
	testing.SetOriginSend(ugnot(1_500_000))
	m2 := CreateMarket(cross(cur), "Sim Market 2", "Desc 2", "Policy", baseClose, 250, 120)
	testing.SetOriginSend(nil)

	// Market 3: 0% fee, disputed and resolved INVALID via ExpireDispute timeout.
	testing.SetRealm(testing.NewUserRealm(carol))
	testing.IssueCoins(realmAddr, ugnot(1_000_000))
	testing.SetOriginSend(ugnot(1_000_000))
	m3 := CreateMarket(cross(cur), "Sim Market 3", "Desc 3", "Sports", baseClose, 0, 120)
	testing.SetOriginSend(nil)

	assertGlobalSolvency(t)

	// Phase 1: Interleaved trading and LP ops across all 3 markets.
	traders := []address{alice, bob, carol, dave, eve}
	mids := []uint64{m1, m2, m3}
	seed := uint64(0x517cc1b727220a95)
	nextRand := func() uint64 {
		seed ^= seed << 13
		seed ^= seed >> 7
		seed ^= seed << 17
		return seed
	}

	for step := 0; step < 45; step++ {
		advanceTime(5)
		actor := traders[nextRand()%uint64(len(traders))]
		mid := mids[nextRand()%uint64(len(mids))]
		op := nextRand() % 4

		switch op {
		case 0, 1: // Buy YES or NO
			buyYes := op == 0
			amt := int64(20_000 + (nextRand() % 300_000))
			if _, err := PreviewBuy(mid, buyYes, amt); err != nil {
				continue
			}
			testing.SetRealm(testing.NewUserRealm(actor))
			testing.IssueCoins(realmAddr, ugnot(amt))
			testing.SetOriginSend(ugnot(amt))
			Buy(cross(cur), mid, buyYes, 1)
			testing.SetOriginSend(nil)

		case 2: // Sell held YES or NO shares
			pos := GetPosition(mid, actor)
			sellYes := true
			held := pos.YesShares
			if pos.NoShares > held {
				sellYes = false
				held = pos.NoShares
			}
			if held < 5_000 {
				continue
			}
			sellAmt := held / 2
			if _, err := PreviewSell(mid, sellYes, sellAmt); err != nil {
				continue
			}
			testing.SetRealm(testing.NewUserRealm(actor))
			Sell(cross(cur), mid, sellYes, sellAmt, 1)

		case 3: // Add or partial Remove LP
			pos := GetPosition(mid, actor)
			if pos.LPShares > 200_000 && (nextRand()%2 == 0) {
				burn := pos.LPShares / 4
				if _, err := PreviewRemoveLiquidity(mid, burn); err != nil {
					continue
				}
				testing.SetRealm(testing.NewUserRealm(actor))
				RemoveLiquidity(cross(cur), mid, burn)
			} else {
				amt := int64(50_000 + (nextRand() % 200_000))
				if _, err := PreviewAddLiquidity(mid, amt); err != nil {
					continue
				}
				testing.SetRealm(testing.NewUserRealm(actor))
				testing.IssueCoins(realmAddr, ugnot(amt))
				testing.SetOriginSend(ugnot(amt))
				AddLiquidity(cross(cur), mid, 1)
				testing.SetOriginSend(nil)
			}
		}
		assertGlobalSolvency(t)
	}

	// Phase 2: Advance past closeTime; propose all 3 markets.
	advanceTime(4000)

	testing.SetRealm(testing.NewUserRealm(dave))
	testing.IssueCoins(realmAddr, ugnot(DefaultBondAmount))
	testing.SetOriginSend(ugnot(DefaultBondAmount))
	ProposeOutcome(cross(cur), m1, uint8(OutcomeYes))
	testing.SetOriginSend(nil)

	testing.SetRealm(testing.NewUserRealm(eve))
	testing.IssueCoins(realmAddr, ugnot(DefaultBondAmount))
	testing.SetOriginSend(ugnot(DefaultBondAmount))
	ProposeOutcome(cross(cur), m2, uint8(OutcomeYes)) // Will be overturned to NO
	testing.SetOriginSend(nil)

	testing.SetRealm(testing.NewUserRealm(bob))
	testing.IssueCoins(realmAddr, ugnot(DefaultBondAmount))
	testing.SetOriginSend(ugnot(DefaultBondAmount))
	ProposeOutcome(cross(cur), m3, uint8(OutcomeNo))
	testing.SetOriginSend(nil)

	assertGlobalSolvency(t)

	// Dispute m2 and m3 inside dispute window.
	advanceTime(30)
	testing.SetRealm(testing.NewUserRealm(carol))
	testing.IssueCoins(realmAddr, ugnot(DefaultBondAmount))
	testing.SetOriginSend(ugnot(DefaultBondAmount))
	DisputeOutcome(cross(cur), m2)
	testing.SetOriginSend(nil)

	testing.SetRealm(testing.NewUserRealm(dave))
	testing.IssueCoins(realmAddr, ugnot(DefaultBondAmount))
	testing.SetOriginSend(ugnot(DefaultBondAmount))
	DisputeOutcome(cross(cur), m3)
	testing.SetOriginSend(nil)

	// Arbiter quorum resolves m2 as NO (carol wins 2x bond).
	testing.SetRealm(testing.NewUserRealm(alice))
	CastArbiterVote(cross(cur), m2, uint8(OutcomeNo))
	testing.SetRealm(testing.NewUserRealm(arb2))
	CastArbiterVote(cross(cur), m2, uint8(OutcomeNo))

	// Advance past disputeDeadline -> finalize m1 (YES).
	advanceTime(150)
	testing.SetRealm(testing.NewUserRealm(alice))
	FinalizeResolution(cross(cur), m1)

	// Advance past ArbiterTimeout -> expire m3 (INVALID).
	advanceTime(ArbiterTimeout)
	testing.SetRealm(testing.NewUserRealm(eve))
	ExpireDispute(cross(cur), m3)

	assertGlobalSolvency(t)

	// Phase 3: Every trader claims all claimable bonds and all winning/LP market positions.
	for _, actor := range traders {
		if GetClaimableBonds(actor) > 0 {
			testing.SetRealm(testing.NewUserRealm(actor))
			ClaimBonds(cross(cur))
		}
		for _, mid := range mids {
			pos := GetPosition(mid, actor)
			if pos.EstClaimable > 0 && !pos.Claimed {
				testing.SetRealm(testing.NewUserRealm(actor))
				Claim(cross(cur), mid)
			}
		}
		assertGlobalSolvency(t)
	}

	if protocolDustPool > 0 {
		testing.SetRealm(testing.NewUserRealm(alice))
		WithdrawDust(cross(cur), alice)
	}
	assertDrainedToZero(t)
}

package verdict

import (
	"chain/banker"

	"gno.land/p/nym-verdict001/fpmm"
)

func buildMarketView(m *market) MarketView {
	return MarketView{
		ID:                 m.id,
		Question:           m.question,
		Description:        m.description,
		Category:           m.category,
		Creator:            m.creator,
		CreatedAt:          m.createdAt,
		CloseTime:          m.closeTime,
		DisputeWindow:      m.disputeWindow,
		BondAmount:         m.bondAmount,
		Status:             m.status,
		StatusLabel:        m.status.String(),
		ReserveYes:         m.pool.ReserveYes,
		ReserveNo:          m.pool.ReserveNo,
		TotalLP:            m.pool.TotalLP,
		FeeBps:             m.pool.FeeBps,
		YesProbBps:         m.pool.YesProbBps(),
		NoProbBps:          m.pool.NoProbBps(),
		Collateral:         m.collateral,
		FeePool:            m.feePool,
		TotalYesOut:        m.totalYesOut,
		TotalNoOut:         m.totalNoOut,
		TotalVolume:        m.totalVolume,
		TradeCount:         m.tradeCount,
		ProposedOutcome:    m.proposedOutcome,
		Proposer:           m.proposer,
		ProposedAt:         m.proposedAt,
		DisputeDeadline:    m.disputeDeadline,
		ProposerBond:       m.proposerBond,
		Disputer:           m.disputer,
		DisputedAt:         m.disputedAt,
		DisputerBond:       m.disputerBond,
		FinalOutcome:       m.finalOutcome,
		FinalOutcomeLabel:  m.finalOutcome.String(),
		ResolvedAt:         m.resolvedAt,
		ArbiterQuorum:      m.arbiterQuorum,
		YesVotes:           m.yesVotes,
		NoVotes:            m.noVotes,
		InvalidVotes:       m.invalidVotes,
		RemainingLP:        m.remainingLP,
		RemainingWinShares: m.remainingWinShares,
	}
}

// GetMarket returns a value copy of a market by ID for vm/qeval_json queries.
func GetMarket(marketID uint64) (MarketView, bool) {
	if marketID == 0 {
		return MarketView{}, false
	}
	// Check existence before calling getMarketOrPanic so read queries don't panic.
	m := getMarketOrNil(marketID)
	if m == nil {
		return MarketView{}, false
	}
	return buildMarketView(m), true
}

func getMarketOrNil(id uint64) *market {
	if id == 0 {
		return nil
	}
	// Walk via seqid.ID(id) matching the key convention used on insert.
	raw := markets.Get(seqidKey(id))
	if raw == nil {
		return nil
	}
	m, ok := raw.(*market)
	if !ok {
		panic("corrupt market entry")
	}
	return m
}

// ListMarkets returns up to limit MarketViews in reverse chronological order.
func ListMarkets(offset, limit int) []MarketView {
	if offset < 0 {
		offset = 0
	}
	if limit <= 0 {
		limit = 20
	}
	if limit > MaxPageLimit {
		limit = MaxPageLimit
	}
	out := make([]MarketView, 0, limit)
	markets.ReverseIterateByOffset(offset, limit, func(_ string, val any) bool {
		m, ok := val.(*market)
		if !ok {
			panic("corrupt market entry")
		}
		out = append(out, buildMarketView(m))
		return false
	})
	return out
}

// GetPosition returns a value copy of addr's position in marketID.
func GetPosition(marketID uint64, addr address) PositionView {
	m := getMarketOrNil(marketID)
	if m == nil {
		return PositionView{MarketID: marketID, Address: addr}
	}
	pos := getPositionOrNil(m, addr)
	if pos == nil {
		return PositionView{MarketID: marketID, Address: addr}
	}
	earned := fpmm.ComputePendingLPFee(m.feeAcc, pos.lpShares, pos.feeDebt)
	pendingFees := pos.pendingFees + earned
	if pendingFees > m.feePool {
		pendingFees = m.feePool
	}
	var estClaimable int64
	if m.status == StatusResolved && !pos.claimed {
		sPay, fPay := computePositionClaim(m, pos)
		estClaimable = sPay + fPay
	}
	return PositionView{
		MarketID:     marketID,
		Address:      addr,
		YesShares:    pos.yesShares,
		NoShares:     pos.noShares,
		LPShares:     pos.lpShares,
		PendingFees:  pendingFees,
		EstClaimable: estClaimable,
		Claimed:      pos.claimed,
	}
}

// GetPriceHistory returns a copied slice of probability ticks for marketID.
func GetPriceHistory(marketID uint64) []PricePointView {
	m := getMarketOrNil(marketID)
	if m == nil {
		return nil
	}
	out := make([]PricePointView, len(m.priceHistory))
	for i, pt := range m.priceHistory {
		out[i] = PricePointView{
			Timestamp:  pt.timestamp,
			YesProbBps: pt.yesProbBps,
			Volume:     pt.volume,
		}
	}
	return out
}

// GetClaimableBonds returns the pull-claimable bond balance in ugnot for addr.
func GetClaimableBonds(addr address) int64 {
	raw := claimableBonds.Get(addr.String())
	if raw == nil {
		return 0
	}
	v, ok := raw.(int64)
	if !ok {
		panic("corrupt claimable bond entry")
	}
	return v
}

// GetArbiters returns a deterministic sorted copy of active arbiter addresses.
func GetArbiters() []address {
	out := make([]address, 0, arbiters.Size())
	arbiters.Iterate("", "", func(key string, _ any) bool {
		out = append(out, address(key))
		return false
	})
	return out
}

// GetStats returns protocol-wide accounting totals and live vault balance.
func GetStats() ProtocolStats {
	vaultBal := banker.NewReadonlyBanker().GetCoin(realmAddr, Denom)
	return ProtocolStats{
		Admin:               admin,
		RealmAddress:        realmAddr,
		MarketCount:         markets.Size(),
		ResolvedMarketCount: resolvedMarketCount,
		TotalCollateral:     totalCollateral,
		TotalFeePool:        totalFeePool,
		TotalActiveBonds:    totalActiveBonds,
		TotalClaimableBonds: totalClaimableBonds,
		ProtocolDustPool:    protocolDustPool,
		VaultBalance:        vaultBal,
		TotalVolume:         totalVolume,
		TotalTrades:         totalTrades,
		DefaultBond:         defaultBond,
		ArbiterCount:        arbiters.Size(),
		ArbiterQuorum:       arbiterQuorum,
	}
}

// PreviewBuy returns a stateless buy quote against marketID's live pool.
func PreviewBuy(marketID uint64, buyYes bool, grossCollateral int64) (fpmm.BuyQuote, error) {
	m := getMarketOrPanic(marketID)
	side := fpmm.SideNo
	if buyYes {
		side = fpmm.SideYes
	}
	return m.pool.QuoteBuy(side, grossCollateral)
}

// PreviewSell returns a stateless sell quote against marketID's live pool.
func PreviewSell(marketID uint64, sellYes bool, sharesIn int64) (fpmm.SellQuote, error) {
	m := getMarketOrPanic(marketID)
	side := fpmm.SideNo
	if sellYes {
		side = fpmm.SideYes
	}
	return m.pool.QuoteSell(side, sharesIn)
}

// PreviewAddLiquidity returns a stateless add-liquidity quote against marketID's live pool.
func PreviewAddLiquidity(marketID uint64, collateralIn int64) (fpmm.AddLiquidityQuote, error) {
	m := getMarketOrPanic(marketID)
	return m.pool.QuoteAddLiquidity(collateralIn)
}

// PreviewRemoveLiquidity returns a stateless remove-liquidity quote against marketID's live pool.
func PreviewRemoveLiquidity(marketID uint64, lpShares int64) (fpmm.RemoveLiquidityQuote, error) {
	m := getMarketOrPanic(marketID)
	return m.pool.QuoteRemoveLiquidity(lpShares)
}

// Package core provides shared validation helpers, deterministic identifier
// rules and status vocabulary for the PROOFLOOM protocol realms.
//
// core holds no mutable state: it is a pure library so it can be imported by
// every other PROOFLOOM realm and by external consumer realms without any
// interrealm authority concerns.
package core

import (
	"strings"
)

// Protocol version stamped on every record produced by these realms.
const ProtocolVersion = "1.0.0"

// Release lifecycle statuses. The authoritative state machine is enforced by
// the releases realm; these constants are shared so callers can reference
// states without magic strings.
const (
	ReleaseDraft          = "DRAFT"
	ReleaseEvidencePending = "EVIDENCE_PENDING"
	ReleaseValidating     = "VALIDATING"
	ReleaseReviewRequired = "REVIEW_REQUIRED"
	ReleaseApproved       = "APPROVED"
	ReleasePublished      = "PUBLISHED"
	ReleaseVerified       = "VERIFIED"
	ReleaseRejected       = "REJECTED"
	ReleaseRevoked        = "REVOKED"
	ReleaseSuperseded     = "SUPERSEDED"
	ReleaseDisputed       = "DISPUTED"
)

// Attestation statuses.
const (
	AttestationActive  = "ACTIVE"
	AttestationRevoked = "REVOKED"
	AttestationExpired = "EXPIRED"
)

// Agent statuses.
const (
	AgentActive    = "ACTIVE"
	AgentSuspended = "SUSPENDED"
	AgentRevoked   = "REVOKED"
)

// Agent permission scopes. Permissions are least-privilege and explicitly
// granted; there is no wildcard scope by design.
const (
	AgentScopeRead          = "READ"
	AgentScopeEvidence      = "EVIDENCE"
	AgentScopeVerifyRequest = "VERIFY_REQUEST"
	AgentScopeTaskUpdate    = "TASK_UPDATE"
	AgentScopeReviewPropose = "REVIEW_PROPOSE"
	AgentScopePublishReq    = "PUBLISH_REQUEST"
)

// Attestation subject types.
const (
	SubjectRelease  = "RELEASE"
	SubjectProject  = "PROJECT"
	SubjectComponent = "COMPONENT"
	SubjectTask     = "TASK"
	SubjectExecution = "AGENT_EXECUTION"
)

// Attestation categories supported by the protocol.
const (
	AttestBuild          = "BUILD_PROVENANCE"
	AttestSource         = "SOURCE_PROVENANCE"
	AttestTest           = "TEST_EXECUTION"
	AttestSecurity       = "SECURITY_ASSESSMENT"
	AttestCodeReview     = "CODE_REVIEW"
	AttestReleaseApprove = "RELEASE_APPROVAL"
	AttestAgentTask      = "AGENT_TASK_COMPLETION"
	AttestBenchmark      = "BENCHMARK_RESULT"
	AttestDependency     = "DEPENDENCY_VERIFICATION"
	AttestOwnership      = "OWNERSHIP_VERIFICATION"
	AttestDeployment     = "DEPLOYMENT_VERIFICATION"
	AttestCompliance     = "COMPLIANCE_EVIDENCE"
	AttestIncident       = "INCIDENT_REMEDIATION"
)

// IsValidAddress reports whether a looks like a Gno bech32 user or package
// address (g1-prefixed). It does not checksum-verify; the VM guarantees the
// addresses it hands out, and externally supplied strings must pass this gate
// before being stored.
func IsValidAddress(a string) bool {
	if len(a) != 40 && len(a) != 43 {
		// user addresses are g1 + 38 chars; package addresses vary slightly.
		if len(a) < 10 || len(a) > 64 {
			return false
		}
	}
	if !strings.HasPrefix(a, "g1") {
		return false
	}
	for i := 0; i < len(a); i++ {
		c := a[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
		if !ok {
			return false
		}
	}
	return true
}

// IsValidDigest reports whether d is a plausible sha256 hex digest
// (64 lowercase hex characters).
func IsValidDigest(d string) bool {
	if len(d) != 64 {
		return false
	}
	for i := 0; i < len(d); i++ {
		c := d[i]
		ok := (c >= 'a' && c <= 'f') || (c >= '0' && c <= '9')
		if !ok {
			return false
		}
	}
	return true
}

// IsValidID reports whether id is a safe slug: lowercase letters, digits and
// dashes, 1..64 characters, no leading or trailing dash.
func IsValidID(id string) bool {
	if len(id) == 0 || len(id) > 64 {
		return false
	}
	if id[0] == '-' || id[len(id)-1] == '-' {
		return false
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-'
		if !ok {
			return false
		}
	}
	return true
}

// IsValidSlugList validates a comma-free, whitespace-free list of IDs.
func IsValidSlugList(ids []string) bool {
	for _, id := range ids {
		if !IsValidID(id) {
			return false
		}
	}
	return true
}

// IsValidVersion checks a loose semver-ish version string: digits and dots
// with optional alphanum suffix, 1..32 chars.
func IsValidVersion(v string) bool {
	if len(v) == 0 || len(v) > 32 {
		return false
	}
	for i := 0; i < len(v); i++ {
		c := v[i]
		ok := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' || c == '-' || c == '+'
		if !ok {
			return false
		}
	}
	return true
}

// IsValidShortHash validates git commit-ish strings (7..64 hex chars).
func IsValidShortHash(h string) bool {
	if len(h) < 7 || len(h) > 64 {
		return false
	}
	for i := 0; i < len(h); i++ {
		c := h[i]
		ok := (c >= 'a' && c <= 'f') || (c >= '0' && c <= '9')
		if !ok {
			return false
		}
	}
	return true
}

// BoundedText guards free-form metadata length on-chain to prevent state
// bloat. Nothing longer than maxLen may be persisted.
func BoundedText(s string, maxLen int) bool {
	return len(s) <= maxLen
}

// ComposeReleaseID derives a deterministic release identifier from the
// project ID and version. Release IDs must be reproducible off-chain so
// external consumers can address them without a lookup.
func ComposeReleaseID(projectID, version string) string {
	return projectID + "-" + strings.ToLower(version)
}

// ComposeAttestationID derives a deterministic attestation identifier from
// subject, category and issuer so duplicate attestations from the same issuer
// for the same subject/category are structurally impossible.
func ComposeAttestationID(subjectID, category, issuer string) string {
	return subjectID + "-" + strings.ToLower(category) + "-" + issuer
}

// MaxTextLen is the default cap for persisted free-form text fields.
const MaxTextLen = 512

// MaxListLen caps ID lists persisted on-chain (scopes, required types, ...).
const MaxListLen = 32

package core

import "testing"

func TestIsValidAddress(cur realm, t *testing.T) {
	valid := []string{
		"g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq",
		"g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5",
	}
	for _, a := range valid {
		if !IsValidAddress(a) {
			t.Fatalf("expected valid: %s", a)
		}
	}
	invalid := []string{
		"", "x1abc", "g2pd8esjj02k67reyzquv42lf8tlc4g9nnntashq",
		"G1PD8ESJJ02K67REYZQUV42LF8TLC4G9NNNTASHQ",
		"g1pd8esjj02k67reyzquv42lf8tlc4g9nnntash;key",
		"g1",
	}
	for _, a := range invalid {
		if IsValidAddress(a) {
			t.Fatalf("expected invalid: %q", a)
		}
	}
}

func TestIsValidDigest(cur realm, t *testing.T) {
	good := "a3f5c2d1b0e9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c3d2e1f0a9b8c7d6e5f4a3"
	if !IsValidDigest(good) {
		t.Fatal("expected digest valid")
	}
	if IsValidDigest("a3f5c2d1") {
		t.Fatal("too short must be invalid")
	}
	if IsValidDigest("A3F5C2D1B0E9F8A7B6C5D4E3F2A1B0C9D8E7F6A5B4C3D2E1F0A9B8C7D6E5F4A3") {
		t.Fatal("uppercase must be invalid")
	}
	if IsValidDigest(good[:63] + "g") {
		t.Fatal("non-hex must be invalid")
	}
}

func TestIsValidID(cur realm, t *testing.T) {
	if !IsValidID("my-project") || !IsValidID("core-api") || !IsValidID("a1") {
		t.Fatal("expected valid ids")
	}
	for _, bad := range []string{"", "-x", "x-", "Big", "a b", string(make([]byte, 65))} {
		if IsValidID(bad) {
			t.Fatalf("expected invalid: %q", bad)
		}
	}
}

func TestIsValidVersionAndHash(cur realm, t *testing.T) {
	if !IsValidVersion("1.2.3") || !IsValidVersion("2.0.0-rc.1") {
		t.Fatal("expected versions valid")
	}
	if IsValidVersion("") || IsValidVersion("1 2") {
		t.Fatal("expected versions invalid")
	}
	if !IsValidShortHash("0123abcd") || IsValidShortHash("abc") {
		t.Fatal("short hash validation broken")
	}
}

func TestComposeIDs(cur realm, t *testing.T) {
	if got := ComposeReleaseID("core-api", "1.2.3"); got != "core-api-1.2.3" {
		t.Fatalf("unexpected release id %q", got)
	}
	got := ComposeAttestationID("core-api-1.2.3", "BUILD_PROVENANCE", "g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq")
	want := "core-api-1.2.3-build_provenance-g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq"
	if got != want {
		t.Fatalf("unexpected attestation id %q", got)
	}
}

func TestBoundedText(cur realm, t *testing.T) {
	if !BoundedText("ok", 10) {
		t.Fatal("bounded failed")
	}
	if BoundedText(string(make([]byte, 513)), MaxTextLen) {
		t.Fatal("over-bounded passed")
	}
}

// Package registry is the authoritative on-chain registry of PROOFLOOM
// projects and software components. It is the ownership backbone of the
// protocol: every other realm consults it for authorization decisions.
//
// Security model:
//   - The protocol admin (set once at Init) can only manage registrar
//     allow-lists, never project state owned by users.
//   - Project owners are recorded from cur.Previous().Address() and never
//     from caller-supplied arguments.
//   - Getters return value copies; internal maps and slices are never
//     exposed.
package registry

import (
        "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/core"

        "sort"
        "strings"
        "time"
)

// Project is a registered software project. Owned by the address that
// registered it.
type Project struct {
        ID          string
        Name        string
        Description string
        Repo        string
        Category    string
        Visibility  string // "public" or "private"
        Owner       address
        CreatedAt   int64
        Archived    bool
}

// Component is a software component (package, image, binary, SBOM...)
// associated with a project.
type Component struct {
        ID           string
        ProjectID    string
        Name         string
        License      string
        ArtifactType string // source, container, binary, sbom, docs
        Owner        address
        CreatedAt    int64
        Deprecated   bool
}

var (
        projects   map[string]*Project
        components map[string]*Component

        admin      address
        registrars map[string]bool // addresses allowed to register projects
)

// projectIDs preserves registration order for deterministic listing.
var projectIDs []string
var componentIDs []string

func mustAdmin(cur realm) {
        if cur.Previous().Address() != admin {
                panic("registry: caller is not protocol admin")
        }
        if !cur.IsCurrent() {
                panic("registry: cross-realm admin call rejected")
        }
}

// IsInitialized reports whether the realm has been initialized.
func IsInitialized() bool {
        return admin != ""
}

// assertCore panics when the realm is used before Init.
func assertCore() {
        if admin == "" {
                panic("registry: realm not initialized")
        }
}

// Init initializes the realm. The caller of the deployment transaction
// becomes the protocol admin. Idempotent: a second call always panics.
func Init(cur realm) {
        if admin != "" {
                panic("registry: already initialized")
        }
        projects = make(map[string]*Project)
        components = make(map[string]*Component)
        registrars = make(map[string]bool)
        admin = cur.Previous().Address()
}

// SetAdmin transfers protocol admin to a new address. Only the current admin
// may call it.
func SetAdmin(cur realm, next address) {
        mustAdmin(cur)
        if !core.IsValidAddress(string(next)) {
                panic("registry: invalid admin address")
        }
        admin = next
}

// GrantRegistrar allow-lists an address to register projects. Only the
// protocol admin may grant registration rights.
func GrantRegistrar(cur realm, addr address) {
        mustAdmin(cur)
        if !core.IsValidAddress(string(addr)) {
                panic("registry: invalid registrar address")
        }
        registrars[string(addr)] = true
}

// RevokeRegistrar removes an address from the registrar allow-list.
func RevokeRegistrar(cur realm, addr address) {
        mustAdmin(cur)
        delete(registrars, string(addr))
}

// IsRegistrar reports whether addr may register projects (owner implicitly
// administers).
func IsRegistrar(addr address) bool {
        assertCore()
        if string(addr) == string(admin) {
                return true
        }
        return registrars[string(addr)]
}

// RegisterProject records a new project owned by the caller.
func RegisterProject(cur realm, id, name, description, repo, category, visibility string) {
        assertCore()
        caller := cur.Previous().Address()
        if !cur.IsCurrent() {
                panic("registry: project registration must run in current realm")
        }
        if !core.IsValidID(id) {
                panic("registry: invalid project id")
        }
        if _, ok := projects[id]; ok {
                panic("registry: project id already registered")
        }
        if !core.BoundedText(name, 128) || !core.BoundedText(description, core.MaxTextLen) ||
                !core.BoundedText(repo, 256) || !core.BoundedText(category, 64) {
                panic("registry: metadata exceeds size limits")
        }
        if name == "" {
                panic("registry: project name required")
        }
        if visibility != "public" && visibility != "private" {
                panic("registry: visibility must be public or private")
        }
        if !IsRegistrar(caller) {
                panic("registry: caller is not a registrar")
        }
        projects[id] = &Project{
                ID:          id,
                Name:        name,
                Description: description,
                Repo:        repo,
                Category:    category,
                Visibility:  visibility,
                Owner:       caller,
                CreatedAt:   time.Now().Unix(),
                Archived:    false,
        }
        projectIDs = append(projectIDs, id)
}

// TransferProject moves project ownership to a new address. Only the current
// owner may transfer.
func TransferProject(cur realm, id string, next address) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                panic("registry: unknown project")
        }
        caller := cur.Previous().Address()
        if caller != p.Owner {
                panic("registry: only the project owner may transfer ownership")
        }
        if !core.IsValidAddress(string(next)) {
                panic("registry: invalid target owner")
        }
        if string(next) == string(p.Owner) {
                panic("registry: target owner already owns project")
        }
        p.Owner = next
}

// SetProjectVisibility toggles public/private. Owner only.
func SetProjectVisibility(cur realm, id, visibility string) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                panic("registry: unknown project")
        }
        if cur.Previous().Address() != p.Owner {
                panic("registry: only the project owner may change visibility")
        }
        if visibility != "public" && visibility != "private" {
                panic("registry: visibility must be public or private")
        }
        p.Visibility = visibility
}

// ArchiveProject soft-archives a project. Owner or protocol admin.
func ArchiveProject(cur realm, id string) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                panic("registry: unknown project")
        }
        caller := cur.Previous().Address()
        if caller != p.Owner && caller != admin {
                panic("registry: not authorized to archive project")
        }
        p.Archived = true
}

// RestoreProject reactivates an archived project. Owner only.
func RestoreProject(cur realm, id string) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                panic("registry: unknown project")
        }
        if cur.Previous().Address() != p.Owner {
                panic("registry: only the project owner may restore")
        }
        p.Archived = false
}

// RegisterComponent records a component under a project owned by the caller.
func RegisterComponent(cur realm, id, projectID, name, license, artifactType string) {
        assertCore()
        p, ok := projects[projectID]
        if !ok {
                panic("registry: unknown project")
        }
        if p.Archived {
                panic("registry: project is archived")
        }
        caller := cur.Previous().Address()
        if caller != p.Owner {
                panic("registry: only the project owner may register components")
        }
        if !core.IsValidID(id) {
                panic("registry: invalid component id")
        }
        if _, exists := components[id]; exists {
                panic("registry: component id already registered")
        }
        if !core.BoundedText(name, 128) || !core.BoundedText(license, 64) || !core.BoundedText(artifactType, 32) {
                panic("registry: component metadata exceeds size limits")
        }
        validTypes := map[string]bool{"source": true, "container": true, "binary": true, "sbom": true, "docs": true, "library": true}
        if !validTypes[artifactType] {
                panic("registry: unsupported artifact type")
        }
        components[id] = &Component{
                ID:           id,
                ProjectID:    projectID,
                Name:         name,
                License:      license,
                ArtifactType: artifactType,
                Owner:        caller,
                CreatedAt:    time.Now().Unix(),
                Deprecated:   false,
        }
        componentIDs = append(componentIDs, id)
}

// DeprecateComponent marks a component deprecated. Owner only.
func DeprecateComponent(cur realm, id string) {
        assertCore()
        c, ok := components[id]
        if !ok {
                panic("registry: unknown component")
        }
        if cur.Previous().Address() != c.Owner {
                panic("registry: only the component owner may deprecate")
        }
        c.Deprecated = true
}

// HasProject reports existence regardless of visibility.
func HasProject(id string) bool {
        assertCore()
        _, ok := projects[id]
        return ok
}

// GetProject returns the project only when it is public. Caller context is
// not available in a pure getter, so private projects are never exposed
// here; owners must use GetProjectFor with their own address. This prevents
// a leaking getter from being accidentally imported by consumer realms.
func GetProject(id string) (Project, bool) {
	return GetPublicProject(id)
}

// GetProjectFor checks visibility for a specific reader address.
func GetProjectFor(id string, reader address) (Project, bool) {
        assertCore()
        p, ok := projects[id]
        if !ok {
                return Project{}, false
        }
        if p.Visibility == "private" && reader != p.Owner {
                return Project{}, false
        }
        return *p, true
}

// GetPublicProject returns the project only when public. Used by the verify
// realm and external consumers.
func GetPublicProject(id string) (Project, bool) {
        assertCore()
        p, ok := projects[id]
        if !ok || p.Visibility != "public" || p.Archived {
                return Project{}, false
        }
        return *p, true
}

// IsProjectOwner reports whether addr owns the given project.
func IsProjectOwner(id string, addr address) bool {
        assertCore()
        p, ok := projects[id]
        if !ok {
                return false
        }
        return p.Owner == addr
}

// GetComponent returns a copy of the component.
func GetComponent(id string) (Component, bool) {
        assertCore()
        c, ok := components[id]
        if !ok {
                return Component{}, false
        }
        return *c, true
}

// IsComponentOwner reports whether addr owns the component's project.
func IsComponentOwner(id string, addr address) bool {
        assertCore()
        c, ok := components[id]
        if !ok {
                return false
        }
        return c.Owner == addr
}

// ListProjectIDs returns all project IDs, newest first.
func ListProjectIDs() []string {
        assertCore()
        out := make([]string, len(projectIDs))
        copy(out, projectIDs)
        // newest first: reverse of registration order
        for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
                out[i], out[j] = out[j], out[i]
        }
        return out
}

// ListPublicProjectIDs returns IDs of public, non-archived projects, sorted
// for deterministic output.
func ListPublicProjectIDs() []string {
        assertCore()
        var out []string
        for _, id := range projectIDs {
                p := projects[id]
                if p != nil && p.Visibility == "public" && !p.Archived {
                        out = append(out, id)
                }
        }
        sort.Strings(out)
        return out
}

// ListComponentIDsByProject returns component IDs for a project, newest first.
func ListComponentIDsByProject(projectID string) []string {
        assertCore()
        var out []string
        for _, id := range componentIDs {
                if c := components[id]; c != nil && c.ProjectID == projectID {
                        out = append(out, id)
                }
        }
        for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
                out[i], out[j] = out[j], out[i]
        }
        return out
}

// ProjectCount returns the number of registered projects.
func ProjectCount() int {
        assertCore()
        return len(projectIDs)
}

// ComponentCount returns the number of registered components.
func ComponentCount() int {
        assertCore()
        return len(componentIDs)
}

// IsProtocolAdmin reports whether addr is the protocol admin. Other realms
// delegate admin decisions to the same root of trust.
func IsProtocolAdmin(addr address) bool {
        assertCore()
        return string(addr) == string(admin)
}

// ProtocolAdminAddress returns the current admin address.
func ProtocolAdminAddress() address {
        assertCore()
        return admin
}

// NormalizeRepo trims scheme and trailing slash for consistent repo keys.
func NormalizeRepo(repo string) string {
        r := strings.TrimSuffix(repo, "/")
        r = strings.TrimPrefix(r, "https://")
        r = strings.TrimPrefix(r, "http://")
        r = strings.TrimPrefix(r, "git@")
        return r
}

package registry

import (
	"testing"
)

const (
	adminAddr = address("g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq")
	aliceAddr = address("g1aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	bobAddr   = address("g1bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb")
)

// expectAbort asserts that f aborts (panics) when executed. It relies on the
// gno `revive` builtin, which captures the panic value without unwinding the
// test frame — the sanctioned way to assert reverts on crossing calls.
func expectAbort(t *testing.T, f func()) {
	t.Helper()
	if r := revive(f); r == nil {
		t.Fatal("expected abort, got none")
	}
}

// NOTE: testing.SetRealm(...) is frame-local: it MUST be called inline within
// the test function body for the realm to apply to subsequent cross(cur)
// calls made from that frame.

func TestRegisterProjectFlow(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	testing.SetRealm(testing.NewUserRealm(adminAddr))
	GrantRegistrar(cross(cur), aliceAddr)

	before := ProjectCount()
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	RegisterProject(cross(cur), "core-api", "Core API", "Primary service", "github.com/example/core-api", "service", "public")

	if ProjectCount() != before+1 {
		t.Fatalf("expected project count to grow by 1, got %d -> %d", before, ProjectCount())
	}
	p, ok := GetPublicProject("core-api")
	if !ok {
		t.Fatal("project should be public readable")
	}
	if p.Owner != aliceAddr {
		t.Fatalf("owner mismatch: %s", p.Owner)
	}
	if p.CreatedAt <= 0 {
		t.Fatal("timestamp missing")
	}

	// duplicate registration must abort
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, func() {
		RegisterProject(cross(cur), "core-api", "Dup", "", "", "", "public")
	})

	// invalid id must abort
	expectAbort(t, func() {
		RegisterProject(cross(cur), "INVALID ID", "Bad", "", "", "", "public")
	})
}

func TestUnauthorizedRegistration(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	// bob is not a registrar: must abort
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		RegisterProject(cross(cur), "bob-proj-x", "Bob", "", "", "", "public")
	})
}

func TestOwnershipTransfer(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	testing.SetRealm(testing.NewUserRealm(adminAddr))
	GrantRegistrar(cross(cur), aliceAddr)

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	RegisterProject(cross(cur), "transfer-me", "Transfer", "", "", "", "public")

	// bob cannot transfer alice's project
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		TransferProject(cross(cur), "transfer-me", bobAddr)
	})

	// owner transfers to bob
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	TransferProject(cross(cur), "transfer-me", bobAddr)
	if !IsProjectOwner("transfer-me", bobAddr) {
		t.Fatal("bob should now own project")
	}
	if IsProjectOwner("transfer-me", aliceAddr) {
		t.Fatal("alice should no longer own project")
	}

	// transfer to self must abort
	expectAbort(t, func() {
		TransferProject(cross(cur), "transfer-me", bobAddr)
	})

	// transfer to invalid address must abort
	expectAbort(t, func() {
		TransferProject(cross(cur), "transfer-me", address("not-an-address"))
	})
}

func TestComponentsAndVisibility(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
