	}
	if !HasProject("archive-me") {
		t.Fatal("archived project still exists")
	}
	RestoreProject(cross(cur), "archive-me")
	if _, ok := GetPublicProject("archive-me"); !ok {
		t.Fatal("restored project must be public again")
	}

	// bob cannot archive
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		ArchiveProject(cross(cur), "archive-me")
	})

	// bob cannot restore
	expectAbort(t, func() {
		RestoreProject(cross(cur), "archive-me")
	})
}

func TestAdminCannotBeUsurped(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	if !IsProtocolAdmin(adminAddr) {
		t.Fatal("admin should be the deployer")
	}

	// alice cannot elevate herself
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, func() {
		SetAdmin(cross(cur), aliceAddr)
	})
	expectAbort(t, func() {
		GrantRegistrar(cross(cur), aliceAddr)
	})

	// admin CAN transfer admin, then original loses power
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	SetAdmin(cross(cur), bobAddr)
	if IsProtocolAdmin(adminAddr) {
		t.Fatal("old admin must lose power")
	}
	if !IsProtocolAdmin(bobAddr) {
		t.Fatal("bob must be admin")
	}

	// hand admin back to the deployer for the rest of the suite
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	SetAdmin(cross(cur), adminAddr)
	if !IsProtocolAdmin(adminAddr) {
		t.Fatal("admin handback failed")
	}
}

func TestListingDeterministic(cur realm, t *testing.T) {
	if !IsInitialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	ids := ListPublicProjectIDs()
	for i := 1; i < len(ids); i++ {
		if ids[i-1] > ids[i] {
			t.Fatalf("public ids not sorted: %v", ids)
		}
	}
	all := ListProjectIDs()
	if len(all) == 0 {
		t.Fatal("expected registered projects")
	}
	if !HasProject(all[0]) {
		t.Fatal("head of newest-first listing must exist")
	}

	if NormalizeRepo("https://github.com/x/y/") != "github.com/x/y" {
		t.Fatalf("NormalizeRepo broken: %s", NormalizeRepo("https://github.com/x/y/"))
	}
}

// Package releases is the on-chain release provenance engine of the
// PROOFLOOM protocol. It records release commitments and enforces the
// authoritative release state machine:
//
//	DRAFT -> EVIDENCE_PENDING -> VALIDATING -> REVIEW_REQUIRED ->
//	APPROVED -> PUBLISHED -> VERIFIED
//
// with terminal states REJECTED, REVOKED, SUPERSEDED and DISPUTED.
//
// A PUBLISHED record can never silently change: corrections require an
// explicit supersede or revocation, both of which are auditable state
// transitions in their own right.
//
// Authorization: every state-changing call is attributed to
// cur.Previous().Address() and must be the project owner (per the registry
// realm), the release publisher, or the protocol admin.
package releases

import (
	"sort"
	"time"

	core "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/core"
	reg "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/registry"
)

// Release is the durable on-chain record of a software release commitment.
type Release struct {
	ID             string
	ProjectID      string
	ComponentID    string
	Version        string
	Commit         string
	Branch         string
	Repo           string
	ArtifactDigest string
	Status         string
	Publisher      address
	CreatedAt      int64
	PublishedAt    int64
	SupersededBy   string
}

var releases map[string]*Release

// releaseOrder preserves creation order for deterministic listing.
var releaseIDs []string

func initialized() bool {
	return releases != nil
}

func ensure() {
	if releases == nil {
		panic("releases: realm not initialized")
	}
}

// Init seeds realm state. The registry realm must already be deployed and
// initialized: this realm relies on registry.IsProtocolAdmin for its root of
// trust, so there is no separate admin to configure here.
func Init(cur realm) {
	if initialized() {
		panic("releases: already initialized")
	}
	releases = make(map[string]*Release)
}

func caller(cur realm) address {
	return cur.Previous().Address()
}

func requireCurrent(cur realm) {
	if !cur.IsCurrent() {
		panic("releases: call must run in current realm")
	}
}

// authorized returns true when addr may act on the given release: as the
// release publisher, the project owner, or the protocol admin.
func authorized(r *Release, addr address) bool {
	if r.Publisher == addr {
		return true
	}
	if reg.IsProjectOwner(r.ProjectID, addr) {
		return true
	}
	if reg.IsProtocolAdmin(addr) {
		return true
	}
	return false
}

func getRelease(id string) *Release {
	r, ok := releases[id]
	if !ok {
		panic("releases: unknown release " + id)
	}
	return r
}

// CreateRelease starts a new release in DRAFT state. Caller must be the
// project owner. The release id is derived deterministically from project
// and version.
func CreateRelease(cur realm, projectID, version, commit, branch, repo, componentID string) string {
	ensure()
	requireCurrent(cur)
	if !reg.HasProject(projectID) {
		panic("releases: unknown project")
	}
	if !core.IsValidVersion(version) {
		panic("releases: invalid version")
	}
	if commit != "" && !core.IsValidShortHash(commit) {
		panic("releases: invalid commit hash")
	}
	if !core.BoundedText(branch, 128) || !core.BoundedText(repo, 256) || !core.BoundedText(componentID, 64) {
		panic("releases: field exceeds size limits")
	}
	id := core.ComposeReleaseID(projectID, version)
	if _, exists := releases[id]; exists {
		panic("releases: release already exists " + id)
	}
	// Authorization: only the project owner may create releases.
	if !reg.IsProjectOwner(projectID, caller(cur)) {
		panic("releases: only the project owner may create releases")
	}
	releases[id] = &Release{
		ID:          id,
		ProjectID:   projectID,
		ComponentID: componentID,
		Version:     version,
		Commit:      commit,
		Branch:      branch,
		Repo:        repo,
		Status:      core.ReleaseDraft,
		Publisher:   caller(cur),
		CreatedAt:   time.Now().Unix(),
	}
	releaseIDs = append(releaseIDs, id)
	return id
}

// SetEvidence attaches the build artifact digest and moves the release from
// DRAFT to EVIDENCE_PENDING, or from EVIDENCE_PENDING to VALIDATING when the
// digest changes. Digest correctness against artifacts is verified off-chain
// by the evidence worker; the chain stores the commitment.
func SetEvidence(cur realm, id, artifactDigest string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if !core.IsValidDigest(artifactDigest) {
		panic("releases: invalid artifact digest")
	}
	switch r.Status {
	case core.ReleaseDraft:
		r.Status = core.ReleaseEvidencePending
	case core.ReleaseEvidencePending:
		r.Status = core.ReleaseValidating
	default:
		panic("releases: cannot set evidence in state " + r.Status)
	}
	r.ArtifactDigest = artifactDigest
}

// MarkValidating records that automated validation started.
func MarkValidating(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status != core.ReleaseEvidencePending {
		panic("releases: expected EVIDENCE_PENDING, got " + r.Status)
	}
	r.Status = core.ReleaseValidating
}

// RequireReview moves a release into REVIEW_REQUIRED (policy or verifier
// decision).
func RequireReview(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status != core.ReleaseValidating {
		panic("releases: expected VALIDATING, got " + r.Status)
	}
	r.Status = core.ReleaseReviewRequired
}

// Approve authorizes the release for publication. Only REVIEW_REQUIRED and
// VALIDATING releases may be approved.
func Approve(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status != core.ReleaseReviewRequired && r.Status != core.ReleaseValidating {
		panic("releases: cannot approve from state " + r.Status)
	}
	r.Status = core.ReleaseApproved
}

// Reject terminates the release lifecycle. Terminal state.
func Reject(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status == core.ReleasePublished || r.Status == core.ReleaseVerified {
		panic("releases: published releases cannot be rejected; revoke instead")
	}
	r.Status = core.ReleaseRejected
}

// Publish commits the release on-chain. Requires APPROVED state and an
// attached artifact digest. Publish stamps the publication time and makes
// the record immutable except through Revoke/Supersede/Dispute.
func Publish(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status != core.ReleaseApproved {
		panic("releases: only APPROVED releases can be published")
	}
	if r.ArtifactDigest == "" {
		panic("releases: missing artifact digest")
	}
	r.Status = core.ReleasePublished
	r.PublishedAt = time.Now().Unix()
}

// MarkVerified records a successful verification pass over a published
// release. Only moves PUBLISHED -> VERIFIED.
func MarkVerified(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized for release")
	}
	if r.Status != core.ReleasePublished {
		panic("releases: only PUBLISHED releases can be verified")
	}
	r.Status = core.ReleaseVerified
}

// Revoke withdraws a published release. Authorization: publisher, project
// owner, or protocol admin. Revoked releases remain publicly readable —
// revocation is a visible state, never a deletion.
func Revoke(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized to revoke")
	}
	if r.Status != core.ReleasePublished && r.Status != core.ReleaseVerified {
		panic("releases: only published releases can be revoked")
	}
	r.Status = core.ReleaseRevoked
}

// Supersede marks a release replaced by a newer release of the same project.
// The superseding release must exist and be published.
func Supersede(cur realm, id, byID string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	nxt := getRelease(byID)
	if r.ProjectID != nxt.ProjectID {
		panic("releases: superseding release belongs to another project")
	}
	if nxt.Status != core.ReleasePublished && nxt.Status != core.ReleaseVerified {
		panic("releases: superseding release is not published")
	}
	// Only a published-family release can meaningfully be replaced; blocking
	// pre-publication states keeps the supersede audit trail coherent.
	if !isPublicState(r.Status) {
		panic("releases: only published releases can be superseded")
	}
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized to supersede")
	}
	r.Status = core.ReleaseSuperseded
	r.SupersededBy = byID
}

// Dispute flags a release as disputed (compliance or legal hold). Admin or
// project owner.
func Dispute(cur realm, id string) {
	ensure()
	requireCurrent(cur)
	r := getRelease(id)
	if !authorized(r, caller(cur)) {
		panic("releases: caller not authorized to dispute")
	}
	if r.Status == core.ReleaseRevoked || r.Status == core.ReleaseSuperseded {
		panic("releases: terminal release cannot be disputed")
	}
	r.Status = core.ReleaseDisputed
}

// GetRelease returns a copy of a release if visible to the reader. Public
// visibility: any reader sees published/verified/revoked/superseded/disputed
// records; pre-publication states are visible to authorized parties only.
func GetRelease(id string, reader address) (Release, bool) {
	ensure()
	r, ok := releases[id]
	if !ok {
		return Release{}, false
	}
	if !isPublicState(r.Status) && !authorized(r, reader) {
		return Release{}, false
	}
	return *r, true
}

// HasRelease reports existence without visibility checks.
func HasRelease(id string) bool {
	ensure()
	_, ok := releases[id]
	return ok
}

func isPublicState(status string) bool {
	switch status {
	case core.ReleasePublished, core.ReleaseVerified, core.ReleaseRevoked,
		core.ReleaseSuperseded, core.ReleaseDisputed:
		return true
	}
	return false
}

// ReleaseStatus returns the current status of a release, or "" when unknown.
// Status is public metadata for every release (needed by external verifiers
// to check revocation without full record access).
func ReleaseStatus(id string) string {
	ensure()
	if r, ok := releases[id]; ok {
		return r.Status
	}
	return ""
}

// GetPublishedRelease returns the release only when in a published-family
// state, for external consumers.
func GetPublishedRelease(id string) (Release, bool) {
	ensure()
	r, ok := releases[id]
	if !ok || !isPublicState(r.Status) {
		return Release{}, false
	}
	return *r, true
}

// ListReleaseIDsByProject returns release ids of a project, newest first.
func ListReleaseIDsByProject(projectID string) []string {
	ensure()
	var out []string
	for _, id := range releaseIDs {
		if r := releases[id]; r != nil && r.ProjectID == projectID {
			out = append(out, id)
		}
	}
	for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
		out[i], out[j] = out[j], out[i]
	}
	return out
}

// FindByDigest returns published release ids whose artifact digest matches,
// sorted for deterministic output. This powers digest-based public
// verification.
func FindByDigest(digest string) []string {
	ensure()
	if !core.IsValidDigest(digest) {
		return nil
	}
	var out []string
	for _, id := range releaseIDs {
		if r := releases[id]; r != nil && r.ArtifactDigest == digest && isPublicState(r.Status) {
			out = append(out, id)
		}
	}
	sort.Strings(out)
	return out
}

// ReleaseCount returns the total number of releases.
func ReleaseCount() int {
	ensure()
	return len(releaseIDs)
}

// Initialized reports whether the releases realm has been initialized.
func Initialized() bool {
	return releases != nil
}

package releases

import (
	"testing"

	core "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/core"
	reg "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/registry"
)

const (
	adminAddr = address("g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq")
	aliceAddr = address("g1aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	bobAddr   = address("g1bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb")
)

const digestA = "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2"

func expectAbort(t *testing.T, f func()) {
	t.Helper()
	if r := revive(f); r == nil {
		t.Fatal("expected abort, got none")
	}
}

// seedRegistry initializes the registry realm (shared across test binaries)
// and registers a project owned by alice.
func seedProject(cur realm, projectID string) {
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	if !reg.IsInitialized() {
		reg.Init(cross(cur))
	}
	reg.GrantRegistrar(cross(cur), aliceAddr)
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	if !reg.HasProject(projectID) {
		reg.RegisterProject(cross(cur), projectID, "Proj", "desc", "github.com/example/proj", "service", "public")
	}
}

func TestReleaseStateMachine(cur realm, t *testing.T) {
	seedProject(cur, "sm-proj")
	if !initialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	id := CreateRelease(cross(cur), "sm-proj", "1.0.0", "abc1234", "main", "github.com/example/proj", "")

	if id != "sm-proj-1.0.0" {
		t.Fatalf("unexpected release id %s", id)
	}

	// pre-publication states are hidden from foreign readers
	if _, ok := GetRelease(id, bobAddr); ok {
		t.Fatal("draft release must be hidden from foreign readers")
	}
	if _, ok := GetRelease(id, aliceAddr); !ok {
		t.Fatal("publisher must see own draft release")
	}

	// publish without evidence must abort
	expectAbort(t, func() {
		testing.SetRealm(testing.NewUserRealm(aliceAddr))
		Publish(cross(cur), id)
	})

	SetEvidence(cross(cur), id, digestA)
	r, _ := GetRelease(id, aliceAddr)
	if r.Status != core.ReleaseEvidencePending {
		t.Fatalf("expected EVIDENCE_PENDING, got %s", r.Status)
	}

	// invalid digest aborts
	expectAbort(t, func() {
		testing.SetRealm(testing.NewUserRealm(aliceAddr))
		SetEvidence(cross(cur), id, "nothex")
	})

	// full happy path
	MarkValidating(cross(cur), id)
	RequireReview(cross(cur), id)
	Approve(cross(cur), id)
	Publish(cross(cur), id)

	r, _ = GetRelease(id, bobAddr)
	if r.Status != core.ReleasePublished {
		t.Fatalf("expected PUBLISHED, got %s", r.Status)
	}
	if r.PublishedAt <= 0 {
		t.Fatal("publication timestamp missing")
	}

	// published records are public
	if _, ok := GetRelease(id, bobAddr); !ok {
		t.Fatal("published release must be public")
	}
	if ReleaseStatus(id) != core.ReleasePublished {
		t.Fatal("status query broken")
	}

	MarkVerified(cross(cur), id)
	if ReleaseStatus(id) != core.ReleaseVerified {
		t.Fatal("expected VERIFIED")
	}

	// digest lookup must find it
	found := FindByDigest(digestA)
	if len(found) != 1 || found[0] != id {
		t.Fatalf("digest lookup failed: %v", found)
	}
}

func TestReleaseAuthorization(cur realm, t *testing.T) {
	seedProject(cur, "authz-proj")
	if !initialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	// bob cannot create releases on alice's project
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		CreateRelease(cross(cur), "authz-proj", "0.1.0", "abc1234", "main", "", "")
	})

	// alice creates; bob cannot touch it
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	id := CreateRelease(cross(cur), "authz-proj", "0.2.0", "abc1234", "main", "", "")
	SetEvidence(cross(cur), id, digestA)

	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		Approve(cross(cur), id)
	})
	expectAbort(t, func() {
		Revoke(cross(cur), id)
	})

	// admin CAN act (protocol admin override)
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	MarkValidating(cross(cur), id)
	Approve(cross(cur), id)
	Publish(cross(cur), id)

	// invalid transition: approve after publish
	expectAbort(t, func() {
		testing.SetRealm(testing.NewUserRealm(aliceAddr))
		Approve(cross(cur), id)
	})
}

func TestRevokeAndSupersede(cur realm, t *testing.T) {
	seedProject(cur, "rv-proj")
	if !initialized() {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
	}

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	id1 := CreateRelease(cross(cur), "rv-proj", "2.0.0", "abc1234", "main", "", "")
	SetEvidence(cross(cur), id1, digestA)
	MarkValidating(cross(cur), id1)
	Approve(cross(cur), id1)
	Publish(cross(cur), id1)

	id2 := CreateRelease(cross(cur), "rv-proj", "2.1.0", "abc1234", "main", "", "")
	SetEvidence(cross(cur), id2, digestA)
	MarkValidating(cross(cur), id2)
	Approve(cross(cur), id2)
	Publish(cross(cur), id2)

	// supersede 2.0.0 with 2.1.0
	Supersede(cross(cur), id1, id2)
	r1, _ := GetRelease(id1, bobAddr)
	if r1.Status != core.ReleaseSuperseded || r1.SupersededBy != id2 {
		t.Fatalf("supersede failed: %s -> %s", r1.Status, r1.SupersededBy)
	}

	// cross-project supersede must abort
	idX := CreateRelease(cross(cur), "sm-proj", "9.9.9", "abc1234", "main", "", "")
	SetEvidence(cross(cur), idX, digestA)
	MarkValidating(cross(cur), idX)
	Approve(cross(cur), idX)
	Publish(cross(cur), idX)
	expectAbort(t, func() {
		Supersede(cross(cur), id2, idX)
	})

	// revoke remains publicly visible
	Revoke(cross(cur), id2)
	r2, ok := GetRelease(id2, bobAddr)
	if !ok || r2.Status != core.ReleaseRevoked {
		t.Fatalf("revoked release must remain visible: %v %s", ok, r2.Status)
	}
}

// Package attestations is the on-chain evidence commitment registry of the
// PROOFLOOM protocol. Attestations bind a claim category to a subject and a
// content digest, recorded by an identifiable issuer.
//
// An attestation is a signed-off-chain claim's public commitment: the
// evidence bytes themselves live off-chain; the chain stores who claimed
// what about which subject, when, and whether it still stands.
//
// Rules enforced here:
//   - Deterministic attestation ids (subject+category+issuer) structurally
//     prevent duplicate active attestations from one issuer for one subject
//     and category.
//   - Revocation is issuer-only (or protocol admin) and is permanent and
//     publicly visible.
//   - Expiry is recorded as data; status computation treats expired
//     attestations as EXPIRED.
package attestations

import (
	"sort"
	"time"

	core "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/core"
	reg "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/registry"
	rel "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/releases"
)

// Attestation is the durable public commitment record.
type Attestation struct {
	ID               string
	SubjectType      string
	SubjectID        string
	Category         string
	Issuer           address
	Digest           string
	Status           string
	IssuedAt         int64
	ExpiresAt        int64 // 0 means no expiry
	RevokedAt        int64
	RevocationReason string
}

var attestations map[string]*Attestation
var attestationIDs []string

// attestationHistory archives prior attestations when a revoked or expired
// record is re-issued under the same deterministic id, so revocation
// reasons and expiry history are never destroyed by an overwrite.
var attestationHistory map[string][]*Attestation

func ensure() {
	if attestations == nil {
		panic("attestations: realm not initialized")
	}
}

// Init seeds realm state. Root of trust is the registry realm's protocol
// admin; no separate admin exists here.
func Init(cur realm) {
	if attestations != nil {
		panic("attestations: already initialized")
	}
	attestations = make(map[string]*Attestation)
	attestationHistory = make(map[string][]*Attestation)
}

func validCategory(cat string) bool {
	switch cat {
	case core.AttestBuild, core.AttestSource, core.AttestTest, core.AttestSecurity,
		core.AttestCodeReview, core.AttestReleaseApprove, core.AttestAgentTask,
		core.AttestBenchmark, core.AttestDependency, core.AttestOwnership,
		core.AttestDeployment, core.AttestCompliance, core.AttestIncident:
		return true
	}
	return false
}

func validSubjectType(st string) bool {
	switch st {
	case core.SubjectRelease, core.SubjectProject, core.SubjectComponent,
		core.SubjectTask, core.SubjectExecution:
		return true
	}
	return false
}

// subjectExists verifies the subject reference resolves in the appropriate
// realm, preventing attestations against phantom subjects.
func subjectExists(subjectType, subjectID string) bool {
	switch subjectType {
	case core.SubjectRelease:
		return rel.HasRelease(subjectID)
	case core.SubjectProject:
		return reg.HasProject(subjectID)
	}
	// component/task/execution subjects are registered off-chain first;
	// on-chain existence is checked for the types the chain knows.
	return subjectType == core.SubjectComponent || subjectType == core.SubjectTask || subjectType == core.SubjectExecution
}

// Issue records a new attestation commitment. The caller is the issuer.
// expiresAt is an absolute unix timestamp; 0 means never expires.
func Issue(cur realm, subjectType, subjectID, category, digest string, expiresAt int64) string {
	ensure()
	if !cur.IsCurrent() {
		panic("attestations: issue must run in current realm")
	}
	if !validSubjectType(subjectType) {
		panic("attestations: invalid subject type")
	}
	if !validCategory(category) {
		panic("attestations: invalid category")
	}
	if !core.IsValidDigest(digest) {
		panic("attestations: invalid evidence digest")
	}
	if !subjectExists(subjectType, subjectID) {
		panic("attestations: subject does not exist")
	}
	if expiresAt != 0 && expiresAt <= time.Now().Unix() {
		panic("attestations: expiry must be in the future")
	}
	issuer := cur.Previous().Address()
	id := core.ComposeAttestationID(subjectID, category, string(issuer))
	if existing, ok := attestations[id]; ok && existing.Status == core.AttestationActive {
		panic("attestations: active attestation already exists for this subject, category and issuer")
	}
	if existing, ok := attestations[id]; ok {
		// Archive the replaced record; history stays publicly inspectable.
		attestationHistory[id] = append(attestationHistory[id], existing)
	}
	attestations[id] = &Attestation{
		ID:          id,
		SubjectType: subjectType,
		SubjectID:   subjectID,
		Category:    category,
		Issuer:      issuer,
		Digest:      digest,
		Status:      core.AttestationActive,
		IssuedAt:    time.Now().Unix(),
		ExpiresAt:   expiresAt,
	}
	attestationIDs = append(attestationIDs, id)
	return id
}

// Revoke permanently revokes an attestation. Only the original issuer or
// the protocol admin may revoke. Revocation is visible forever.
func Revoke(cur realm, id, reason string) {
	ensure()
	a, ok := attestations[id]
	if !ok {
		panic("attestations: unknown attestation")
	}
	caller := cur.Previous().Address()
	if a.Issuer != caller && !reg.IsProtocolAdmin(caller) {
		panic("attestations: only the issuer or protocol admin may revoke")
	}
	if a.Status == core.AttestationRevoked {
		panic("attestations: already revoked")
	}
	if !core.BoundedText(reason, core.MaxTextLen) {
		panic("attestations: revocation reason too long")
	}
	a.Status = core.AttestationRevoked
	a.RevokedAt = time.Now().Unix()
	a.RevocationReason = reason
}

// GetAttestation returns a copy of the attestation record.
func GetAttestation(id string) (Attestation, bool) {
	ensure()
	a, ok := attestations[id]
	if !ok {
		return Attestation{}, false
	}
	return *a, true
}

// GetAttestationHistory returns archived (replaced) attestation records for
// a deterministic attestation id, oldest first. Copies only: internal
// pointers are never exposed.
func GetAttestationHistory(id string) []Attestation {
	ensure()
	hist := attestationHistory[id]
	out := make([]Attestation, 0, len(hist))
	for _, a := range hist {
		out = append(out, *a)
	}
	return out
}

// EffectiveStatus returns ACTIVE, REVOKED or EXPIRED for an attestation id,
// "" when unknown. Expired status is derived from recorded expiry time so
// verifiers get truthful answers without re-computing.
func EffectiveStatus(id string) string {
	ensure()
	a, ok := attestations[id]
	if !ok {
		return ""
	}
	if a.Status == core.AttestationRevoked {
		return core.AttestationRevoked
	}
	if a.ExpiresAt != 0 && a.ExpiresAt <= time.Now().Unix() {
		return core.AttestationExpired
	}
	return core.AttestationActive
}

// ListBySubject returns attestation ids attached to a subject, newest first.
func ListBySubject(subjectID string) []string {
	ensure()
	var out []string
	for _, id := range attestationIDs {
		if a := attestations[id]; a != nil && a.SubjectID == subjectID {
			out = append(out, id)
		}
	}
	for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
		out[i], out[j] = out[j], out[i]
	}
	return out
}

// ListActiveBySubjectAndCategory returns active attestation ids for a
// subject/category pair, sorted deterministically.
func ListActiveBySubjectAndCategory(subjectID, category string) []string {
	ensure()
	var out []string
	for _, id := range attestationIDs {
		a := attestations[id]
		if a == nil || a.SubjectID != subjectID || a.Category != category {
			continue
		}
		if EffectiveStatus(id) != core.AttestationActive {
			continue
		}
		out = append(out, id)
	}
	sort.Strings(out)
	return out
}

// HasActiveAttestation reports whether any active attestation of the given
// category exists for the subject from the given issuer (empty issuer = any).
func HasActiveAttestation(subjectID, category, issuer string) bool {
	ensure()
	for _, id := range ListActiveBySubjectAndCategory(subjectID, category) {
		if issuer == "" || string(attestations[id].Issuer) == issuer {
			return true
		}
	}
	return false
}

// AttestationCount returns the number of attestations recorded.
func AttestationCount() int {
	ensure()
	return len(attestationIDs)
}

// Initialized reports whether the realm is initialized.
func Initialized() bool {
	return attestations != nil
}

package attestations

import (
	"testing"

	core "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/core"
	reg "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/registry"
	rel "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/releases"
)

const (
	adminAddr = address("g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq")
	aliceAddr = address("g1aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	bobAddr   = address("g1bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb")
)

const digestA = "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2"
const digestB = "b1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2"

func expectAbort(t *testing.T, f func()) {
	t.Helper()
	if r := revive(f); r == nil {
		t.Fatal("expected abort, got none")
	}
}

// seed initializes all dependency realms and returns a published release id.
func seed(cur realm) string {
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	if !reg.IsInitialized() {
		reg.Init(cross(cur))
	}
	reg.GrantRegistrar(cross(cur), aliceAddr)
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	if !reg.HasProject("att-proj") {
		reg.RegisterProject(cross(cur), "att-proj", "Att", "d", "repo", "service", "public")
	}
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	if !rel.Initialized() {
		rel.Init(cross(cur))
	}
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	if !rel.HasRelease("att-proj-1.0.0") {
		id := rel.CreateRelease(cross(cur), "att-proj", "1.0.0", "abc1234", "main", "", "")
		rel.SetEvidence(cross(cur), id, digestA)
		rel.MarkValidating(cross(cur), id)
		rel.Approve(cross(cur), id)
		rel.Publish(cross(cur), id)
	}
	if !initDone {
		testing.SetRealm(testing.NewUserRealm(adminAddr))
		Init(cross(cur))
		initDone = true
	}
	return "att-proj-1.0.0"
}

var initDone bool

func TestIssueAndDuplicatePrevention(cur realm, t *testing.T) {
	rid := seed(cur)

	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	id := Issue(cross(cur), core.SubjectRelease, rid, core.AttestBuild, digestB, 0)
	if id == "" {
		t.Fatal("attestation id missing")
	}
	if EffectiveStatus(id) != core.AttestationActive {
		t.Fatal("expected active")
	}

	// duplicate active attestation from same issuer for same subject+category
	expectAbort(t, func() {
		testing.SetRealm(testing.NewUserRealm(aliceAddr))
		Issue(cross(cur), core.SubjectRelease, rid, core.AttestBuild, digestB, 0)
	})

	// a different issuer may attest the same subject+category
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	id2 := Issue(cross(cur), core.SubjectRelease, rid, core.AttestBuild, digestB, 0)
	if EffectiveStatus(id2) != core.AttestationActive {
		t.Fatal("second issuer attestation should be active")
	}

	if AttestationCount() < 2 {
		t.Fatal("expected at least 2 attestations")
	}
}

func TestRevocation(cur realm, t *testing.T) {
	rid := seed(cur)

	testing.SetRealm(testing.NewUserRealm(bobAddr))
	id := Issue(cross(cur), core.SubjectRelease, rid, core.AttestTest, digestB, 0)

	// bob (issuer) revokes
	Revoke(cross(cur), id, "superseded by retest")
	if EffectiveStatus(id) != core.AttestationRevoked {
		t.Fatal("expected revoked")
	}
	a, _ := GetAttestation(id)
	if a.RevocationReason != "superseded by retest" || a.RevokedAt <= 0 {
		t.Fatal("revocation metadata missing")
	}

	// after revocation, the issuer may re-issue a fresh attestation
	id2 := Issue(cross(cur), core.SubjectRelease, rid, core.AttestTest, digestB, 0)
	if EffectiveStatus(id2) != core.AttestationActive {
		t.Fatal("re-issue after revocation should work")
	}

	// alice cannot revoke bob's attestation
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, func() {
		Revoke(cross(cur), id2, "not my attestation")
	})

	// admin CAN revoke
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	Revoke(cross(cur), id2, "admin hold")
	if EffectiveStatus(id2) != core.AttestationRevoked {
		t.Fatal("admin revocation failed")
	}

	// revoked attestations remain publicly readable
	a2, ok := GetAttestation(id2)
	if !ok || a2.Status != core.AttestationRevoked {
		t.Fatal("revoked record must remain visible")
	}
}

func TestValidationGuards(cur realm, t *testing.T) {
	rid := seed(cur)

	// invalid category
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	expectAbort(t, func() {
		Issue(cross(cur), core.SubjectRelease, rid, "MAGIC", digestB, 0)
	})

	// invalid digest
	expectAbort(t, func() {
		Issue(cross(cur), core.SubjectRelease, rid, core.AttestBuild, "tooshort", 0)
	})

	// phantom subject
	expectAbort(t, func() {
		Issue(cross(cur), core.SubjectRelease, "ghost-release-9.9.9", core.AttestBuild, digestB, 0)
	})

	// expiry in the past
	expectAbort(t, func() {
		Issue(cross(cur), core.SubjectRelease, rid, core.AttestBenchmark, digestB, 1000)
	})

	// project subject works
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	pid := Issue(cross(cur), core.SubjectProject, "att-proj", core.AttestOwnership, digestB, 0)
	if EffectiveStatus(pid) != core.AttestationActive {
		t.Fatal("project attestation should be active")
	}
}

// Package agents is the on-chain registry and accountability layer for
// autonomous AI agents in the PROOFLOOM protocol.
//
// Agents are first-class protocol participants, but they never receive
// implicit authority: every permission is a scoped, expiring, revocable
// grant made by a project owner. Execution receipts make agent work
// auditable and attributable on-chain.
//
// The agent runtime itself (LLM inference, tool use, evidence collection)
// runs entirely off-chain. This realm records identities, permissions,
// grants and execution receipts — nothing else.
package agents

import (
	"time"

	core "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/core"
	reg "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/registry"
)

// Agent is a registered autonomous actor.
type Agent struct {
	ID           string
	Name         string
	Description  string
	Owner        address
	Version      string
	Runtime      string // off-chain runtime/provider metadata reference
	Capabilities []string
	Status       string
	CreatedAt    int64
}

// Grant is a scoped, expiring permission for an agent over a project.
type Grant struct {
	AgentID   string
	ProjectID string
	Scopes    []string
	ExpiresAt int64
	GrantedBy address
	GrantedAt int64
	Revoked   bool
}

// Execution is an immutable agent execution receipt.
type Execution struct {
	ID       string
	AgentID  string
	TaskID   string
	ProjectID string
	Digest   string // content digest of the execution report
	Status   string // COMPLETED or FAILED
	RecordedBy address
	At       int64
}

var (
	agents     map[string]*Agent
	grants     map[string]*Grant // key: agentID + "/" + projectID
	executions map[string]*Execution
	agentIDs     []string
	executionIDs []string
)

func ensure() {
	if agents == nil {
		panic("agents: realm not initialized")
	}
}

// Init seeds realm state.
func Init(cur realm) {
	if agents != nil {
		panic("agents: already initialized")
	}
	agents = make(map[string]*Agent)
	grants = make(map[string]*Grant)
	executions = make(map[string]*Execution)
}

func validScope(s string) bool {
	switch s {
	case core.AgentScopeRead, core.AgentScopeEvidence, core.AgentScopeVerifyRequest,
		core.AgentScopeTaskUpdate, core.AgentScopeReviewPropose, core.AgentScopePublishReq:
		return true
	}
	return false
}

// RegisterAgent records a new agent owned by the caller.
func RegisterAgent(cur realm, id, name, description, version, runtime string, capabilities []string) {
	ensure()
	if !cur.IsCurrent() {
		panic("agents: register must run in current realm")
	}
	if !core.IsValidID(id) {
		panic("agents: invalid agent id")
	}
	if _, ok := agents[id]; ok {
		panic("agents: agent id already registered")
	}
	if !core.BoundedText(name, 128) || !core.BoundedText(description, core.MaxTextLen) ||
		!core.BoundedText(version, 32) || !core.BoundedText(runtime, 128) {
		panic("agents: metadata exceeds size limits")
	}
	if name == "" {
		panic("agents: agent name required")
	}
	if len(capabilities) > core.MaxListLen {
		panic("agents: too many capabilities")
	}
	caps := make([]string, 0, len(capabilities))
	for _, c := range capabilities {
		if !core.BoundedText(c, 64) || c == "" {
			panic("agents: invalid capability")
		}
		caps = append(caps, c)
	}
	agents[id] = &Agent{
		ID:           id,
		Name:         name,
		Description:  description,
		Owner:        cur.Previous().Address(),
		Version:      version,
		Runtime:      runtime,
		Capabilities: caps,
		Status:       core.AgentActive,
		CreatedAt:    time.Now().Unix(),
	}
	agentIDs = append(agentIDs, id)
}

// canSuspend reports whether caller may suspend the agent: the agent
// owner, the protocol admin, or the owner of any project the agent holds a
// grant on (protective control for affected project owners).
func canSuspend(a *Agent, caller address) bool {
	if a.Owner == caller || reg.IsProtocolAdmin(caller) {
		return true
	}
	for _, g := range grants {
		if g.AgentID == a.ID && !g.Revoked && reg.IsProjectOwner(g.ProjectID, caller) {
			return true
		}
	}
	return false
}

// SuspendAgent pauses an agent. Owner, protocol admin, or any project owner
// holding an active grant for the agent.
func SuspendAgent(cur realm, id string) {
	ensure()
	a := getAgent(id)
	caller := cur.Previous().Address()
	if !canSuspend(a, caller) {
		panic("agents: not authorized to suspend")
	}
	if a.Status != core.AgentActive {
		panic("agents: agent is not active")
	}
	a.Status = core.AgentSuspended
}

// ResumeAgent reactivates a suspended agent. Owner only.
func ResumeAgent(cur realm, id string) {
	ensure()
	a := getAgent(id)
	if a.Owner != cur.Previous().Address() {
		panic("agents: only the owner may resume")
	}
	if a.Status != core.AgentSuspended {
		panic("agents: agent is not suspended")
	}
	a.Status = core.AgentActive
}

// RevokeAgent permanently revokes an agent. Owner or protocol admin.
func RevokeAgent(cur realm, id string) {
	ensure()
	a := getAgent(id)
	caller := cur.Previous().Address()
	if a.Owner != caller && !reg.IsProtocolAdmin(caller) {
		panic("agents: not authorized to revoke")
	}
	if a.Status == core.AgentRevoked {
		panic("agents: agent already revoked")
	}
	a.Status = core.AgentRevoked
	// revoke all grants immediately: least privilege on termination.
	for k, g := range grants {
		if g.AgentID == id && !g.Revoked {
			g.Revoked = true
			_ = k
		}
	}
}

// GrantPermission gives an agent scoped access to a project until expiresAt.
// Only the project owner may grant. Scopes are additive across grants but
// every grant is independently revocable and expiring.
func GrantPermission(cur realm, agentID, projectID string, scopes []string, expiresAt int64) {
	ensure()
	a := getAgent(agentID)
	if a.Status != core.AgentActive {
		panic("agents: agent is not active")
	}
	if !reg.HasProject(projectID) {
		panic("agents: unknown project")
	}
	if !reg.IsProjectOwner(projectID, cur.Previous().Address()) {
		panic("agents: only the project owner may grant permissions")
	}
	if len(scopes) == 0 || len(scopes) > core.MaxListLen {
		panic("agents: invalid scope count")
	}
	for _, s := range scopes {
		if !validScope(s) {
			panic("agents: invalid scope " + s)
		}
	}
	if expiresAt != 0 && expiresAt <= time.Now().Unix() {
		panic("agents: expiry must be in the future")
	}
	key := agentID + "/" + projectID
	if g, ok := grants[key]; ok && !g.Revoked && (g.ExpiresAt == 0 || g.ExpiresAt > time.Now().Unix()) {
		panic("agents: active grant already exists for this agent and project")
	}
	grants[key] = &Grant{
		AgentID:   agentID,
		ProjectID: projectID,
		Scopes:    scopes,
		ExpiresAt: expiresAt,
		GrantedBy: cur.Previous().Address(),
		GrantedAt: time.Now().Unix(),
		Revoked:   false,
	}
}

// RevokePermission withdraws an agent's grant for a project immediately.
func RevokePermission(cur realm, agentID, projectID string) {
	ensure()
	key := agentID + "/" + projectID
	g, ok := grants[key]
	if !ok {
		panic("agents: no grant for this agent and project")
	}
	if !reg.IsProjectOwner(g.ProjectID, cur.Previous().Address()) && !reg.IsProtocolAdmin(cur.Previous().Address()) {
		panic("agents: only the project owner or admin may revoke")
	}
	g.Revoked = true
}

// HasPermission reports whether an agent holds an active, unexpired grant
// with the given scope on the project. Used by other realms and the
// off-chain runtime as the authorization gate.
func HasPermission(agentID, projectID, scope string) bool {
	ensure()
	g, ok := grants[agentID+"/"+projectID]
	if !ok || g.Revoked {
		return false
	}
	if g.ExpiresAt != 0 && g.ExpiresAt <= time.Now().Unix() {
		return false
	}
	a := agents[agentID]
	if a == nil || a.Status != core.AgentActive {
		return false
	}
	for _, s := range g.Scopes {
		if s == scope {
			return true
		}
	}
	return false
}

// RecordExecution records an immutable execution receipt. Caller must be
// the agent owner; the agent must hold EVIDENCE or TASK_UPDATE scope on the
// target project. Duplicate execution ids are structurally rejected.
func RecordExecution(cur realm, agentID, taskID, projectID, digest, status string) string {
	ensure()
	a := getAgent(agentID)
	if a.Owner != cur.Previous().Address() {
		panic("agents: only the agent owner may record executions")
	}
	if a.Status != core.AgentActive {
		panic("agents: agent is not active")
	}
	if status != "COMPLETED" && status != "FAILED" {
		panic("agents: invalid execution status")
	}
	if !core.IsValidDigest(digest) {
		panic("agents: invalid report digest")
	}
	if !core.BoundedText(taskID, 64) || !core.BoundedText(projectID, 64) {
		panic("agents: field exceeds size limits")
	}
	if projectID != "" {
		if !reg.HasProject(projectID) {
			panic("agents: unknown project")
		}
		if !HasPermission(agentID, projectID, core.AgentScopeEvidence) &&
			!HasPermission(agentID, projectID, core.AgentScopeTaskUpdate) {
			panic("agents: agent lacks required permission for project")
		}
	}
	id := agentID + "-" + taskID
	if _, exists := executions[id]; exists {
		panic("agents: duplicate execution record " + id)
	}
	executions[id] = &Execution{
		ID:         id,
		AgentID:    agentID,
		TaskID:     taskID,
		ProjectID:  projectID,
		Digest:     digest,
		Status:     status,
		RecordedBy: cur.Previous().Address(),
		At:         time.Now().Unix(),
	}
	executionIDs = append(executionIDs, id)
	return id
}

func getAgent(id string) *Agent {
	a, ok := agents[id]
	if !ok {
		panic("agents: unknown agent " + id)
	}
	return a
}

// GetAgent returns a copy of the agent record.
func GetAgent(id string) (Agent, bool) {
	ensure()
	a, ok := agents[id]
	if !ok {
		return Agent{}, false
	}
	cp := *a
	caps := make([]string, len(a.Capabilities))
	copy(caps, a.Capabilities)
	cp.Capabilities = caps
	return cp, true
}

// GetGrant returns a copy of the grant for an agent/project pair.
func GetGrant(agentID, projectID string) (Grant, bool) {
	ensure()
	g, ok := grants[agentID+"/"+projectID]
	if !ok {
		return Grant{}, false
	}
	cp := *g
	sc := make([]string, len(g.Scopes))
	copy(sc, g.Scopes)
	cp.Scopes = sc
	return cp, true
}

// GetExecution returns a copy of an execution receipt.
func GetExecution(id string) (Execution, bool) {
	ensure()
	e, ok := executions[id]
	if !ok {
		return Execution{}, false
	}
	return *e, true
}

// ListAgentIDs returns registered agent ids, newest first.
func ListAgentIDs() []string {
	ensure()
	out := make([]string, len(agentIDs))
	copy(out, agentIDs)
	for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
		out[i], out[j] = out[j], out[i]
	}
	return out
}

// ListExecutionsByAgent returns execution ids for an agent, newest first.
func ListExecutionsByAgent(agentID string) []string {
	ensure()
	var out []string
	for _, id := range executionIDs {
		if e := executions[id]; e != nil && e.AgentID == agentID {
			out = append(out, id)
		}
	}
	for i, j := 0, len(out)-1; i < j; i, j = i+1, j-1 {
		out[i], out[j] = out[j], out[i]
	}
	return out
}

// AgentCount returns the number of registered agents.
func AgentCount() int {
	ensure()
	return len(agentIDs)
}

// Initialized reports whether the realm is initialized.
func Initialized() bool {
	return agents != nil
}

package agents

import (
	"testing"

	core "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/core"
	reg "gno.land/r/g143auna4q94a3qtr8fqnwf0z3c3f3rxcz9ed55s/proofloom/registry"
)

const (
	adminAddr = address("g1pd8esjj02k67reyzquv42lf8tlc4g9nnntashq")
	aliceAddr = address("g1aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa")
	bobAddr   = address("g1bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb")
)

const digestA = "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2"

func expectAbort(t *testing.T, f func()) {
	t.Helper()
	if r := revive(f); r == nil {
		t.Fatal("expected abort, got none")
	}
}

func seedAll(cur realm) {
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	if !reg.IsInitialized() {
		reg.Init(cross(cur))
	}
	reg.GrantRegistrar(cross(cur), aliceAddr)
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	if !reg.HasProject("ag-proj") {
		reg.RegisterProject(cross(cur), "ag-proj", "Ag", "d", "repo", "service", "public")
	}
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	if !Initialized() {
		Init(cross(cur))
	}
}

func TestAgentLifecycle(cur realm, t *testing.T) {
	seedAll(cur)

	// bob registers an agent he owns
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	RegisterAgent(cross(cur), "code-review-bot", "Code Review Bot", "Reviews PRs", "1.0.0", "sandbox-runtime", []string{"code-review", "static-analysis"})

	a, ok := GetAgent("code-review-bot")
	if !ok || a.Owner != bobAddr || a.Status != core.AgentActive {
		t.Fatalf("agent registration broken: %v %s %s", ok, a.Owner, a.Status)
	}

	// alice (project owner) grants scoped permission
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	GrantPermission(cross(cur), "code-review-bot", "ag-proj", []string{core.AgentScopeRead, core.AgentScopeEvidence}, 0)

	if !HasPermission("code-review-bot", "ag-proj", core.AgentScopeEvidence) {
		t.Fatal("expected evidence permission")
	}
	if HasPermission("code-review-bot", "ag-proj", core.AgentScopePublishReq) {
		t.Fatal("publish scope must not be granted implicitly")
	}

	// bob records an execution receipt under the grant
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	eid := RecordExecution(cross(cur), "code-review-bot", "task-001", "ag-proj", digestA, "COMPLETED")
	e, _ := GetExecution(eid)
	if e.AgentID != "code-review-bot" || e.Status != "COMPLETED" {
		t.Fatal("execution record broken")
	}

	// duplicate execution id aborts
	expectAbort(t, func() {
		testing.SetRealm(testing.NewUserRealm(bobAddr))
		RecordExecution(cross(cur), "code-review-bot", "task-001", "ag-proj", digestA, "COMPLETED")
	})

	// suspension blocks execution recording
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	SuspendAgent(cross(cur), "code-review-bot")
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	expectAbort(t, func() {
		RecordExecution(cross(cur), "code-review-bot", "task-002", "ag-proj", digestA, "COMPLETED")
	})

	// bob cannot suspend or resume alice-granted... bob owns the agent: resume
	testing.SetRealm(testing.NewUserRealm(bobAddr))
	ResumeAgent(cross(cur), "code-review-bot")
	if a, _ := GetAgent("code-review-bot"); a.Status != core.AgentActive {
		t.Fatal("resume failed")
	}

	// revocation kills grants
	testing.SetRealm(testing.NewUserRealm(adminAddr))
	RevokeAgent(cross(cur), "code-review-bot")
	if HasPermission("code-review-bot", "ag-proj", core.AgentScopeEvidence) {
		t.Fatal("revoked agent must lose grants")
	}
}

func TestGrantAuthorization(cur realm, t *testing.T) {
	seedAll(cur)

	testing.SetRealm(testing.NewUserRealm(bobAddr))
	RegisterAgent(cross(cur), "task-bot", "Task Bot", "Does tasks", "1.0.0", "runtime", []string{"tasks"})

	// bob (not project owner) cannot grant himself permissions
	expectAbort(t, func() {
		GrantPermission(cross(cur), "task-bot", "ag-proj", []string{core.AgentScopeRead}, 0)
	})

	// alice grants, then revokes
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
	GrantPermission(cross(cur), "task-bot", "ag-proj", []string{core.AgentScopeTaskUpdate}, 0)

	// duplicate active grant aborts
	expectAbort(t, func() {
		GrantPermission(cross(cur), "task-bot", "ag-proj", []string{core.AgentScopeRead}, 0)
	})

	// invalid scope aborts
	expectAbort(t, func() {
		GrantPermission(cross(cur), "task-bot-x", "ag-proj", []string{"SUPERUSER"}, 0)
	})

	// bob records execution without permission: abort
	expectAbort(t, func() {
		testing.SetRealm(testing.NewUserRealm(bobAddr))
		RecordExecution(cross(cur), "task-bot", "task-100", "ag-proj", digestA, "COMPLETED")
	})

	// alice revokes the grant; bob still cannot execute
	RevokePermission(cross(cur), "task-bot", "ag-proj")
	expectAbort(t, func() {
		testing.SetRealm(testing.NewUserRealm(bobAddr))
		RecordExecution(cross(cur), "task-bot", "task-101", "ag-proj", digestA, "COMPLETED")
	})
}

func TestExpiringGrants(cur realm, t *testing.T) {
	seedAll(cur)

	testing.SetRealm(testing.NewUserRealm(bobAddr))
	RegisterAgent(cross(cur), "shortlived", "Short", "Expires fast", "1.0.0", "rt", nil)

	// grant that expires in the past aborts
	testing.SetRealm(testing.NewUserRealm(aliceAddr))
