package rules

// Game is a game in progress. It is a plain value owned by whoever created
// it; bots never get a reference to it, only Views.
type Game struct {
	m      Map
	cells  []uint8
	head   [2]Point
	turn   int
	moves  []byte
	winner int
	death  [2]int
	facing [2]Dir

	// scratch space for View.Reach, reused to avoid allocations per call
	mark  []uint32
	gen   uint32
	queue []int
}

// NewGame starts a game on m.
func NewGame(m Map) *Game {
	g := &Game{m: m, cells: make([]uint8, m.w*m.h), winner: going, mark: make([]uint32, m.w*m.h), queue: make([]int, 0, m.w*m.h)}
	for i, w := range m.wall {
		if w {
			g.cells[i] = Wall
		}
	}
	for side := 0; side < 2; side++ {
		p, f := m.Start(side)
		g.head[side] = p
		g.facing[side] = f
		g.cells[p.Y*m.w+p.X] = uint8(TrailA + side)
	}
	return g
}

// Over reports whether the game has ended.
func (g *Game) Over() bool { return g.winner != going }

// Turn is the number of turns played.
func (g *Game) Turn() int { return g.turn }

// Map returns the game's map.
func (g *Game) Map() Map { return g.m }

// Head returns a side's head in board coordinates.
func (g *Game) Head(side int) Point { return g.head[side] }

// Cell returns Empty, Wall, TrailA or TrailB. Outside the board is Wall.
func (g *Game) Cell(x, y int) int {
	if x < 0 || y < 0 || x >= g.m.w || y >= g.m.h {
		return Wall
	}
	return int(g.cells[y*g.m.w+x])
}

// View returns the read-only view a side's bot sees.
func (g *Game) View(side int) View { return View{g: g, side: side} }

// Apply resolves one turn from two move symbols (0-3 a direction in BOARD
// coordinates, 4 crashed). It is the only place the rules live; Play and
// Replay both go through it.
func (g *Game) Apply(symA, symB int) {
	if g.Over() {
		panic("rules: game is over")
	}
	sym := [2]int{symA, symB}
	var next [2]Point
	for s := 0; s < 2; s++ {
		if sym[s] < 0 || sym[s] > crashed {
			panic("rules: bad move symbol")
		}
		if sym[s] == crashed {
			g.death[s] = Crashed
			continue
		}
		next[s] = g.head[s].Step(Dir(sym[s]))
		switch g.Cell(next[s].X, next[s].Y) {
		case Empty:
		case Wall:
			g.death[s] = HitWall
		default:
			g.death[s] = HitTrail
		}
	}
	if g.death[0] == Alive && g.death[1] == Alive && next[0] == next[1] {
		g.death[0], g.death[1] = HitHead, HitHead
	}
	g.moves = append(g.moves, byte('a'+5*symA+symB))
	g.turn++
	deadA, deadB := g.death[0] != Alive, g.death[1] != Alive
	switch {
	case deadA && deadB:
		g.winner = Draw
		return
	case deadA:
		g.winner = WinB
		return
	case deadB:
		g.winner = WinA
		return
	}
	for s := 0; s < 2; s++ {
		g.head[s] = next[s]
		g.facing[s] = Dir(sym[s])
		g.cells[next[s].Y*g.m.w+next[s].X] = uint8(TrailA + s)
	}
}

// Result returns the outcome so far.
func (g *Game) Result() Result {
	return Result{Winner: g.winner, Turns: g.turn, DeathA: g.death[0], DeathB: g.death[1], Match: g.String()}
}

// String is the canonical match string: "v1.<mapkey>.<moves>".
func (g *Game) String() string { return "v1." + g.m.Key() + "." + string(g.moves) }

// Result is the outcome of a finished (or abandoned) game.
type Result struct {
	Winner int // Draw, WinA or WinB; -1 while the game is still going
	Turns  int
	DeathA int
	DeathB int
	Match  string
}

// Play runs a full game between two bots. A bot that panics or returns an
// invalid direction crashes that turn. A panic in a bot declared in an /r/
// realm aborts the whole transaction instead (Gno semantics); callers that
// need to survive that must not run untrusted realm code.
func Play(a, b Bot, m Map) Result {
	g := NewGame(m)
	g.Advance(a, b, -1)
	return g.Result()
}

// Advance plays up to n more turns (all remaining turns if n < 0) and
// returns how many were played. Together with ReplayTo it lets a long game
// be played across several transactions.
func (g *Game) Advance(a, b Bot, n int) int {
	played := 0
	for !g.Over() && (n < 0 || played < n) {
		symA := ask(a, g.View(SideA))
		symB := ask(b, g.View(SideB))
		if symB != crashed {
			symB = int(Dir(symB).Opposite()) // B answered in its rotated frame
		}
		g.Apply(symA, symB)
		played++
	}
	return played
}

// ask calls a bot and converts a panic or invalid answer into a crash.
func ask(bot Bot, v View) (sym int) {
	defer func() {
		if r := recover(); r != nil {
			sym = crashed
		}
	}()
	if bot == nil {
		return crashed
	}
	d := bot(v)
	if !d.Valid() {
		return crashed
	}
	return int(d)
}

// reach counts empty cells reachable from board cell (x, y), including it,
// stopping at limit. A non-empty start counts 0. It works on flat indexes
// with local slices because every call and field access costs gas.
func (g *Game) reach(x, y, limit int) int {
	w, h := g.m.w, g.m.h
	cells := g.cells
	if x < 0 || y < 0 || x >= w || y >= h || cells[y*w+x] != Empty || limit <= 0 {
		return 0
	}
	g.gen++
	gen := g.gen
	mark := g.mark
	q := g.queue[:0]
	c := y*w + x
	mark[c] = gen
	q = append(q, c)
	last := w*h - w
	for i := 0; i < len(q) && len(q) < limit; i++ {
		c = q[i]
		cx := c % w
		if cx > 0 {
			if n := c - 1; cells[n] == Empty && mark[n] != gen {
				mark[n] = gen
				q = append(q, n)
			}
		}
		if cx < w-1 {
			if n := c + 1; cells[n] == Empty && mark[n] != gen {
				mark[n] = gen
				q = append(q, n)
			}
		}
		if c >= w {
			if n := c - w; cells[n] == Empty && mark[n] != gen {
				mark[n] = gen
				q = append(q, n)
			}
		}
		if c < last {
			if n := c + w; cells[n] == Empty && mark[n] != gen {
				mark[n] = gen
				q = append(q, n)
			}
		}
	}
	g.queue = q
	if len(q) > limit {
		return limit
	}
	return len(q)
}

package rules

import "strconv"

// Map is an immutable board layout: size plus point-symmetric obstacles.
// It is fully identified by (W, H, Seed, Density).
type Map struct {
	w, h    int
	seed    uint32
	density int
	wall    []bool
}

// Cell contents of a board.
const (
	Empty  = 0
	Wall   = 1
	TrailA = 2
	TrailB = 3
)

const (
	MinSize = 8
	MaxSize = 40
)

// NewMap builds the map for the given size, seed and obstacle density (number
// of obstacle pairs). W and H must be even and within [MinSize, MaxSize].
// Seed 0 or density 0 gives an empty board. If a seed produces a board where
// the two starts are not connected, the next seed is tried (up to 32 times),
// so every map is playable.
func NewMap(w, h int, seed uint32, density int) Map {
	if w%2 != 0 || h%2 != 0 || w < MinSize || h < MinSize || w > MaxSize || h > MaxSize {
		panic("rules: map size must be even and within bounds")
	}
	if density < 0 || density > w*h/8 {
		panic("rules: density out of range")
	}
	m := Map{w: w, h: h, seed: seed, density: density}
	if seed == 0 || density == 0 {
		m.wall = make([]bool, w*h)
		return m
	}
	s := seed
	for try := 0; try < 32; try++ {
		m.wall = generate(w, h, s, density)
		if connected(m) {
			return m
		}
		s++
		if s == 0 {
			s = 1
		}
	}
	m.wall = make([]bool, w*h)
	return m
}

func (m Map) W() int       { return m.w }
func (m Map) H() int       { return m.h }
func (m Map) Seed() uint32 { return m.seed }
func (m Map) Density() int { return m.density }
func (m Map) Wall(x, y int) bool {
	if x < 0 || y < 0 || x >= m.w || y >= m.h {
		return true
	}
	return m.wall[y*m.w+x]
}

// Start returns the starting cell and facing of a side. Side B is side A
// rotated 180 degrees about the board centre.
func (m Map) Start(side int) (Point, Dir) {
	a := Point{2, m.h / 2}
	if side == SideA {
		return a, Right
	}
	return m.rot(a), Left
}

// rot rotates a point 180 degrees about the board centre.
func (m Map) rot(p Point) Point { return Point{m.w - 1 - p.X, m.h - 1 - p.Y} }

// Key is a compact text id used in match strings, e.g. "24x24s7d6".
func (m Map) Key() string {
	return strconv.Itoa(m.w) + "x" + strconv.Itoa(m.h) + "s" + strconv.FormatUint(uint64(m.seed), 10) + "d" + strconv.Itoa(m.density)
}

func xorshift(s uint32) uint32 {
	s ^= s << 13
	s ^= s >> 17
	s ^= s << 5
	return s
}

func generate(w, h int, seed uint32, density int) []bool {
	wall := make([]bool, w*h)
	m := Map{w: w, h: h}
	a, _ := m.Start(SideA)
	b, _ := m.Start(SideB)
	s := seed
	placed := 0
	for guard := 0; placed < density && guard < density*20; guard++ {
		s = xorshift(s)
		x := int(s % uint32(w))
		s = xorshift(s)
		y := int(s % uint32(h))
		p := Point{x, y}
		q := m.rot(p)
		if reserved(p, a) || reserved(p, b) || reserved(q, a) || reserved(q, b) {
			continue
		}
		if wall[y*w+x] {
			continue
		}
		wall[y*w+x] = true
		wall[q.Y*w+q.X] = true
		placed++
	}
	return wall
}

// reserved keeps each start and the cells around and ahead of it free.
func reserved(p, start Point) bool {
	ddx := p.X - start.X
	if ddx < 0 {
		ddx = -ddx
	}
	ddy := p.Y - start.Y
	if ddy < 0 {
		ddy = -ddy
	}
	return ddx <= 3 && ddy <= 1
}

// connected reports whether the two starts are joined by free cells.
func connected(m Map) bool {
	a, _ := m.Start(SideA)
	b, _ := m.Start(SideB)
	seen := make([]bool, m.w*m.h)
	queue := []Point{a}
	seen[a.Y*m.w+a.X] = true
	for len(queue) > 0 {
		p := queue[0]
		queue = queue[1:]
		if p == b {
			return true
		}
		for d := Dir(0); d < 4; d++ {
			n := p.Step(d)
			if m.Wall(n.X, n.Y) || seen[n.Y*m.w+n.X] {
				continue
			}
			seen[n.Y*m.w+n.X] = true
			queue = append(queue, n)
		}
	}
	return false
}

package rules

import (
	"errors"
	"strconv"
	"strings"
)

// ErrBadMatch is returned for a malformed match string.
var ErrBadMatch = errors.New("rules: bad match string")

// ParseMapKey parses "24x24s7d6".
func ParseMapKey(k string) (Map, error) {
	x := strings.Index(k, "x")
	s := strings.Index(k, "s")
	d := strings.Index(k, "d")
	if x < 1 || s < x+2 || d < s+2 || d == len(k)-1 {
		return Map{}, ErrBadMatch
	}
	w, e1 := strconv.Atoi(k[:x])
	h, e2 := strconv.Atoi(k[x+1 : s])
	seed, e3 := strconv.ParseUint(k[s+1:d], 10, 32)
	den, e4 := strconv.Atoi(k[d+1:])
	if e1 != nil || e2 != nil || e3 != nil || e4 != nil {
		return Map{}, ErrBadMatch
	}
	if w%2 != 0 || h%2 != 0 || w < MinSize || h < MinSize || w > MaxSize || h > MaxSize || den < 0 || den > w*h/8 {
		return Map{}, ErrBadMatch
	}
	return NewMap(w, h, uint32(seed), den), nil
}

// Decode splits a match string into its map and move symbols.
func Decode(match string) (Map, []byte, error) {
	parts := strings.Split(match, ".")
	if len(parts) != 3 || parts[0] != "v1" {
		return Map{}, nil, ErrBadMatch
	}
	m, err := ParseMapKey(parts[1])
	if err != nil {
		return Map{}, nil, err
	}
	mv := []byte(parts[2])
	for _, c := range mv {
		if c < 'a' || c > 'y' {
			return Map{}, nil, ErrBadMatch
		}
	}
	return m, mv, nil
}

// ReplayTo replays a match string up to turn t (all turns if t < 0) and
// returns the game at that point. It fails if the string has moves after
// the game ended.
func ReplayTo(match string, t int) (*Game, error) {
	m, mv, err := Decode(match)
	if err != nil {
		return nil, err
	}
	g := NewGame(m)
	for i, c := range mv {
		if t >= 0 && i >= t {
			break
		}
		if g.Over() {
			return nil, ErrBadMatch
		}
		v := int(c - 'a')
		g.Apply(v/5, v%5)
	}
	return g, nil
}

// Replay replays a whole match string and returns its result.
func Replay(match string) (Result, error) {
	g, err := ReplayTo(match, -1)
	if err != nil {
		return Result{}, err
	}
	return g.Result(), nil
}

// Package rules is the pure rule book of Ribbonfight, a two-player grid duel.
//
// Each player is a ribbon that moves one cell per turn and leaves a solid
// trail. Moving into a wall, an obstacle, any trail, or the cell the other
// head enters at the same time kills the ribbon. Both moves of a turn resolve
// simultaneously.
//
// The package has no chain imports: no address, no height, no clock. A game
// is fully described by its map and its move string, so everything else
// (the board at any turn, the winner, the end reason) is derived by replay.
package rules

// Dir is a direction. Bots return one per turn.
type Dir uint8

const (
	Up Dir = iota
	Right
	Down
	Left
)

// crashed is the move symbol recorded when a bot panics or returns an
// invalid direction.
const crashed = 4

var (
	dx = [4]int{0, 1, 0, -1}
	dy = [4]int{-1, 0, 1, 0}
)

// Valid reports whether d is one of the four directions.
func (d Dir) Valid() bool { return d <= Left }

// Opposite returns the reverse direction.
func (d Dir) Opposite() Dir { return (d + 2) % 4 }

// String returns u, r, d or l.
func (d Dir) String() string {
	if !d.Valid() {
		return "?"
	}
	return string("urdl"[d])
}

// ParseDir parses u, r, d or l.
func ParseDir(c byte) (Dir, bool) {
	switch c {
	case 'u':
		return Up, true
	case 'r':
		return Right, true
	case 'd':
		return Down, true
	case 'l':
		return Left, true
	}
	return 0, false
}

// Point is a board cell. (0, 0) is the top-left corner.
type Point struct {
	X, Y int
}

// Step returns the neighbour of p in direction d.
func (p Point) Step(d Dir) Point {
	return Point{p.X + dx[d&3], p.Y + dy[d&3]}
}

// Side identifies a player.
const (
	SideA = 0
	SideB = 1
)

// Winner values of a Result.
const (
	Draw  = 0
	WinA  = 1
	WinB  = 2
	going = -1
)

// Death causes.
const (
	Alive    = 0
	HitWall  = 1 // left the board or hit an obstacle
	HitTrail = 2 // hit a trail (either ribbon)
	HitHead  = 3 // both heads entered the same cell
	Crashed  = 4 // the bot panicked or returned an invalid direction
)

// Bot is a ribbon's brain. It is called once per turn with a read-only view
// in which it always plays from side A's perspective (side B's view is the
// board rotated 180 degrees). It must be deterministic for the league to be
// fair, which is automatic for a function in a /p/ package.
type Bot func(v View) Dir

package rules

// View is what a bot sees: a read-only window on the game, always from side
// A's perspective. For side B every coordinate and direction is rotated 180
// degrees, so the same bot code works on both sides and the two sides are
// exactly symmetric.
type View struct {
	g    *Game
	side int
}

// W and H are the board size.
func (v View) W() int { return v.g.m.w }
func (v View) H() int { return v.g.m.h }

// Turn is the number of turns already played.
func (v View) Turn() int { return v.g.turn }

func (v View) toBoard(x, y int) (int, int) {
	if v.side == SideB {
		return v.g.m.w - 1 - x, v.g.m.h - 1 - y
	}
	return x, y
}

func (v View) fromBoard(p Point) Point {
	if v.side == SideB {
		return v.g.m.rot(p)
	}
	return p
}

// Free reports whether a cell is inside the board and empty.
func (v View) Free(x, y int) bool {
	g := v.g
	w, h := g.m.w, g.m.h
	if v.side == SideB {
		x, y = w-1-x, h-1-y
	}
	if x < 0 || y < 0 || x >= w || y >= h {
		return false
	}
	return g.cells[y*w+x] == Empty
}

// Mine reports whether a cell holds this bot's own trail.
func (v View) Mine(x, y int) bool {
	bx, by := v.toBoard(x, y)
	return v.g.Cell(bx, by) == TrailA+v.side
}

// Theirs reports whether a cell holds the opponent's trail.
func (v View) Theirs(x, y int) bool {
	bx, by := v.toBoard(x, y)
	return v.g.Cell(bx, by) == TrailA+1-v.side
}

// Me and Opp return the two heads.
func (v View) Me() Point  { return v.fromBoard(v.g.head[v.side]) }
func (v View) Opp() Point { return v.fromBoard(v.g.head[1-v.side]) }

// Heading is the direction this ribbon moved last turn (its start facing on
// turn 0), in the bot's own frame.
func (v View) Heading() Dir {
	f := v.g.facing[v.side]
	if v.side == SideB {
		return f.Opposite()
	}
	return f
}

// Reach counts the empty cells reachable from (x, y) through empty cells,
// including (x, y) itself, and stops counting at limit. It returns 0 if
// (x, y) is not empty. It is the cheap way for a bot to measure room: it
// runs on the board directly with no allocations.
func (v View) Reach(x, y, limit int) int {
	bx, by := v.toBoard(x, y)
	return v.g.reach(bx, by, limit)
}

// FreeDirs returns how many of the four neighbours of (x, y) are empty.
func (v View) FreeDirs(x, y int) int {
	n := 0
	if v.Free(x+1, y) {
		n++
	}
	if v.Free(x-1, y) {
		n++
	}
	if v.Free(x, y+1) {
		n++
	}
	if v.Free(x, y-1) {
		n++
	}
	return n
}

// Package svg draws Ribbonfight boards and replays as SVG images.
//
// gnoweb strips raw <svg> from Markdown, so every picture is returned as a
// data URI that Markdown can embed with ![alt](uri). Replays animate with
// SMIL inside the image (no script), which gnoweb's CSP allows.
//
// Coordinates use one unit per cell; trails are single paths through cell
// centres, so an image stays small even for long games.
package svg

import (
	"encoding/base64"
	"strconv"
	"strings"

	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/rfrh1/rules/v1"
)

// Colours.
const (
	bg     = "#14141c"
	grid   = "#1f1f2b"
	wall   = "#4a4a5e"
	colA   = "#ff3df0"
	colB   = "#2de2ff"
	dead   = "#ff4040"
	cellPx = 16
)

// Track is the list of cells a ribbon occupied, in order, plus how it died.
type Track struct {
	Cells []rules.Point
	Death int
}

// Tracks replays a match string up to turn t (t < 0 for the whole game) and
// returns the board map, both tracks and the game.
func Tracks(match string, t int) (rules.Map, [2]Track, *rules.Game, error) {
	var tr [2]Track
	m, mv, err := rules.Decode(match)
	if err != nil {
		return m, tr, nil, err
	}
	g := rules.NewGame(m)
	for s := 0; s < 2; s++ {
		tr[s].Cells = append(tr[s].Cells, g.Head(s))
	}
	for i, c := range mv {
		if t >= 0 && i >= t {
			break
		}
		if g.Over() {
			return m, tr, nil, rules.ErrBadMatch
		}
		v := int(c - 'a')
		g.Apply(v/5, v%5)
		if !g.Over() {
			for s := 0; s < 2; s++ {
				tr[s].Cells = append(tr[s].Cells, g.Head(s))
			}
		}
	}
	r := g.Result()
	tr[0].Death, tr[1].Death = r.DeathA, r.DeathB
	return m, tr, g, nil
}

// Frame returns an SVG of the board after turn t (t < 0 for the end).
func Frame(match string, t int) (string, error) {
	m, tr, _, err := Tracks(match, t)
	if err != nil {
		return "", err
	}
	var b strings.Builder
	open(&b, m)
	for s := 0; s < 2; s++ {
		b.WriteString(`<path d="` + pathD(tr[s].Cells) + `" stroke="` + color(s) + `" stroke-width="0.62" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`)
	}
	for s := 0; s < 2; s++ {
		head(&b, tr[s], s, "")
	}
	b.WriteString("</svg>")
	return b.String(), nil
}

// Animated returns an SVG that replays the whole match and loops, holding the
// final position for a moment. stepMs is the time per turn.
func Animated(match string, stepMs int) (string, error) {
	m, tr, _, err := Tracks(match, -1)
	if err != nil {
		return "", err
	}
	if stepMs < 20 {
		stepMs = 20
	}
	segs := len(tr[0].Cells) - 1
	playMs := segs * stepMs
	if playMs < 400 {
		playMs = 400
	}
	holdMs := 1800
	total := playMs + holdMs
	split := ratio(playMs, total)
	dur := strconv.Itoa(total) + "ms"
	var b strings.Builder
	open(&b, m)
	L := strconv.Itoa(segs + 1)
	for s := 0; s < 2; s++ {
		b.WriteString(`<path d="` + pathD(tr[s].Cells) + `" stroke="` + color(s) + `" stroke-width="0.62" fill="none" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="` + L + ` ` + L + `" stroke-dashoffset="` + L + `">`)
		b.WriteString(`<animate attributeName="stroke-dashoffset" values="` + L + `;0;0" keyTimes="0;` + split + `;1" dur="` + dur + `" repeatCount="indefinite"/></path>`)
	}
	// Death markers fade in when the replay reaches the end.
	anim := `<animate attributeName="opacity" values="0;0;1;1" keyTimes="0;` + split + `;` + split + `;1" dur="` + dur + `" repeatCount="indefinite"/>`
	for s := 0; s < 2; s++ {
		head(&b, tr[s], s, anim)
	}
	b.WriteString("</svg>")
	return b.String(), nil
}

// DataURI wraps an SVG document for Markdown image embedding.
func DataURI(svg string) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(svg))
}

// Image returns a Markdown image of an SVG document. alt is escaped.
func Image(alt, svg string) string {
	return "![" + escapeAlt(alt) + "](" + DataURI(svg) + ")"
}

func open(b *strings.Builder, m rules.Map) {
	w, h := strconv.Itoa(m.W()), strconv.Itoa(m.H())
	b.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" width="` + strconv.Itoa(m.W()*cellPx) + `" height="` + strconv.Itoa(m.H()*cellPx) + `" viewBox="0 0 ` + w + ` ` + h + `">`)
	b.WriteString(`<defs><pattern id="g" width="1" height="1" patternUnits="userSpaceOnUse"><path d="M1 0H0V1" fill="none" stroke="` + grid + `" stroke-width="0.06"/></pattern></defs>`)
	b.WriteString(`<rect width="` + w + `" height="` + h + `" fill="` + bg + `"/><rect width="` + w + `" height="` + h + `" fill="url(#g)"/>`)
	// Walls as one path of unit squares.
	var wp strings.Builder
	for y := 0; y < m.H(); y++ {
		for x := 0; x < m.W(); x++ {
			if m.Wall(x, y) {
				wp.WriteString("M" + strconv.Itoa(x) + " " + strconv.Itoa(y) + "h1v1h-1z")
			}
		}
	}
	if wp.Len() > 0 {
		b.WriteString(`<path d="` + wp.String() + `" fill="` + wall + `"/>`)
	}
}

func head(b *strings.Builder, t Track, side int, anim string) {
	p := t.Cells[len(t.Cells)-1]
	cx, cy := half(p.X), half(p.Y)
	b.WriteString(`<circle cx="` + cx + `" cy="` + cy + `" r="0.42" fill="` + color(side) + `"`)
	if anim != "" {
		// The head rides along with the trail only at the end; keep it simple.
		b.WriteString(` opacity="0">` + anim + `</circle>`)
	} else {
		b.WriteString(`/>`)
	}
	if t.Death == rules.Alive {
		return
	}
	x0, y0 := strconv.Itoa(p.X), strconv.Itoa(p.Y)
	b.WriteString(`<path d="M` + x0 + ` ` + y0 + `l1 1M` + strconv.Itoa(p.X+1) + ` ` + y0 + `l-1 1" stroke="` + dead + `" stroke-width="0.22"`)
	if anim != "" {
		b.WriteString(` opacity="0">` + anim + `</path>`)
	} else {
		b.WriteString(`/>`)
	}
}

func pathD(cells []rules.Point) string {
	var b strings.Builder
	for i, p := range cells {
		if i == 0 {
			b.WriteString("M")
		} else {
			b.WriteString("L")
		}
		b.WriteString(half(p.X) + " " + half(p.Y))
	}
	if len(cells) == 1 {
		b.WriteString("h0.01")
	}
	return b.String()
}

func half(n int) string { return strconv.Itoa(n) + ".5" }

func color(side int) string {
	if side == rules.SideA {
		return colA
	}
	return colB
}

// ratio formats a/b with 3 decimals, for keyTimes.
func ratio(a, b int) string {
	v := a * 1000 / b
	s := strconv.Itoa(v)
	for len(s) < 3 {
		s = "0" + s
	}
	return "0." + s
}

func escapeAlt(s string) string {
	r := strings.NewReplacer("[", "", "]", "", "(", "", ")", "", "<", "", ">", "", "\n", " ")
	return r.Replace(s)
}

// Package wall is Ribbonfight's easy house bot: it keeps going straight and,
// when blocked, turns left if it can, otherwise right. No look-ahead.
package wall

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/rfrh1/rules/v1"

// Move is the bot.
func Move(v rules.View) rules.Dir {
	h := v.Heading()
	me := v.Me()
	for _, d := range []rules.Dir{h, (h + 3) % 4, (h + 1) % 4} {
		n := me.Step(d)
		if v.Free(n.X, n.Y) {
			return d
		}
	}
	return h
}

// Package space is Ribbonfight's medium house bot. Among its free moves it
// picks the one with the most room nearby (a small flood fill), steers away
// from cells the opponent's head could also enter, and prefers to keep its
// heading on ties.
package space

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/rfrh1/rules/v1"

// Budget caps the room count per candidate move.
const Budget = 12

// Move is the bot.
func Move(v rules.View) rules.Dir {
	me, opp, h := v.Me(), v.Opp(), v.Heading()
	best, bestScore := h, -1000
	for i := 0; i < 4; i++ {
		d := (h + rules.Dir(i)) % 4
		n := me.Step(d)
		if !v.Free(n.X, n.Y) {
			continue
		}
		score := 4 * v.Reach(n.X, n.Y, Budget)
		if abs(n.X-opp.X)+abs(n.Y-opp.Y) == 1 {
			score -= 20
		}
		if d == h {
			score++
		}
		if score > bestScore {
			best, bestScore = d, score
		}
	}
	return best
}

func abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

// Package flood is Ribbonfight's hard house bot. For each free move it
// measures how much room it keeps with a flood fill, breaks ties by hugging
// walls (fewer free neighbours wastes less space), and avoids head-on
// collisions unless it is cornered.
//
// To stay cheap in gas it first counts room with a small budget and only
// runs the deep count when two or more moves look equally roomy and one of
// them passes through a narrow cell, which is when sealing a pocket is a
// real risk.
package flood

import "gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/rfrh1/rules/v1"

const (
	Shallow = 20
	Deep    = 150
)

// Move is the bot.
func Move(v rules.View) rules.Dir {
	me, opp, h := v.Me(), v.Opp(), v.Heading()
	var cand [4]rules.Dir
	var room, nbr [4]int
	n := 0
	capped, narrow := 0, false
	for i := 0; i < 4; i++ {
		d := (h + rules.Dir(i)) % 4
		p := me.Step(d)
		if !v.Free(p.X, p.Y) {
			continue
		}
		cand[n] = d
		room[n] = v.Reach(p.X, p.Y, Shallow)
		nbr[n] = v.FreeDirs(p.X, p.Y)
		if room[n] == Shallow {
			capped++
			if nbr[n] <= 2 {
				narrow = true
			}
		}
		n++
	}
	if n == 0 {
		return h
	}
	if capped >= 2 && narrow {
		for k := 0; k < n; k++ {
			if room[k] == Shallow {
				p := me.Step(cand[k])
				room[k] = v.Reach(p.X, p.Y, Deep)
			}
		}
	}
	best, bestScore := cand[0], -100000
	for k := 0; k < n; k++ {
		p := me.Step(cand[k])
		score := 16*room[k] - 2*nbr[k]
		if abs(p.X-opp.X)+abs(p.Y-opp.Y) == 1 {
			score -= 400
		}
		if cand[k] == h {
			score++
		}
		if score > bestScore {
			best, bestScore = cand[k], score
		}
	}
	return best
}

func abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

// Package arena runs the Ribbonfight league on chain.
//
// Bots are Go functions, ideally in /p/ packages, registered by small entry
// realms from their init. Every pair of bots plays exactly one game on each
// league map. Games are deterministic, so anyone may push a pending game
// forward with PlayPair, a chunk of turns per transaction, and everyone gets
// the same result. The realm stores only match strings; boards, winners and
// pictures are derived by replay.
package arena

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/rfrh1/rules/v1"
	"gno.land/p/nt/avl/v0"
)

// League maps (24x24). Their keys are part of every match string.
var maps = []mapInfo{
	{"Open field", 0, 0},
	{"Pillars", 11, 14},
	{"Maze", 29, 30},
}

type mapInfo struct {
	Name    string
	Seed    uint32
	Density int
}

const (
	boardSize = 24
	maxChunk  = 100
	maxBots   = 64
)

// Bot is a registered player.
type Bot struct {
	ID      uint64
	Name    string
	Owner   address
	Entry   string // realm that registered the bot
	Brain   string // package the author says holds the logic (unverified)
	Height  int64
	Retired bool
	Points  int
	Wins    int
	Draws   int
	Losses  int
	Crashes int
	fn      rules.Bot
}

// Game is one league game between two bots on one map.
type Game struct {
	A, B    uint64 // A < B; A plays side A
	Map     int
	Match   string
	Done    bool
	Winner  int // rules.Draw, rules.WinA or rules.WinB once Done
	Turns   int
	Started int64
	Ended   int64
}

var (
	admin   address
	paused  bool
	playing bool

	bots    avl.Tree // id key -> *Bot
	byName  avl.Tree // name -> id
	byEntry avl.Tree // entry realm path -> id
	games   avl.Tree // game key -> *Game
	done    avl.Tree // finish order key -> game key
	nextID  uint64
	nDone   int
	lastKey string
)

// deployer is the initial admin. It can pause the arena, retire bots whose
// games cannot complete, and hand the role on.
const deployer = address("g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d")

func init() {
	admin = deployer
}

// guard rejects calls while paused or while a game is running (so a bot
// declared in a realm cannot call back into the arena mid-game).
func guard() {
	if playing {
		panic("arena: re-entrant call")
	}
}

func idKey(id uint64) string {
	s := strconv.FormatUint(id, 10)
	for len(s) < 6 {
		s = "0" + s
	}
	return s
}

func gameKey(a, b uint64, m int) string { return idKey(a) + "-" + idKey(b) + "-" + strconv.Itoa(m) }

func leagueMap(i int) rules.Map {
	mi := maps[i]
	return rules.NewMap(boardSize, boardSize, mi.Seed, mi.Density)
}

// Register adds a bot. It must be called by a realm (normally from the
// entry realm's init); that realm path becomes the bot's entry and may
// register only once. name: 3 to 24 chars of a-z, 0-9 and '-'. brain is the
// package path holding the bot's logic, shown as its claimed source.
func Register(cur realm, name, brain string, fn rules.Bot) uint64 {
	guard()
	if paused {
		panic("arena: paused")
	}
	entry := cur.Previous().PkgPath()
	if entry == "" {
		panic("arena: Register must be called from a realm")
	}
	if fn == nil {
		panic("arena: nil bot")
	}
	if !validName(name) {
		panic("arena: name must be 3-24 chars of a-z, 0-9, -")
	}
	if byName.Has(name) {
		panic("arena: name taken")
	}
	if byEntry.Has(entry) {
		panic("arena: this realm already registered a bot")
	}
	if !validPath(brain) {
		panic("arena: brain must be a gno.land/p/ or gno.land/r/ path")
	}
	if bots.Size() >= maxBots {
		panic("arena: league is full")
	}
	nextID++
	b := &Bot{ID: nextID, Name: name, Owner: unsafe.OriginCaller(), Entry: entry, Brain: brain, Height: runtime.ChainHeight(), fn: fn}
	bots.Set(idKey(b.ID), b)
	byName.Set(name, b.ID)
	byEntry.Set(entry, b.ID)
	chain.Emit("BotRegistered", "id", strconv.FormatUint(b.ID, 10), "name", name, "entry", entry)
	return b.ID
}

// PlayPair advances the game between bots a and b on league map m by up to
// n turns (1 to 100). Anyone may call it. It returns the game's status. A
// finished game is never replayed, so calling it again is a no-op.
func PlayPair(cur realm, a, b uint64, m int, n int) string {
	guard()
	if paused {
		panic("arena: paused")
	}
	if a == b {
		panic("arena: a bot does not play itself")
	}
	if a > b {
		a, b = b, a
	}
	if m < 0 || m >= len(maps) {
		panic("arena: unknown map")
	}
	if n < 1 || n > maxChunk {
		panic("arena: n must be 1 to 100")
	}
	ba, bb := mustBot(a), mustBot(b)
	if ba.Retired || bb.Retired {
		panic("arena: retired bot")
	}
	key := gameKey(a, b, m)
	var gm *Game
	if v := games.Get(key); v != nil {
		gm = v.(*Game)
	} else {
		gm = &Game{A: a, B: b, Map: m, Match: rules.NewGame(leagueMap(m)).String(), Started: runtime.ChainHeight()}
		games.Set(key, gm)
	}
	if gm.Done {
		return status(gm)
	}
	g, err := rules.ReplayTo(gm.Match, -1)
	if err != nil {
		panic("arena: corrupt match")
	}
	playing = true
	g.Advance(ba.fn, bb.fn, n)
	playing = false
	gm.Match = g.String()
	gm.Turns = g.Turn()
	if g.Over() {
		finish(gm, g.Result(), ba, bb, key)
	}
	return status(gm)
}

func finish(gm *Game, r rules.Result, ba, bb *Bot, key string) {
	gm.Done = true
	gm.Winner = r.Winner
	gm.Ended = runtime.ChainHeight()
	switch r.Winner {
	case rules.WinA:
		ba.Points += 2
		ba.Wins++
		bb.Losses++
	case rules.WinB:
		bb.Points += 2
		bb.Wins++
		ba.Losses++
	default:
		ba.Points++
		bb.Points++
		ba.Draws++
		bb.Draws++
	}
	if r.DeathA == rules.Crashed {
		ba.Crashes++
	}
	if r.DeathB == rules.Crashed {
		bb.Crashes++
	}
	nDone++
	done.Set(idKey(uint64(nDone)), key)
	lastKey = key
	chain.Emit("GamePlayed", "key", key, "winner", strconv.Itoa(r.Winner), "turns", strconv.Itoa(r.Turns))
}

func status(gm *Game) string {
	if !gm.Done {
		return "pending at turn " + strconv.Itoa(gm.Turns)
	}
	switch gm.Winner {
	case rules.WinA:
		return "done: " + botName(gm.A) + " won in " + strconv.Itoa(gm.Turns)
	case rules.WinB:
		return "done: " + botName(gm.B) + " won in " + strconv.Itoa(gm.Turns)
	}
	return "done: draw in " + strconv.Itoa(gm.Turns)
}

// Pause stops Register and PlayPair (admin only).
func Pause(cur realm, on bool) {
	assertAdmin(cur)
	paused = on
	chain.Emit("Paused", "on", strconv.FormatBool(on))
}

// Retire removes a bot from the league table and from future games (admin
// only). Use it for bots whose games cannot complete; finished games keep
// their results.
func Retire(cur realm, id uint64) {
	assertAdmin(cur)
	b := mustBot(id)
	b.Retired = true
	chain.Emit("BotRetired", "id", strconv.FormatUint(id, 10))
}

// TransferAdmin hands the admin role to another address (admin only).
func TransferAdmin(cur realm, to address) {
	assertAdmin(cur)
	if !to.IsValid() {
		panic("arena: invalid address")
	}
	admin = to
}

func assertAdmin(cur realm) {
	guard()
	if cur.Previous().Address() != admin {
		panic("arena: admin only")
	}
}

func mustBot(id uint64) *Bot {
	v := bots.Get(idKey(id))
	if v == nil {
		panic("arena: unknown bot")
	}
	return v.(*Bot)
}

func getBot(id uint64) (*Bot, bool) {
	v := bots.Get(idKey(id))
	if v == nil {
		return nil, false
	}
	return v.(*Bot), true
}

func botName(id uint64) string {
	if b, ok := getBot(id); ok {
		return b.Name
	}
	return "?"
}

func validName(s string) bool {
	if len(s) < 3 || len(s) > 24 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-') {
			return false
		}
	}
	return true
}

func validPath(s string) bool {
	if !(strings.HasPrefix(s, "gno.land/p/") || strings.HasPrefix(s, "gno.land/r/")) || len(s) > 120 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '/' || c == '_' || c == '.' || c == '-') {
			return false
		}
	}
	return true
}

package arena

import (
	"strconv"
	"strings"

	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/rfrh1/rules/v1"
	"gno.land/p/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/rfrh1/svg/v1"
	"gno.land/p/moul/txlink/v0"
)

const pageSize = 20

// Render serves the arena pages:
//
//	""                       home: latest game replay, top of the table
//	"table"                  full league table
//	"bot/<id>"               one bot: record, games, source links
//	"game/<key>"             one game: animated replay, step links
//	"game/<key>/t/<turn>"    the board after a given turn
//	"games[?page=N]"         finished games, newest first
//	"pending"                games still to play, with PlayPair links
//	"guide"                  how to write and register a bot
func Render(path string) string {
	path, page := splitPage(path)
	parts := strings.Split(path, "/")
	switch {
	case path == "":
		return renderHome()
	case path == "table":
		return renderTable(0)
	case parts[0] == "bot" && len(parts) == 2:
		id, err := strconv.ParseUint(parts[1], 10, 64)
		if err != nil {
			return notFound()
		}
		return renderBot(id)
	case parts[0] == "game" && len(parts) == 2:
		return renderGame(parts[1], -1)
	case parts[0] == "game" && len(parts) == 4 && parts[2] == "t":
		t, err := strconv.Atoi(parts[3])
		if err != nil || t < 0 {
			return notFound()
		}
		return renderGame(parts[1], t)
	case path == "games":
		return renderGames(page)
	case path == "pending":
		return renderPending(page)
	case path == "guide":
		return renderGuide()
	}
	return notFound()
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Ribbonfight\n\n")
	b.WriteString("A grid duel where the players are Go programs you can read. Each ribbon moves one cell per turn and leaves a wall behind it; crash into anything and you lose.\n\n")
	if lastKey != "" {
		gm := games.Get(lastKey).(*Game)
		b.WriteString("## Latest game\n\n")
		b.WriteString(gameTitle(gm) + "\n\n")
		if img, err := svg.Animated(gm.Match, 60); err == nil {
			b.WriteString(svg.Image("latest game replay", img) + "\n\n")
		}
		b.WriteString(resultLine(gm) + " [Step through it](" + link("game/"+lastKey) + ")\n\n")
	}
	b.WriteString("## League\n\n")
	b.WriteString(renderTableBody(10))
	b.WriteString("\n[Full table](" + link("table") + ") | [Finished games](" + link("games") + ") | [Pending games](" + link("pending") + ") | [Write a bot](" + link("guide") + ")\n")
	return b.String()
}

func renderTable(limit int) string {
	return "# League table\n\nEvery pair of bots plays once on each of the " + strconv.Itoa(len(maps)) + " maps. Win 2, draw 1, loss 0; unplayed games count 0.\n\n" + renderTableBody(limit) + "\n[Home](" + link("") + ")\n"
}

func renderTableBody(limit int) string {
	list := activeBots()
	sortBots(list, func(x, y *Bot) bool {
		if x.Points != y.Points {
			return x.Points > y.Points
		}
		if x.Wins != y.Wins {
			return x.Wins > y.Wins
		}
		return x.ID < y.ID
	})
	if len(list) == 0 {
		return "_No bots yet._\n"
	}
	var b strings.Builder
	b.WriteString("| # | Bot | Pts | W | D | L | Crashes | Played |\n|---|---|---|---|---|---|---|---|\n")
	total := (len(list) - 1) * len(maps)
	for i, bt := range list {
		if limit > 0 && i >= limit {
			break
		}
		played := bt.Wins + bt.Draws + bt.Losses
		b.WriteString("| " + strconv.Itoa(i+1) + " | [" + bt.Name + "](" + link("bot/"+u(bt.ID)) + ") | " + strconv.Itoa(bt.Points) + " | " + strconv.Itoa(bt.Wins) + " | " + strconv.Itoa(bt.Draws) + " | " + strconv.Itoa(bt.Losses) + " | " + strconv.Itoa(bt.Crashes) + " | " + strconv.Itoa(played) + "/" + strconv.Itoa(total) + " |\n")
	}
	return b.String()
}

func renderBot(id uint64) string {
	bt, ok := getBot(id)
	if !ok {
		return notFound()
	}
	var b strings.Builder
	b.WriteString("# " + bt.Name + "\n\n")
	if bt.Retired {
		b.WriteString("**Retired** by the admin: it no longer plays.\n\n")
	}
	b.WriteString("- Points " + strconv.Itoa(bt.Points) + ", record " + strconv.Itoa(bt.Wins) + "-" + strconv.Itoa(bt.Draws) + "-" + strconv.Itoa(bt.Losses) + ", crashes " + strconv.Itoa(bt.Crashes) + "\n")
	b.WriteString("- Brain (claimed source): [" + bt.Brain + "](" + webPath(bt.Brain) + "$source)\n")
	b.WriteString("- Entry realm: [" + bt.Entry + "](" + webPath(bt.Entry) + "$source)\n")
	b.WriteString("- Owner: " + bt.Owner.String() + ", registered at block " + strconv.FormatInt(bt.Height, 10) + "\n\n")
	b.WriteString("## Games\n\n| Opponent | Map | Result |\n|---|---|---|\n")
	for _, o := range allBots() {
		if o.ID == id {
			continue
		}
		for m := range maps {
			a, c := id, o.ID
			if a > c {
				a, c = c, a
			}
			key := gameKey(a, c, m)
			res := "not played"
			if v := games.Get(key); v != nil {
				gm := v.(*Game)
				res = "[" + outcomeFor(gm, id) + "](" + link("game/"+key) + ")"
			}
			if res == "not played" && !o.Retired && !bt.Retired {
				res = "[play](" + playLink(a, c, m) + ")"
			}
			b.WriteString("| [" + o.Name + "](" + link("bot/"+u(o.ID)) + ") | " + maps[m].Name + " | " + res + " |\n")
		}
	}
	b.WriteString("\n[Table](" + link("table") + ")\n")
	return b.String()
}

func renderGame(key string, t int) string {
	v := games.Get(key)
	if v == nil {
		return notFound()
	}
	gm := v.(*Game)
	var b strings.Builder
	b.WriteString("# " + gameTitle(gm) + "\n\n")
	g, err := rules.ReplayTo(gm.Match, t)
	if err != nil {
		return notFound()
	}
	if t < 0 && gm.Done {
		if img, err := svg.Animated(gm.Match, 60); err == nil {
			b.WriteString(svg.Image("replay", img) + "\n\n")
		}
	} else {
		if img, err := svg.Frame(gm.Match, t); err == nil {
			b.WriteString(svg.Image("board", img) + "\n\n")
		}
	}
	b.WriteString(resultLine(gm) + "\n\n")
	cur := g.Turn()
	b.WriteString("Turn " + strconv.Itoa(cur) + " of " + strconv.Itoa(gm.Turns) + ": ")
	b.WriteString("[start](" + link("game/"+key+"/t/0") + ")")
	if cur > 0 {
		b.WriteString(" | [-10](" + link("game/"+key+"/t/"+strconv.Itoa(max0(cur-10))) + ") | [-1](" + link("game/"+key+"/t/"+strconv.Itoa(cur-1)) + ")")
	}
	if cur < gm.Turns {
		b.WriteString(" | [+1](" + link("game/"+key+"/t/"+strconv.Itoa(cur+1)) + ") | [+10](" + link("game/"+key+"/t/"+strconv.Itoa(minInt(cur+10, gm.Turns))) + ")")
	}
	b.WriteString(" | [replay](" + link("game/"+key) + ")\n\n")
	if !gm.Done {
		b.WriteString("This game is still pending: [play the next 40 turns](" + playLink(gm.A, gm.B, gm.Map) + ").\n\n")
	}
	b.WriteString("Match string (the whole game; replay it with `rules.Replay`):\n\n```\n" + gm.Match + "\n```\n")
	return b.String()
}

func renderGames(page int) string {
	var b strings.Builder
	b.WriteString("# Finished games\n\n")
	if nDone == 0 {
		return b.String() + "_None yet._\n"
	}
	b.WriteString("| Game | Map | Result |\n|---|---|---|\n")
	skip := page * pageSize
	n := 0
	done.ReverseIterate("", "", func(_ string, v any) bool {
		if skip > 0 {
			skip--
			return false
		}
		key := v.(string)
		gm := games.Get(key).(*Game)
		b.WriteString("| [" + botName(gm.A) + " vs " + botName(gm.B) + "](" + link("game/"+key) + ") | " + maps[gm.Map].Name + " | " + resultLine(gm) + " |\n")
		n++
		return n >= pageSize
	})
	b.WriteString(pager("games", page, nDone))
	return b.String()
}

func renderPending(page int) string {
	var b strings.Builder
	b.WriteString("# Pending games\n\nAnyone can play these: each click plays up to 40 turns.\n\n| Game | Map | Progress |\n|---|---|---|\n")
	list := activeBots()
	sortBots(list, func(x, y *Bot) bool { return x.ID < y.ID })
	count, shown := 0, 0
	for i := 0; i < len(list); i++ {
		for j := i + 1; j < len(list); j++ {
			for m := range maps {
				a, c := list[i].ID, list[j].ID
				key := gameKey(a, c, m)
				turns := 0
				if v := games.Get(key); v != nil {
					gm := v.(*Game)
					if gm.Done {
						continue
					}
					turns = gm.Turns
				}
				count++
				if count <= page*pageSize || shown >= pageSize {
					continue
				}
				shown++
				b.WriteString("| " + list[i].Name + " vs " + list[j].Name + " | " + maps[m].Name + " | turn " + strconv.Itoa(turns) + ", [play](" + playLink(a, c, m) + ") |\n")
			}
		}
	}
	if count == 0 {
		return "# Pending games\n\n_Nothing to play: the table is complete._\n"
	}
	b.WriteString(pager("pending", page, count))
	return b.String()
}

func renderGuide() string {
	return `# Write a Ribbonfight bot

A bot is one Go function:

` + "```go" + `
func Move(v rules.View) rules.Dir
` + "```" + `

It is called once per turn. ` + "`v`" + ` always shows the board from your side (side B sees it rotated), so the same code works on both sides. Return ` + "`rules.Up`, `rules.Right`, `rules.Down` or `rules.Left`" + `. Useful calls: ` + "`v.Me()`, `v.Opp()`, `v.Heading()`, `v.Free(x, y)`, `v.FreeDirs(x, y)`, `v.Reach(x, y, limit)`" + `.

1. Put the function in a /p/ package (so its source is public and a panic only loses you the game).
2. Deploy a tiny entry realm whose init registers it:

` + "```go" + `
func init(cur realm) {
	arena.Register(cross(cur), "my-bot", "gno.land/p/<you>/mybot/v1", mybot.Move)
}
` + "```" + `

3. Play your games from your bot page, or let the keeper do it.

Gas budget: keep each move under 10M gas. A function call costs about 15k gas and a flood-fill cell about 21k, so ` + "`v.Reach(x, y, 150)`" + ` is about 3M. A move that runs out of gas makes the game unplayable: it stays pending and scores 0 for both bots.

[Home](` + link("") + `)
`
}

// helpers

func activeBots() []*Bot {
	var out []*Bot
	bots.Iterate("", "", func(_ string, v any) bool {
		if b := v.(*Bot); !b.Retired {
			out = append(out, b)
		}
		return false
	})
	return out
}

func allBots() []*Bot {
	var out []*Bot
	bots.Iterate("", "", func(_ string, v any) bool {
		out = append(out, v.(*Bot))
		return false
	})
	return out
}

func gameTitle(gm *Game) string {
	return botName(gm.A) + " (pink) vs " + botName(gm.B) + " (cyan), " + maps[gm.Map].Name
}

func resultLine(gm *Game) string {
	if !gm.Done {
		return "Pending at turn " + strconv.Itoa(gm.Turns) + "."
	}
	switch gm.Winner {
	case rules.WinA:
		return "**" + botName(gm.A) + "** won in " + strconv.Itoa(gm.Turns) + " turns."
	case rules.WinB:
		return "**" + botName(gm.B) + "** won in " + strconv.Itoa(gm.Turns) + " turns."
	}
	return "Draw after " + strconv.Itoa(gm.Turns) + " turns."
}

func outcomeFor(gm *Game, id uint64) string {
	if !gm.Done {
		return "pending"
	}
	if gm.Winner == rules.Draw {
		return "draw"
	}
	if (gm.Winner == rules.WinA) == (gm.A == id) {
		return "won"
	}
	return "lost"
}

func playLink(a, b uint64, m int) string {
	return txlink.Realm("gno.land"+self).Call("PlayPair", "a", u(a), "b", u(b), "m", strconv.Itoa(m), "n", "40")
}

// self is this realm's web path. It is a constant so links stay right when
// another realm calls Render.
const self = "/r/g1nx9tjlhjs6ndr3lcfrkqa0hdardjn2twv4vw4d/rfrh1/arena/v1"

func link(p string) string {
	base := self
	if p == "" {
		return base
	}
	return base + ":" + p
}

func webPath(pkg string) string { return strings.TrimPrefix(pkg, "gno.land") }

func u(id uint64) string { return strconv.FormatUint(id, 10) }

func splitPage(path string) (string, int) {
	i := strings.Index(path, "?page=")
	if i < 0 {
		return path, 0
	}
	p, err := strconv.Atoi(path[i+6:])
	if err != nil || p < 0 {
		p = 0
	}
	return path[:i], p
}

func pager(route string, page, total int) string {
	s := "\n"
	if page > 0 {
		s += "[newer](" + link(route) + "?page=" + strconv.Itoa(page-1) + ") "
	}
	if (page+1)*pageSize < total {
		s += "[older](" + link(route) + "?page=" + strconv.Itoa(page+1) + ")"
	}
	return s + "\n"
}

func notFound() string { return "# Not found\n\n[Home](" + link("") + ")\n" }

func max0(n int) int {
	if n < 0 {
		return 0
	}
	return n
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

// sortBots is an insertion sort; the league holds at most maxBots bots.
func sortBots(list []*Bot, less func(x, y *Bot) bool) {
	for i := 1; i < len(list); i++ {
		for j := i; j > 0 && less(list[j], list[j-1]); j-- {
			list[j], list[j-1] = list[j-1], list[j]
		}
	}
}

